        public dynamic Login_GetPassword(string userId, string otpType)
        {
            GetOtpResponseFP resModel = new GetOtpResponseFP();
            try
            {
                resModel.status = "failed";
                objUtility.CreateOTPMasterTable();
                string Strsql = "select count(0) from OTP_Master with (NoLock) where OTP_ClientCode='" + userId + "' and OTP_Product='TradeWeb' and OTP_Type = '" + otpType + "' and CAST(OTP_SentDate AS DATETIME) + CAST(OTP_SentTime AS DATETIME) >= DATEADD(MINUTE, -15, GETDATE())";
                DataTable dtCheck = objUtility.OpenDataTable(Strsql);
                if (dtCheck.Rows.Count > 0)
                {
                    double intPwdAttempt = Conversion.Val(objUtility.GetSysParmSt("PWDLOCKEDATM", ""));
                    if (intPwdAttempt == 0)
                    {
                        intPwdAttempt = 10;
                    }
                    if (Convert.ToInt32(dtCheck.Rows[0][0]) >= intPwdAttempt)
                    {
                        resModel.message = "You have exceeded maximum attempts permitted.Please try after sometime.";
                        return resModel;
                    }
                }

                string result = Login_GetPassword_Execute(userId, otpType); //"select cm_mobile from Client_master with (nolock) where cm_cd='" + userId + "'  and cm_pwd='" + password + "'";
                resModel.message = result;
                if (result.Contains("OTP sent to your registered mobile"))
                {
                    resModel.status = "success";

                    int intPwdMaxLength = Convert.ToInt16(objUtility.fnFireQueryTradeWeb("sysobjects a,syscolumns b", "b.Length", "a.id=b.id and a.name='Client_master' and b.name", "cm_pwd", true));
                    double intLastPass = Conversion.Val(objUtility.GetWebParameter("PWDSAMECHK"));
                    int intMinChar = 0;
                    string strAlphaNum = "", addMessage = "";

                    if (_configuration["IsTradeWeb"] == "O")
                    {
                        intMinChar = Convert.ToInt16(objUtility.GetSysParmSt("PWDMINCHR", ""));
                        strAlphaNum = objUtility.GetSysParmSt("PWDALPHANUM", "");
                        resModel.isAlphaNum = strAlphaNum;
                    }

                    if (strAlphaNum.Trim() == "Y")
                    {
                        addMessage += "<strong>Your Password must:<ol> <li><strong>Contain at least one letter (A-Z or a-z)</strong></li><li><strong>Contain at least one digit (0-9)</strong></li><li><strong>Contain at least one special character (e.g., !, @, #, $, etc.)</strong></li></strong></ol>";
                    }

                    addMessage += "<strong>Additional Guidelines:</strong><br />";
                    addMessage += "<ol><li>Maximum length: <strong>" + intPwdMaxLength + " characters</strong></li>";
                    resModel.maxLength = intPwdMaxLength;
                    if (intMinChar > 0)
                    {
                        addMessage += "<li>Minimum length: <strong>" + intMinChar + " characters</strong></li>";
                        resModel.minLength = intMinChar;
                    }
                    if (intLastPass > 0)
                    {
                        addMessage += "<li><strong>You cannot reuse your last " + intLastPass + " passwords.</strong></li>";
                    }
                    addMessage += "</ol>";
                    resModel.additionalMessage = addMessage;
                }
                return resModel;
            }
            catch (Exception ex)
            {
                resModel.message = ex.Message.ToString();
                return resModel;
            }
        }

