        public dynamic ChangePassword(string clientCd, string compCode, string OldPwd, string NewPwd)
        {
            try
            {
                string strLastLoginDt = "", Strsql = "", strDPID = "";
                if (string.IsNullOrEmpty(NewPwd))
                {
                    return "New password should not be blank!";
                }
                double intLastPass = Conversion.Val(objUtility.GetWebParameter("PWDSAMECHK"));
                if (intLastPass > 0)
                {
                    if (!objUtility.fnchkTable("Password_history"))
                    {
                        Strsql = "CREATE TABLE Password_history(";
                        Strsql += "[ph_srno] [numeric](18, 0) IDENTITY(1,1) NOT NULL,";
                        Strsql += "[ph_dpid] [char](8) NOT NULL,";
                        Strsql += "[ph_code] [char](8) NOT NULL,";
                        Strsql += "[ph_logintype] [char](1) NOT NULL,";
                        Strsql += "[ph_password] [char](10) NOT NULL,";
                        Strsql += "[mkrdt] [char](8) NOT NULL";
                        Strsql += ")";
                        objUtility.ExecuteSQL(Strsql);
                    }
                }

                if (_configuration["IsTradeWeb"] == "C" || _configuration["IsTradeWeb"] == "E")
                {
                    string strcode = Strings.UCase(Strings.Left(clientCd.Trim(), 3));
                    if ((Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects", "count(*)", "name", "GroupLogins", true)) == 1) && ((strcode == "GR/") || (strcode == "BR/") || (strcode == "FM/")))
                    {
                        string strPwdSetting = objUtility.fnFireQueryTradeWeb("webparameter", "sp_sysvalue", "sp_parmcd", "PWDSETTING", true);
                        if (strPwdSetting != "")
                        {
                            string strPwdMinLen = strPwdSetting.Split('/')[0];
                            string strPwdFormat = strPwdSetting.Split('/')[1];
                            if (NewPwd.Trim().Length < Convert.ToInt32(strPwdMinLen))
                            {
                                return "Password should contain minimum " + strPwdMinLen + " characters.";
                            }
                            if (strPwdFormat.Trim() == "Y")
                            {
                                int intPwdAlphaCnt = 0;
                                int intPwdNumCnt = 0;
                                int intPwdSplCnt = 0;
                                string strNewPwd = NewPwd.Trim();
                                for (int i = 0; i <= strNewPwd.Length - 1; i++)
                                {
                                    if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 65 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 90)
                                    {
                                        intPwdAlphaCnt++;
                                    }
                                    else if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 97 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 122)
                                    {
                                        intPwdAlphaCnt++;
                                    }
                                    else if (Strings.Asc(strNewPwd.Substring(i, 1)) >= 48 && Strings.Asc(strNewPwd.Substring(i, 1)) <= 57)
                                    {
                                        intPwdNumCnt++;
                                    }
                                    else
                                    {
                                        intPwdSplCnt++;
                                    }
                                }
                                if (intPwdNumCnt == 0)
                                {
                                    return "Password should contain at least one number.";
                                }
                                if (intPwdAlphaCnt == 0)
                                {
                                    return "Password should contain at least one Alphabet.";
                                }
                                if (intPwdSplCnt == 0)
                                {
                                    return "Password should contain at least one special character.";
                                }
                            }
                        }

                        string strGroupType = strcode;
                        string strGroupCode = Strings.UCase(Convert.ToString(clientCd.ToUpper().Replace(strGroupType, "")));

                        Strsql = "select gl_Code from GroupLogins where gl_Code='" + strGroupCode.Trim() + "' and gl_Pwd ='" + OldPwd + "'";
                        Strsql += " and gl_Type='" + Strings.UCase(Strings.Left(strGroupType.Trim(), 1)) + "'";

                        DataSet ObjDsPwd2 = new DataSet();
                        ObjDsPwd2 = objUtility.OpenDataSet(Strsql);

                        if (ObjDsPwd2.Tables[0].Rows.Count > 0)
                        {
                            Strsql = " update GroupLogins set ";
                            Strsql += " gl_Pwd ='" + NewPwd + "'";
                            Strsql += " where gl_Code ='" + strGroupCode.Trim() + "' and gl_Pwd ='" + OldPwd + "'";
                            Strsql += " and gl_Type='" + Strings.UCase(Strings.Left(strGroupType.Trim(), 1)) + "'";
                            objUtility.ExecuteSQL(Strsql);
                            return "Password has been changed successfully!";
                        }
                        else
                        {
                            return "Invalid Current Password!";
                        }
                    }
                }
                else
                {
                    if (_configuration["IsTradeWeb"] == "O")
                    {
                        double intMinChar = Conversion.Val(objUtility.GetSysParmSt("PWDMINCHR", ""));
                        string strAlphaNum = objUtility.GetSysParmSt("PWDALPHANUM", "");

                        if (intMinChar > 0)
                        {
                            if (NewPwd.Length < intMinChar)
                            {
                                return "Password should contain minimum " + intMinChar + " characters.";
                            }
                        }
                        if (strAlphaNum.Trim() == "Y")
                        {
                            int intPwdAlphaCnt = 0;
                            int intPwdNumCnt = 0;
                            int intPwdSplCnt = 0;

                            for (int i = 0; i <= NewPwd.Length - 1; i++)
                            {
                                if (Strings.Asc(NewPwd.Substring(i, 1)) >= 65 && Strings.Asc(NewPwd.Substring(i, 1)) <= 90)
                                {
                                    intPwdAlphaCnt++;
                                }
                                else if (Strings.Asc(NewPwd.Substring(i, 1)) >= 97 && Strings.Asc(NewPwd.Substring(i, 1)) <= 122)
                                {
                                    intPwdAlphaCnt++;
                                }
                                else if (Strings.Asc(NewPwd.Substring(i, 1)) >= 48 && Strings.Asc(NewPwd.Substring(i, 1)) <= 57)
                                {
                                    intPwdNumCnt++;
                                }
                                else
                                {
                                    intPwdSplCnt++;
                                }
                            }
                            string errorMsg = "";
                            if (intPwdNumCnt == 0)
                            {
                                errorMsg = "Password should contain at least one number.";
                            }
                            if (intPwdAlphaCnt == 0)
                            {
                                errorMsg += "\n Password should contain at least one Alphabet.";
                            }
                            if (intPwdSplCnt == 0)
                            {
                                errorMsg += "\n Password should contain at least one special character.";
                            }
                            if (errorMsg != "")
                            {
                                return errorMsg;
                            }
                        }
                    }

                    Strsql = "select cm_cd,cm_pwd from client_master where cm_cd='" + clientCd + "'";
                    DataSet ObjDsPwd = new DataSet();
                    ObjDsPwd = objUtility.OpenDataSet(Strsql);
                    if (ObjDsPwd.Tables[0].Rows.Count > 0)
                    {
                        strLastLoginDt = objUtility.fnFireQueryTradeWeb("Client_master", "cm_lastlogindt", "cm_cd", clientCd, true);
                        if (ObjDsPwd.Tables[0].Rows[0]["cm_pwd"].ToString().Trim() == OldPwd.ToString().Trim())
                        {
                            if (intLastPass > 0)
                            {
                                if (InvalidPassword(intLastPass, strDPID, clientCd, NewPwd))
                                {
                                    return "You cannot use any of the previous " + intLastPass + " passwords. Please set a different password.!";
                                }
                            }
                            Strsql = " update Client_master set cm_pwd='" + NewPwd.Trim() + "' where cm_cd='" + clientCd + "'";
                            Strsql = Strsql + " and cm_pwd='" + OldPwd.Trim() + "'";
                            objUtility.ExecuteSQL(Strsql);

                            if (_configuration["IsTradeWeb"] != "O") //not live
                            {
                                Strsql = "Update LoginDetails set lg_lastLoginDt='" + strLastLoginDt + "',lg_RsetPwd='Y',lg_ChangePwd='Y',lg_LastRSetDt='" + DateTime.Now.ToString("yyyyMMdd").Trim() + "' where lg_cmcd='" + clientCd + "' and lg_companycode='" + compCode + "'";
                                objUtility.ExecuteSQL(Strsql);
                            }
                            if (intLastPass > 0)
                            {
                                Strsql = "Insert into Password_history(ph_dpid, ph_code, ph_logintype, ph_password, mkrdt) values('" + strDPID + "', '" + clientCd + "', 'C', '" + NewPwd + "', '" + DateTime.Now.ToString("yyyyMMdd") + "')";
                                objUtility.ExecuteSQL(Strsql);
                            }
                            return "Password has been changed successfully!";
                        }
                        else
                        {
