        public static string GetHtmlFromUrl(string url)
        {
            if (string.IsNullOrEmpty(url))
                throw new ArgumentNullException("url", "Parameter is null or empty");

            string html = "";
            HttpWebRequest request = GenerateHttpWebRequest(url);
            using (HttpWebResponse response = (HttpWebResponse)request.GetResponse())
            {
                // Get the response stream.
                Stream responseStream = response.GetResponseStream();
                // Use a stream reader that understands UTF8.
                using (StreamReader reader =
                new StreamReader(responseStream, Encoding.UTF8))
                {
                    html = reader.ReadToEnd();
                }
            }
            return html;
        }
        public static HttpWebRequest GenerateHttpWebRequest(string UriString)
        {
            // Get a Uri object.
            Uri Uri = new Uri(UriString);
            // Create the initial request.
            HttpWebRequest httpRequest = (HttpWebRequest)WebRequest.Create(Uri);
            // Return the request.
            return httpRequest;
        }
        public dynamic GetUserDetais(string userId)
        {
            try
            {
                string qury = "";
                if (_configuration["IsTradeWeb"] == "T")
                {
                    if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects", "count(*)", "name", "Client_AdditionalDetail", true)) > 0)
                    {
                        qury = "Select cm_cd as ClientCode,LTrim(RTrim(cm_name)) as ClientName,LTrim(RTrim(cm_add1)) As Address1, LTrim(RTrim(cm_add2)) As Address2, LTrim(RTrim(cm_add3)) As Address3, ";
                        qury += " LTrim(RTrim(cm_add4)) as Address4, LTrim(RTrim(cm_pincode)) as Pincode, LTrim(RTrim(cm_email)) as Email, LTrim(RTrim(cm_mobile)) as Mobile, LTrim(RTrim(cm_tele1)) as Telephone1, LTrim(RTrim(cm_tele2)) as Telephone2, LTrim(RTrim(ca_state)) as State, LTrim(RTrim(ca_country)) as Country, LTrim(RTrim(cm_panno)) as PanNo, ca_nominee, ca_blsavingcd, ca_chgsscheme, ca_sech_name, ca_thih_name, cm_groupname, cm_familyname, ca_branchname, ";
                        qury += " isNull((select bt_description from Beneficiary_type where bt_code=ca_clienttype),'') BenType,isNull((select bs_description from Beneficiary_status where bs_code=ca_active),'') as Status ";
                        qury += " from client_master with (nolock) left outer join Client_AdditionalDetail with (nolock) on cm_cd=ca_cmcd where cm_cd='" + userId + "' ";
                    }
                }
                else
                {
                    qury = "Select cm_cd as ClientCode, LTrim(RTrim(cm_name)) as ClientName , LTrim(RTrim(cm_add1)) As Address1, LTrim(RTrim(cm_add2)) As Address2, LTrim(RTrim(cm_add3)) As Address3, LTrim(RTrim(cm_add4)) as Address4, LTrim(RTrim(cm_pincode)) as Pincode, LTrim(RTrim(cm_state)) as State, LTrim(RTrim(cm_pcountry)) as Country, LTrim(RTrim(cm_email)) as Email, LTrim(RTrim(cm_mobile)) as Mobile, LTrim(RTrim(cm_tele1)) as Telephone1, LTrim(RTrim(cm_tele2)) as Telephone2 , LTrim(RTrim(cm_panno)) as PanNo, LTrim(RTrim(bk_name)) as BankName, LTrim(RTrim(ba_actno)) as BankAccountNo, LTrim(RTrim(ba_micr)) as MICR, LTrim(RTrim(ba_ifsccode)) as IFSC, LTrim(RTrim(da_dpid)) as DPID, LTrim(RTrim(da_actno)) as DematAccountNo " +
                              " ,case cm_grossincome when 1 then 'Below Rs. 1  Lac' when 2 then 'Btw Rs. 1 to Rs. 5 Lacs' when 3 then 'Btw Rs. 5 to Rs. 10 Lacs' when 4 then 'Btw Rs. 10 to Rs. 25 Lacs' when 5 then 'Btw Rs. 25 Lacs to Rs. 1 Crore' when 6 then 'More than Rs. 1 Crore' else '' end as Income " +
                              " ,(Case When (select Count(0) from Client_details where substring(ce_companycode,3,1) in ('F','K','X' ) and ce_regDt<>'' and ce_clientcd='" + userId + "')>0 Then 'true' else 'false' end) as GrossIncomeProof " +
                              " ,Case cm_freezeyn when 'A' Then 'Freeze for All' when 'B' then 'Freeze for Branches' when 'Y' then 'Freeze for Trades' else 'Active' end as Status " +
                              " From client_master,client_info,Bankact,Bank_master,Dematact with (nolock) where cm_cd=cm2_cd and cm_cd='" + userId + "' and da_clientcd='" + userId + "' and da_defaultyn='y' and ba_clientcd='" + userId + "' and ba_default='y' and ba_micr=bk_micr  and ba_ifsccode = bk_IFCCode;";
                }
                var ds = CommonRepository.FillDataset(qury);
                if (ds != null)
                {
                    if (ds.Tables.Count > 0)
                    {
                        DataTable Dt = new DataTable();
                        Dt = ds.Tables[0];
                        if (objUtility.GetSysParmSt("MaskKeyInfo", "") != "N")
                        {
                            if (Dt.Rows[0]["Mobile"].ToString().Trim() != "")
                            {
                                Dt.Rows[0]["Mobile"] = Strings.Mid(Dt.Rows[0]["Mobile"].ToString().Trim(), 1, 2) + "xxxx" + Strings.Mid(Dt.Rows[0]["Mobile"].ToString().Trim(), 7);
                            }
                            if (Dt.Rows[0]["Telephone1"].ToString().Trim() != "")
                            {
                                Dt.Rows[0]["Telephone1"] = (Dt.Rows[0]["Telephone1"].ToString().Trim().Length > 8 ? "xxxxxx" : "xxxx") + Strings.Right(Dt.Rows[0]["Telephone1"].ToString().Trim(), 4);
                            }
                            if (Dt.Rows[0]["Telephone2"].ToString().Trim() != "")
                            {
                                Dt.Rows[0]["Telephone2"] = (Dt.Rows[0]["Telephone2"].ToString().Trim().Length > 8 ? "xxxxxx" : "xxxx") + Strings.Right(Dt.Rows[0]["Telephone2"].ToString().Trim(), 4);
                            }
                            if (Dt.Rows[0]["Email"].ToString().Trim() != "")
                            {
                                string[] arEmailPart = Strings.Split(Dt.Rows[0]["Email"].ToString().Trim(), "@");
                                string strEmail = "";
                                if (arEmailPart[0].Length > 2)
                                {
                                    arEmailPart[0] = Strings.Mid(arEmailPart[0], 1, 2) + Strings.StrDup(arEmailPart[0].Length - 2, "x");
                                }
                                strEmail = arEmailPart[0] + "@";
                                if (arEmailPart[1].Contains("."))
                                {
                                    string[] arEmailPart2 = Strings.Split(arEmailPart[1], ".");
                                    for (int i = 0; i <= arEmailPart2.Length - 1; i++)
                                    {
                                        if (arEmailPart2[i].Length > 2)
                                        {
                                            arEmailPart2[i] = Strings.Mid(arEmailPart2[i], 1, 2) + Strings.StrDup(arEmailPart2[i].Length - 2, "x");
                                        }
                                        strEmail += arEmailPart2[i] + ".";
                                    }
                                    if (strEmail.EndsWith("."))
                                    {
                                        strEmail = Strings.Mid(strEmail, 1, strEmail.Length - 1);
                                    }
                                }
                                else
                                {
                                    if (arEmailPart[1].Length > 2)
                                    {
                                        arEmailPart[1] = Strings.Mid(arEmailPart[1], 1, 2) + Strings.StrDup(arEmailPart[1].Length - 2, "x");
                                    }
                                    strEmail += arEmailPart[1];
                                }
                                Dt.Rows[0]["Email"] = strEmail;
                            }
                            if (Dt.Rows[0]["PanNo"].ToString().Trim() != "")
                            {
                                Dt.Rows[0]["PanNo"] = "xx" + Strings.Mid(Dt.Rows[0]["PanNo"].ToString().Trim(), 3, 2) + "xx" + Strings.Mid(Dt.Rows[0]["PanNo"].ToString().Trim(), 7, 2) + "xx";
                            }
                        }
                        return Dt;
                    }
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

