                { StrMTFTRXIndex = "index(idx_MrgTdgFin_TRX_clientcd),"; }

                if (_configuration["IsTradeWeb"] == "O")//Live DB
                {
                    strsql = "select  rtrim(ss_name) as ScripNm,MTtd_scripcd, MTtd_Stlmnt,ltrim(rtrim(convert(char,convert(datetime,MTtd_dt),103)))as MTtd_dt, ";
                    strsql = strsql + "sum(MTtd_bqty) Bqty, convert(decimal(15,2),sum(MTtd_bqty*MTtd_rate)) BAmt, sum(MTtd_sqty) Sqty, convert(decimal(15,2),sum(MTtd_sqty*MTtd_rate)) SAmt, ";
                    strsql = strsql + "sum(MTtd_bqty-MTtd_sqty) NQty, convert(decimal(15,2),sum((MTtd_bqty-MTtd_sqty)*MTtd_rate)) NAmt ";
                    strsql = strsql + " from MrgTdgFin_TRX with (" + StrMTFTRXIndex + "nolock),securities with(nolock)";
                    strsql = strsql + " where MTtd_clientcd ='" + cm_cd + "' ";
                    strsql = strsql + "and MTtd_Stlmnt='" + td_stlmnt + "' and MTtd_dt between '" + FromDt + "' and '" + ToDt + "' and MTtd_scripcd = ss_cd group by ss_name,MTtd_scripcd, ";
                    strsql = strsql + "MTtd_Stlmnt,MTtd_dt order by ss_name,MTtd_scripcd,MTtd_Stlmnt ";
                }
                else
                {
                    strsql = "select  rtrim(ss_name) as ScripNm,MTtd_scripcd, MTtd_Stlmnt,ltrim(rtrim(convert(char,convert(datetime,MTtd_dt),103)))as MTtd_dt, ";
                    strsql = strsql + "sum(MTtd_bqty) Bqty, convert(decimal(15,2),sum(MTtd_bqty*MTtd_rate)) BAmt, sum(MTtd_sqty) Sqty, convert(decimal(15,2),sum(MTtd_sqty*MTtd_rate)) SAmt, ";
                    strsql = strsql + "sum(MTtd_bqty-MTtd_sqty) NQty, convert(decimal(15,2),sum((MTtd_bqty-MTtd_sqty)*MTtd_rate)) NAmt ";
                    strsql = strsql + " from MrgTdgFin_TRX with (" + StrMTFTRXIndex + "nolock),TPSecurities with(nolock)";
                    strsql = strsql + " where MTtd_clientcd ='" + cm_cd + "' ";
                    strsql = strsql + "and MTtd_Stlmnt='" + td_stlmnt + "' and MTtd_dt between '" + FromDt + "' and '" + ToDt + "' and MTtd_scripcd = ss_cd group by ss_name,MTtd_scripcd, ";
                    strsql = strsql + "MTtd_Stlmnt,MTtd_dt order by ss_name,MTtd_scripcd,MTtd_Stlmnt ";

                }

            }

            return strsql;
        }

        #endregion

        #region Ledger handler methods
        public DataTable Ledger_Summary(string userId, string type, string fromdate, string toDate)
        {

            if (String.IsNullOrEmpty(type))
                type = "";

            if (String.IsNullOrEmpty(fromdate))
                fromdate = "";

            if (String.IsNullOrEmpty(toDate))
                toDate = "";

            string strsql = "", strTCM = "";
            if (type == "" || type.ToUpper() == "1")
            {
                //if (_configuration["TCM"] == "True")
                //{
                strTCM = " AND  Rtrim(CES_Segment) <> 'Comm' ";
                //}
                strsql = strsql + "select 1 as Ord , 'Trading' as [Type], ld_clientcd as [ClientCode], sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end) OpeningBalance,sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) Debit, sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag     when 'D' then 0 else ld_amount end end) Credit, sum(ld_amount) Balance ,";
                strsql = strsql + " Rtrim(CES_Exchange) + '-' + CES_Segment [ExchSeg], ";
                strsql = strsql + " LD_DPID as CESCD , 1 as TypeCode";
                strsql = strsql + " from ledger with (nolock) , Companyexchangesegments with (nolock) where LD_DPID = CES_Cd and ld_clientcd='" + userId + "' and ld_dt <= '" + toDate + "' " + strTCM + " group by ld_dpid , ld_clientcd,CES_Exchange,CES_Segment";
                //strsql = strsql + " union all ";
                //strsql = strsql + " select  1 as Ord ,  'Trading-Margin' as [Type], ld_clientcd as [ClientCode], sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end) OpeningBalance,sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag  ";
                //strsql = strsql + " when 'D' then ld_amount else 0 end end) Debit, sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then 0 else ld_amount end end) Credit, sum(ld_amount) Balance, ";
                //strsql = strsql + " Rtrim(CES_Exchange) + '-' + CES_Segment [ExchSeg], ";
                //strsql = strsql + " LD_DPID as CompanyCode,2 as TypeCode";
                //strsql = strsql + " from ledger , Companyexchangesegments where LD_DPID = CES_Cd and ld_clientcd=(select distinct cm_brkggroup from client_master with (nolock) where cm_cd='" + userId + "') ";
                //strsql = strsql + " and ld_dt <= '" + toDate + "' group by ld_dpid , ld_clientcd,CES_Exchange,CES_Segment ";
            }
            //MTF ledger
            if (type == "" || type.ToUpper() == "3")
            {
                if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects", "count(*)", "name", "MrgTdgFin_TRX", true)) > 0)
                {
                    if (strsql.Length > 0)
                    {
                        strsql = strsql + " union all ";
                    }
                    strsql = strsql + "select  3 as Ord , 'MTF' as [Type], ld_clientcd [ClientCode], sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end) OpeningBalance,sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) Debit, sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag     when 'D' then 0 else ld_amount end end) Credit, sum(ld_amount) Balance ,";
                    strsql = strsql + " Rtrim(CES_Exchange) + '- MTF' [ExchSeg] , ";
                    strsql = strsql + " LD_DPID as CESCD,5 as TypeCode";
                    strsql = strsql + " from ledger with (nolock),MrgTdgFin_Clients with (nolock) , Companyexchangesegments with (nolock) where LD_DPID = CES_Cd and ld_clientcd='" + userId + objUtility.GetSysParmSt("MTFP_SUFFIX", "") + "' and ld_dt <= '" + toDate + "'";
                    strsql = strsql + " and ld_clientcd =  Rtrim(MTFC_CMCD) + '" + objUtility.GetSysParmSt("MTFP_SUFFIX", "") + "' ";
                    strsql = strsql + " group by ld_dpid , ld_clientcd , CES_Exchange ";
                }

            }
            // NBFC
            if (type == "" || type.ToUpper() == "4")
            {
                if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects", "count(*)", "name", "nbfc_clients", true)) > 0)
                {
                    if (strsql.Length > 0)
                    {
                        strsql = strsql + " union all ";
                    }
                    strsql += "select  4 as Ord ,  'NBFC' as [Type], ld_clientcd [ClientCode], sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end) OpeningBalance,sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) Debit, sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag     when 'D' then 0 else ld_amount end end) Credit, sum(ld_amount) Balance ,";
                    strsql += " 'NBFC' [ExchSeg],";
                    strsql += " 'NBFC' as CESCD,6 as TypeCode";
                    strsql = strsql + " from NBFC_Ledger with (nolock) where ld_clientcd='" + userId + "' and ld_dt <= '" + toDate + "' group by ld_dpid , ld_clientcd";

                }
            }
            //// Commex Commodity
            if (type == "" || type.ToUpper() == "2")
            {
                if (_configuration["Commex"] != null && _configuration["Commex"] != string.Empty)
                {

                    string StrCommexConn = objUtility.GetCommexConnectionNew(_configuration["Commex"]);
                    StrCommexConn = StrCommexConn + ".";
                    if (strsql.Length > 0)
                    {
                        strsql = strsql + " union all ";
                    }
                    if (_configuration["TCM"] == "True")
                    {
                        StrCommexConn = "";
                        strTCM = " AND  Rtrim(CES_Segment) = 'Comm' ";
                    }
                    strsql = strsql + " select  2 as Ord ,  'Commodity' as [Type], ld_clientcd [ClientCode], sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end) OpeningBalance,sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) Debit, sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then 0 else ld_amount end end) Credit, sum(ld_amount) Balance, ";
                    strsql = strsql + " Rtrim(CES_Exchange) + '-Comm' [ExchSeg] , ";
                    strsql = strsql + " Left(ld_DPID,2)+'X' as CESCD,3 as TypeCode";
                    strsql = strsql + " from " + StrCommexConn + "ledger with (nolock)," + StrCommexConn + "Companyexchangesegments with (nolock)";
                    strsql = strsql + " where LD_DPID = CES_Cd and ld_clientcd='" + userId + "' and ld_dt <= '" + toDate + "' " + strTCM;
                    strsql = strsql + " group by ld_dpid , ld_clientcd , CES_Exchange ";

                    //strsql = strsql + " union all ";
                    //strsql = strsql + " select  2 as Ord ,  'Commodity-Margin' as [Type], ld_clientcd [ClientCode], sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end) OpeningBalance,sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) Debit, sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then 0 else ld_amount end end) Credit, sum(ld_amount) Balance, ";
                    //strsql = strsql + " Rtrim(CES_Exchange) + '-Comm' [ExchSeg],";
                    //strsql = strsql + " Left(ld_DPID,2)+'X' as CESCD,4 as TypeCode";
                    //strsql = strsql + " from   " + StrCommexConn + ".ledger," + StrCommexConn + ".Companyexchangesegments";
                    //strsql = strsql + " where LD_DPID = CES_Cd and ld_clientcd=(select distinct cm_brkggroup from " + StrCommexConn + ".client_master where cm_cd='" + userId + "') and ld_dt <= '" + toDate + "' ";
                    //strsql = strsql + " group by ld_dpid , ld_clientcd , CES_Exchange ";
                }
            }

            /////// For below grid data for DP value
            if (objUtility.GetWebParameter("DPReports") == "Y")//live
            {
                char[] ArrSeparators = new char[1];
                ArrSeparators[0] = '/';
                if (_configuration["Cross"] != "")
                {
                    string[] ArrCross = _configuration["Cross"].Split(ArrSeparators);
                    strsql = strsql + (strsql != "" ? " Union all" : "");
                    strsql = strsql + " select 5 as Ord, 'DP' as Type,ld_clientcd as ClientCode, ";
                    strsql = strsql + " sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end)  as  OpenBal,";
                    strsql = strsql + " sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) as  Debit,";
                    strsql = strsql + " sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then 0 else ld_amount*-1 end end) as  Credit,";
                    strsql = strsql + " sum(ld_amount) as Closing , 'Depository Services-' + ld_clientcd  as ExchSeg,ld_clientcd as CESCD,8 as TypeCode";
                    strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".ledger with (nolock)," + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_master with (nolock) where cm_cd=ld_clientcd and cm_blsavingcd ='" + userId + "' and ld_dt <= '" + toDate + "' ";
                    strsql = strsql + "  group by  ld_clientcd ";
                }

                if (_configuration["Estro"] != "")
                {
                    string[] ArrEstro = _configuration["Estro"].Split(ArrSeparators);
                    strsql = strsql + (strsql != "" ? " Union all" : "");
                    strsql = strsql + " select 5 as Ord, 'DP' as Type,ld_clientcd as ClientCode, ";
                    strsql = strsql + " sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then ld_amount else 0 end)  as  OpenBal,";
                    strsql = strsql + " sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then ld_amount else 0 end end) as  Debit,";
                    strsql = strsql + " sum(case sign(datediff(d,'" + fromdate + "',ld_dt)) when -1 then 0 else case ld_debitflag when 'D' then 0 else ld_amount*-1 end end) as  Credit,";
                    strsql = strsql + " sum(ld_amount) as Closing , 'Depository Services-' + ld_clientcd  as ExchSeg,ld_clientcd as CESCD,8 as TypeCode";
                    strsql = strsql + " from " + ArrEstro[0].Trim() + "." + ArrEstro[1].Trim() + "." + ArrEstro[2].Trim() + ".ledger with (nolock)," + ArrEstro[0].Trim() + "." + ArrEstro[1].Trim() + "." + ArrEstro[2].Trim() + ".Client_master with (nolock) where cm_cd=ld_clientcd and cm_blsavingcd ='" + userId + "' and ld_dt <= '" + toDate + "' ";
                    strsql = strsql + "  group by  ld_clientcd ";
                }
            }

            strsql = "select * from ( " + strsql;
            strsql = strsql + " ) a ";
            strsql = strsql + " order by Ord, [Type],ClientCode,CESCD ";

            try
            {
                var ds = objUtility.OpenDataSet(strsql);
                if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                {
                    var data = ds.Tables[0];
                    return data;
                }
                return null; // List<string>();
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

