            {
                var ds = CommonRepository.FillDataset(strsql);
                if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                {
                    DataTable dt = new DataTable();
                    dt = ds.Tables[0];
                    foreach (DataRow ObjRow in dt.Rows)
                    {
                        if ((decimal)ObjRow["Amount"] < 0)
                        {
                            if (ObjRow["Particular"].ToString().Length > 2)
                            {
                                if (Strings.Left(ObjRow["Particular"].ToString().ToUpper(), 2) == "TO")
                                    ObjRow["Particular"] = "By " + Strings.Right(ObjRow["Particular"].ToString(), ObjRow["Particular"].ToString().Length - 2);
                                else if (Strings.Left(ObjRow["Particular"].ToString().ToUpper(), 2) != "BY")
                                    ObjRow["Particular"] = "By " + ObjRow["Particular"].ToString();
                            }
                        }
                        else
                        {
                            if (ObjRow["Particular"].ToString().Length > 2)
                                if (Strings.Left(ObjRow["Particular"].ToString().ToUpper(), 2) == "BY")
                                    ObjRow["Particular"] = "To " + Strings.Right(ObjRow["Particular"].ToString(), ObjRow["Particular"].ToString().Length - 2);
                                else if (Strings.Left(ObjRow["Particular"].ToString().ToUpper(), 2) != "TO")
                                    ObjRow["Particular"] = "To " + ObjRow["Particular"].ToString();
                        }

                        if (Strings.Right(ObjRow["CESCD"].ToString().Trim(), 1) == "C" && ObjRow["Documenttype"].ToString() == "B" && ObjRow["Particular"].ToString().IndexOf('/') == -1)
                        {
                            if (ObjRow["Particular"].ToString().Length > 2)
                            {
                                DataTable dtDate = objUtility.OpenDataTable("select SUBSTRING(se_endt,7,2)+'/'+ SUBSTRING(se_endt,5,2)+'/'+SUBSTRING(se_endt,3,2) as se_endt from settlements where se_stlmnt='" + ObjRow["Common"].ToString() + "'");
                                ObjRow["Particular"] = ObjRow["Particular"].ToString() + " (" + dtDate.Rows[0]["se_endt"].ToString() + ")";
                            }
                        }
                    }

                    return dt;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic Ledger_Year()
        {
            strsql = strsql + "select distinct ld_AccYear AccYear from Ledger";
            try
            {
                var ds = CommonRepository.FillDataset(strsql);
                if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                {
                    var json = ds.Tables[0];
                    return json;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

