                new LedgerTypeResponse { Id = 2, Value = "Commodity"},
                new LedgerTypeResponse { Id = 3, Value = "MTF"},
                new LedgerTypeResponse { Id = 4, Value = "NBFC"},
            };

            return ledgerTypes;
        }
        #endregion

        #region OutStanding Handler Method
        // For getting Outstanding data
        public dynamic OutStandingPosition(string userId, string AsOnDt, List<string> ExchSeg = null, bool blnBranch = false)
        {
            String Strsql = "";
            string strExSeg = "";
            string strCommExSeg = "";
            bool blnTradePlus = false;
            bool blnCommex = false;
            string StrTradesIndex = "";
            List<OutstandingPositionRes> response = new List<OutstandingPositionRes>();
            if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("sysobjects a, sysindexes b", "COUNT(0)", "a.id = b.id and a.name = 'trades' and b.name", "idx_trades_clientcd", true)) == 1)
            { StrTradesIndex = "index(idx_trades_clientcd),"; }

            if (_configuration["isTradeWeb"] == "O")
            {
                String StrCommexConn = objUtility.GetCommexConnection();

                if (ExchSeg != null)
                {
                    var lstExch = ExchSeg.Where(x => Strings.Right(x, 1) != "X").ToList();
                    var lstCommExch = ExchSeg.Where(x => Strings.Right(x, 1) == "X").ToList();
                    if (lstExch.Count > 0)
                    {
                        var fltr = objUtility.mfnReplaceForSQLInjection(Strings.Join(lstExch.ToArray(), "##"));
                        strExSeg = " and CES_Cd in ('" + fltr.Replace("##", "','") + "')";
                    }
                    if (lstCommExch.Count > 0)
                    {
                        var fltr = objUtility.mfnReplaceForSQLInjection(Strings.Join(lstCommExch.ToArray(), "##"));
                        strCommExSeg = " and CES_Cd in ('" + fltr.Replace("##", "','") + "')";
                    }
                }

                if (string.IsNullOrWhiteSpace(strExSeg) && string.IsNullOrWhiteSpace(strCommExSeg))
                {
                    blnTradePlus = true;
                    blnCommex = true;
                }
                else
                {
                    if (!string.IsNullOrWhiteSpace(strExSeg))
                    {
                        blnTradePlus = true;
                    }
                    if (!string.IsNullOrWhiteSpace(strCommExSeg))
                    {
                        blnCommex = true;
                    }
                }

                if (blnTradePlus)
                {
                    //Query To Fecth Record From TradePlus DataBase
                    Strsql = " Select cm_cd ClientCode,cm_name ClientName,case right(sm_prodtype,1) when 'F' then 'Future' else 'Option' end+ case td_segment when 'X' then '(Commodities)' when 'K' then ' (Currency)'  else ''end ";
                    Strsql = Strsql + " as [Type],ltrim(rtrim(sm_desc)) LongName,sm_sname ShortName,";
                    Strsql = Strsql + " sum(td_bqty) Buy, sum(td_sqty) Sell,sum(td_bqty-td_sqty) as Net,td_companycode+td_exchange+td_Segment CESCD, ";
                    Strsql = Strsql + " convert(decimal(15,2), case sum(td_bqty -td_sqty) when 0 then 0 else abs(sum((td_bqty -td_sqty)*td_rate)/sum(td_bqty-td_sqty)) end) AvgRate,";
                    Strsql = Strsql + " convert(decimal(15,2), (isnull((select ms_lastprice from Market_summary with (nolock) where ms_exchange = td_exchange and ms_Segment = td_Segment and ms_seriesid = td_seriesid and ms_dt = (select max(ms_dt) from Market_summary with (nolock) where ms_exchange = td_exchange and ms_Segment = td_Segment and ms_seriesid = td_seriesid and  ms_dt <= '" + AsOnDt + "')),0))) Closeprice,";
                    //Strsql = Strsql + " + case  when right(sm_prodtype,1) <> 'F' then  sm_strikeprice  else 0 end) ) Closeprice,";
                    Strsql = Strsql + " convert(decimal(15,2), (isnull((select ms_lastprice from Market_summary with (nolock) where ms_exchange = td_exchange and ms_Segment = td_Segment and ms_seriesid = td_seriesid ";
                    Strsql = Strsql + " and ms_dt = (select max(ms_dt) from Market_summary with (nolock) where ms_exchange = td_exchange and ms_Segment = td_Segment and ms_seriesid = td_seriesid and  ms_dt <= '" + AsOnDt + "')),0) ";
                    Strsql = Strsql + "  + case when right(sm_prodtype,1) <> 'F' then sm_strikeprice  else 0 end)	";
                    Strsql = Strsql + " *sum(td_bqty-td_sqty) * sm_multiplier ) Closing,";
                    Strsql = Strsql + " case sm_prodtype when 'IF' then 1 when 'EF' then 2 when 'IO' then 3 when 'EO' then 4 else 5 end SortOrder,";
                    Strsql = Strsql + " Rtrim(CES_Exchange) +'-'+CES_Segment ExchSeg,td_seriesid SeriesID, sm_multiplier Multiplier";
                    Strsql = Strsql + " from Trades with (" + StrTradesIndex + "nolock), Series_master with (nolock) , CompanyExchangeSegments, Client_master ";
                    Strsql = Strsql + " where td_companyCode+td_exchange+td_Segment = CES_Cd and td_seriesid=sm_seriesid and td_exchange = sm_exchange and td_Segment = sm_Segment and td_clientcd = cm_cd ";
                    if (blnBranch)
                    {
                        Strsql = Strsql + userId;
                    }
                    else
                    {
                        Strsql = Strsql + " and td_clientcd='" + userId + "' ";
                    }
                    if (strExSeg != "")
                    {
                        Strsql = Strsql + strExSeg;
                    }
                    Strsql = Strsql + " and td_dt <= '" + AsOnDt + "' and sm_expirydt >= '" + AsOnDt + "'";
                    Strsql = Strsql + " Group by td_companyCode,td_clientcd ,td_seriesid,td_exchange,td_Segment,sm_sname,sm_prodtype,sm_desc,sm_multiplier,sm_strikeprice,CES_Exchange,CES_Segment,cm_cd,cm_name  having sum(td_bqty-td_sqty)<>0 ";
                }

                string StrComTradesIndex = "";
                //Query To Fecth Record From Commex DataBase
                if ((objUtility.GetWebParameter("Commex") != null && objUtility.GetWebParameter("Commex") != string.Empty) && blnCommex)
                {
                    if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb(StrCommexConn + ".sysobjects a, " + StrCommexConn + ".sysindexes b", "COUNT(0)", "a.id = b.id and a.name = 'trades' and b.name", "idx_trades_clientcd", true)) == 1)
                    { StrComTradesIndex = "index(idx_trades_clientcd),"; }

                    if (Strsql != "")
                    {
                        Strsql = Strsql + " Union all";
                    }
                    Strsql = Strsql + " Select cm_cd ClientCode,cm_name ClientName,case right(sm_prodtype,1)when 'F' then 'Future (Commodities)' else 'Option (Commodities)' ";
                    Strsql = Strsql + " end as [Type],ltrim(rtrim(sm_desc)) LongName,sm_sname ShortName,sum(td_bqty) Buy,sum(td_sqty) Sell,sum(td_bqty-td_sqty) as Net,td_companycode+td_Exchange+'X' CESCD,";
                    Strsql = Strsql + " convert(decimal(15,2), case sum(td_bqty -td_sqty) when 0 then 0 else abs(sum((td_bqty -td_sqty)*td_rate)/sum(td_bqty-td_sqty)) end) AvgRate,";
                    Strsql = Strsql + " convert(decimal(15,2), (isnull((select ms_lastprice from " + StrCommexConn + ".Market_summary with (nolock) where ms_exchange = td_exchange and ms_seriesid = td_seriesid and ms_dt = (select max(ms_dt) from " + StrCommexConn + ".Market_summary with (nolock) where ms_exchange = td_exchange and ms_seriesid = td_seriesid and  ms_dt <= '" + AsOnDt + "')),0))) Closeprice, ";
                    //Strsql = Strsql + "  + case  when right(sm_prodtype,1) <> 'F' then  sm_strikeprice  else 0 end) ) Closeprice,";
                    Strsql = Strsql + " convert(decimal(15,2), (isnull((select ms_lastprice from " + StrCommexConn + ".Market_summary with (nolock) where ms_exchange = td_exchange and ms_seriesid = td_seriesid ";
                    Strsql = Strsql + " and ms_dt = (select max(ms_dt) from " + StrCommexConn + ".Market_summary with (nolock) where ms_exchange = td_exchange and ms_seriesid = td_seriesid and  ms_dt <= '" + AsOnDt + "')),0) ";
                    Strsql = Strsql + "  + case  when right(sm_prodtype,1) <> 'F' then sm_strikeprice  else 0 end)	";
                    Strsql = Strsql + "  *sum(td_bqty-td_sqty) * sm_multiplier ) Closing,";
                    Strsql = Strsql + " case sm_prodtype when 'CF'then 11 else 12 end SortOrder,";
                    Strsql = Strsql + " Rtrim(CES_Exchange) +'-Comm' ExchSeg,td_seriesid SeriesID,sm_multiplier Multiplier";
                    Strsql = Strsql + " from " + StrCommexConn + ".Trades with(" + StrComTradesIndex + "nolock), " + StrCommexConn + ".Series_master with (nolock) , " + StrCommexConn + ".CompanyExchangeSegments with (nolock), " + StrCommexConn + ".Client_master ";
                    Strsql = Strsql + " where td_companyCode+td_exchange+'F' = CES_Cd and td_seriesid=sm_seriesid and td_exchange = sm_exchange and td_clientcd = cm_cd ";
                    if (blnBranch)
                    {
                        Strsql = Strsql + userId;
                    }
                    else
                    {
                        Strsql = Strsql + " and td_clientcd='" + userId + "' ";
                    }
                    if (strCommExSeg != "")
                    {
                        Strsql = Strsql + strCommExSeg.Replace("X", "F");
                    }
                    Strsql = Strsql + " and td_dt <= '" + AsOnDt + "' and sm_expirydt > '" + AsOnDt + "'";
                    Strsql = Strsql + " Group by td_companyCode,td_clientcd ,td_seriesid,td_exchange,sm_sname,sm_prodtype,sm_desc,sm_multiplier,sm_strikeprice,CES_Exchange,cm_cd,cm_name  having sum(td_bqty-td_sqty)<>0 ";
                }
            }
            else //Connect to TradeWeb DataBase
            {
                Strsql = " Select cm_cd ClientCode,cm_name ClientName,case ot_exchange when 'N' then 1 else 2 end Td_order, case left(sm_sname,1) when 'F' then 'Future' else 'Option' end+case sm_prodtype when 'CF' then ' (Currency)' else '' end  as Type,ltrim(rtrim(sm_desc)) LongName,sm_sname ShortName,";
                Strsql = Strsql + " ot_bqty Buy,ot_sqty Sell,(ot_bqty-ot_sqty) as Net,ot_companycode+ot_exchange+ot_Segment CESCD,ot_companycode compcode, cast(ot_avgrate as decimal(15,2)) AvgRate,";
                Strsql = Strsql + " cast(ot_closeprice as decimal(15,2))Closeprice,";
                Strsql = Strsql + " cast(((ot_bqty-ot_sqty)*ot_closeprice*sm_multiplier)as decimal(15,2)) as Closing,";
                Strsql = Strsql + " case sm_prodtype when 'IF' then 1 when 'EF' then 2 when 'IO' then 3 when 'EO' then 4 else 5 end SortOrder,";
                Strsql = Strsql + " Rtrim(ot_exchange) +'-'+ot_Segment ExchSeg, convert(char,convert(datetime,ot_dt),103) ot_dt ,";
                Strsql = Strsql + " Case ot_segment when 'F' then case ot_exchange when 'B' then 'BSE' when 'N' then 'NSE' end ";
                Strsql = Strsql + " when 'K' then Case ot_exchange when 'B' then 'BSEFX' when 'N' then 'NSEFX' when 'M' then 'MCFFX' end ";
                Strsql = Strsql + " end  as strExchange, ";
                Strsql = Strsql + " ot_seriesid SeriesID,ot_exchange,ot_Segment";
                Strsql = Strsql + " from Foutstanding with (nolock), Series_master with (nolock),Client_master with (nolock) ";
                Strsql = Strsql + " where ot_clientcd = cm_cd and ot_seriesid=sm_seriesid and ot_exchange = sm_exchange and ot_Segment = sm_Segment and ot_clientcd='" + userId + "'";
                Strsql = Strsql + " union all";
                Strsql = Strsql + " Select cm_cd ClientCode,cm_name ClientName,3 Td_order,case left(sm_sname,1)when 'F' then 'Future (Commodities)' else 'Option (Commodities)'";
                Strsql = Strsql + " end as tdtype,ltrim(rtrim(sm_desc)) LongName,sm_sname,ot_bqty,ot_sqty,(ot_bqty-ot_sqty) as net,ot_companycode+ot_exchange+'' CESCD,ot_companycode compcode,";
                Strsql = Strsql + " cast(ot_avgrate as decimal(15,2))ot_avgrate,cast(ot_closeprice as decimal(15,2))ot_closeprice,";
                Strsql = Strsql + " cast(((ot_bqty-ot_sqty)*ot_closeprice*sm_multiplier)as decimal(15,2)) as Closing, case sm_prodtype when 'CF'";
                Strsql = Strsql + " then 11 else 12 end SortOrder,Rtrim(ot_exchange) +'-'+'' ExchSeg, convert(char,convert(datetime,ot_dt),103) ot_dt ,";
                Strsql = Strsql + " case ot_exchange when 'M' then 'M CX' when 'N' then 'NCDEX' when 'S' then 'NSEL' end as strExchange,ot_seriesid SeriesID,ot_exchange,'' ot_Segment";
                Strsql = Strsql + " from Coutstanding with (nolock),CSeries_master with (nolock),Client_master with (nolock) ";
                Strsql = Strsql + " where ot_clientcd = cm_cd and ot_seriesid=sm_seriesid and ot_exchange = sm_exchange and ot_clientcd='" + userId + "'";
                //Strsql = Strsql + " order by SortOrder,LongName";
            }

            Strsql = " select * from (" + Strsql + ") a order by ClientCode,ClientName,SortOrder,LongName";


            try
            {
                var ds = CommonRepository.FillDataset(Strsql);
                if (ds != null)
                {
                    if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                    {
                        DataTable dt = ds.Tables[0];
                        if (blnBranch)
                        {
                            var tempOutstandingPos = dt.AsEnumerable().Select(row => new TempOutstandingPositionRecords
                            {
                                ClientCode = row["ClientCode"].ToString().Trim(),
                                ClientName = row["ClientName"].ToString().Trim(),
                                Type = row["Type"].ToString().Trim(),
                                LongName = row["LongName"].ToString().Trim(),
                                ShortName = row["ShortName"].ToString().Trim(),
                                Buy = Convert.ToDouble(row["Buy"]),
                                Sell = Convert.ToDouble(row["Sell"]),
                                Net = Convert.ToDouble(row["Net"]),
                                CESCD = row["CESCD"].ToString().Trim(),
                                AvgRate = Convert.ToDouble(row["AvgRate"]),
                                Closeprice = Convert.ToDouble(row["Closeprice"]),
                                Closing = Convert.ToDouble(row["Closing"]),
                                SortOrder = Convert.ToInt16(row["SortOrder"]),
                                ExchSeg = Convert.ToString(row["ExchSeg"]),
                                SeriesID = Convert.ToDouble(row["SeriesID"]),
                                Multiplier = Convert.ToDouble(row["Multiplier"])
                            }).ToList();

                            var clientList = tempOutstandingPos.Select(x => x.ClientCode).Distinct().ToList();

                            foreach (var client in clientList)
                            {
                                var clientData = tempOutstandingPos.Where(x => x.ClientCode == client).ToList();
                                List<OutstandingPositionModel> outstanding = clientData.Select(row => new OutstandingPositionModel
                                {
                                    Type = row.Type.ToString().Trim(),
                                    LongName = row.LongName.ToString().Trim(),
                                    ShortName = row.ShortName.ToString().Trim(),
                                    Buy = Convert.ToDouble(row.Buy),
                                    Sell = Convert.ToDouble(row.Sell),
                                    Net = Convert.ToDouble(row.Net),
                                    CESCD = row.CESCD.ToString().Trim(),
                                    AvgRate = Convert.ToDouble(row.AvgRate),
                                    Closeprice = Convert.ToDouble(row.Closeprice),
                                    Closing = Convert.ToDouble(row.Closing),
                                    SortOrder = Convert.ToInt16(row.SortOrder),
                                    ExchSeg = Convert.ToString(row.ExchSeg),
                                    SeriesID = Convert.ToDouble(row.SeriesID),
                                    Multiplier = Convert.ToDouble(row.Multiplier)
                                }).ToList();

                                double dblSpanMrg = 0;
                                double dblExpMrg = 0;
                                string compCode = Strings.Left(outstanding.FirstOrDefault().CESCD.Trim(), 1);
                                Strsql = "Select fm_initialmargin,fm_ExposureValue From Fmargins Where Fm_Clientcd ='" + client + "' and fm_dt ='" + AsOnDt + "'";
                                Strsql += " and fm_companycode ='" + compCode + "' and fm_Segment <> 'C'";
                                dt = objUtility.OpenDataTable(Strsql);
                                if (dt.Rows.Count > 0)
                                {
                                    if (Convert.ToDouble(dt.Rows[0]["fm_initialmargin"]) > 0)
                                    {
                                        dblSpanMrg = Convert.ToDouble(dt.Rows[0]["fm_initialmargin"]);
                                    }
                                    if (Convert.ToDouble(dt.Rows[0]["fm_exposurevalue"]) > 0)
                                    {
                                        dblExpMrg = Convert.ToDouble(dt.Rows[0]["fm_exposurevalue"]);
                                    }
                                }

                                response.Add(new OutstandingPositionRes
                                {
                                    ClientCode = clientData.FirstOrDefault().ClientCode.Trim(),
                                    ClientName = clientData.FirstOrDefault().ClientName.Trim(),
                                    SpanMargin = dblSpanMrg,
                                    ExposureMargin = dblExpMrg,
                                    Data = outstanding
                                });
                            }

                            return response;
                        }
                        else
                        {
                            return dt;
                        }
                    }
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        //For getting Outstanding details data
        public dynamic OutStandingPosition_Detail(string userId, string seriesid, string CESCd)
        {
            try
            {
                string StrTradesIndex = "";

                string Strsql = string.Empty;

                if (CESCd.Substring(2, 1) == "X")
                {
                    Strsql = " select td_dt tradedt, sum(td_bqty) Buy, convert(decimal(15,2),sum(td_bqty*td_rate*sm_multiplier)) BuyAmount, sum(td_sqty) Sell, ";
                    Strsql = Strsql + " convert(decimal(15,2),sum(td_sqty*td_rate* sm_multiplier)) SellAmount, sum(td_bqty-td_sqty) Net, ";
                    Strsql = Strsql + "  convert(decimal(15,2), (sum((td_bqty-td_sqty)*td_rate* sm_multiplier)))  NetAmount ";
                    if (_configuration["IsTradeWeb"] == "O")//Connect to Live DataBase
                    {
                        string StrCommexConn = "";
                        string StrComTradesIndex = "";
                        StrCommexConn = objUtility.GetCommexConnection();
                        if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb(StrCommexConn + ".sysobjects a, " + StrCommexConn + ".sysindexes b", "COUNT(0)", "a.id = b.id and a.name = 'trades' and b.name", "idx_trades_clientcd", true)) == 1)
                        { StrComTradesIndex = "index(idx_trades_clientcd),"; }

                        Strsql = Strsql + " from " + StrCommexConn + ".trades with (" + StrComTradesIndex + "nolock), " + StrCommexConn + ".series_master with (nolock)";
                    }
                    else
                    {
                        string StrCTradesIndex = "";
                        if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("sysobjects a, sysindexes b", "COUNT(0)", "a.id = b.id and a.name = 'Ctrades' and b.name", "idx_Ctrades_clientcd", true)) == 1)
                        { StrCTradesIndex = "index(idx_Ctrades_clientcd),"; }

                        Strsql = Strsql + " from ctrades with (" + StrCTradesIndex + "nolock), cseries_master with (nolock)";
                    }
                    // Strsql = Strsql + " from trades with (" + StrTradesIndex + "nolock), series_master with (nolock) ";
                    Strsql = Strsql + " where td_clientcd='" + userId + "' and td_exchange=sm_exchange and td_seriesid=sm_seriesid ";
                    Strsql = Strsql + " and td_seriesid='" + seriesid + "' and td_exchange='" + CESCd.Substring(1, 1) + "'   and td_trxflag <> 'O' ";
                    //Strsql = Strsql + " and td_companycode='" + CESCd.Substring(0, 1) + "' ";
                    Strsql = Strsql + " group by td_dt";
                }
                else
                {
                    if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("sysobjects a, sysindexes b", "COUNT(0)", "a.id = b.id and a.name = 'trades' and b.name", "idx_trades_clientcd", true)) == 1)
                    { StrTradesIndex = "index(idx_trades_clientcd),"; }

                    Strsql = " select td_dt tradedt, sum(td_bqty) Buy, convert(decimal(15,2),sum(td_bqty*td_rate* sm_multiplier)) BuyAmount, sum(td_sqty) Sell, ";
                    Strsql = Strsql + " convert(decimal(15,2),sum(td_sqty*td_rate* sm_multiplier)) SellAmount, sum(td_bqty-td_sqty) Net, ";
                    Strsql = Strsql + "  convert(decimal(15,2), (sum((td_bqty-td_sqty)*td_rate*sm_multiplier)))  NetAmount ";
                    Strsql = Strsql + " from trades with (" + StrTradesIndex + "nolock), series_master with (nolock) where td_clientcd='" + userId + "' ";
                    Strsql = Strsql + " and td_exchange=sm_exchange and td_Segment=sm_Segment and td_seriesid=sm_seriesid ";
                    Strsql = Strsql + " and td_seriesid='" + seriesid + "' and td_exchange='" + CESCd.Substring(1, 1) + "' ";
                    Strsql = Strsql + " and td_trxflag <> 'O' ";
                    if (CESCd.Substring(2, 1) != "")
                    {
                        Strsql = Strsql + " and td_Segment='" + CESCd.Substring(2, 1) + "' ";
                    }
                    //Strsql = Strsql + " and td_companycode='" + CESCd.Substring(0, 1) + "' ";
                    Strsql = Strsql + " group by td_dt";
                }
                var ds = CommonRepository.FillDataset(Strsql);
                if (ds != null)
                {
                    if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                    {
                        var json = ds.Tables[0];
                        return json;
                    }
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

