        #region ProfitLoss Handler Method
        public dynamic ProfitLoss_Segment()
        {
            try
            {
                strsql = " Select Distinct CES_Segment as Segment, RIGHT(CES_Cd,1) CES_Cd From CompanyExchangeSegments Where CES_Segment not in ('MF') Order By RIGHT(CES_Cd,1) ";

                var dt = objUtility.OpenDataTable(strsql);
                if (dt.Rows.Count > 0)
                {
                    return dt;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
        public dynamic ProfitLoss_Exchange(string segment)
        {
            try
            {
                strsql = " Select Distinct CES_Exchange as Exchange From CompanyExchangeSegments  Where CES_Segment='" + segment + "'  ";

                var dt = objUtility.OpenDataTable(strsql);
                if (dt.Rows.Count > 0)
                {
                    return dt;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
        public dynamic ProfitLoss_Cash_Summary(string userId, string fromDate, string toDate)
        {
            try
            {
                SqlConnection con;
                using (var db = new DataContext())
                {
                    con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                    con.Open();
                    ProfitLoss_Cash_Process(userId, fromDate, toDate, con);

                    strsql = " select '1' as Ord, case td_flag When 'Y' Then 1 else 2 end Flag,ss_Lname ScripName,sum(td_bqty) Buy, convert(decimal(15,2),sum(td_bqty*td_rate)) BuyAmount ,  case when SUM(td_bqty) <> 0 then convert(decimal(15,2),sum(td_bqty*td_rate)/sum(td_bqty)) else 0 end BuyRate,  sum(td_sqty) Sell , convert(decimal(15,2),sum(td_sqty*td_rate)) SellAmount ,  case when SUM(td_sqty) <> 0 then convert(decimal(15,2),sum(td_sqty*td_rate)/sum(td_sqty)) else 0 end SellRate, ";
                    strsql += " convert(decimal(15,2), sum( case When td_flag <> 'X' Then ((td_sqty-td_bqty) *td_rate) else 0 end)) Realised,  ";
                    strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then (td_bqty-td_sqty)* ((Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) - td_rate) else 0 end)) UnRealised,  ";
                    strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_bqty-td_sqty)) else 0 end)) Net,  convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_sqty-td_bqty) * (Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) ) else 0 end))  NetAmount,  ";
                    strsql += " case When sum( case when td_flag = 'X'  Then (td_bqty-td_sqty) else 0 end) <> 0 then abs(convert(decimal(15,2),sum(Case When td_flag = 'X' Then (td_sqty-td_bqty)*(Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) else 0 end )/sum(td_bqty-td_sqty))) else 0 end NetRate, ";
                    strsql += " isnull(td_desc,'') TrdDlv,td_scripcd Scrip ";
                    strsql += " from ##VX,securities with(nolock) where td_scripcd=ss_cd ";
                    strsql += " Group by ss_Lname,case td_flag When 'Y' Then 1 else 2 end ,td_desc,td_scripcd ";
                    strsql += " Union all ";
                    strsql += " select '2' Ord,'','Charges' ic_desc,0,0,0,0,0,0,convert(decimal(15,2),sum(ic_amount)) * (-1),0,0,0,0 amt ,'','' from ##invcharges";
                    strsql += " where ic_amount > 0";
                    strsql += " order by Ord,ss_Lname,flag desc";
                    var ds = objUtility.OpenDataSetTmp(strsql, con);
                    if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                    {
                        var data = ds.Tables[0];
                        return data;
                    }
                    return null;
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic ProfitLoss_CashSummary(string clientWhere, string fromDate, string toDate, int stockValuation = 0)
        {
            try
            {
                SqlConnection con;
                using (var db = new DataContext())
                {
                    con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                    con.Open();
                    ProfitLoss_CashProcess(clientWhere, fromDate, toDate, con);

                    strsql = "update #VX set td_desc = CAse td_flag when 'Y' then 'Square off' else 'Delivery' end ";
                    objUtility.ExecuteSQLTmp(strsql, con);

                    strsql = "select '1' as Ord,td_scripcd,td_scripnm";
                    if (_configuration["IsTradeWeb"] == "O")//Live DB
                    {

                        strsql = " select td_clientcd, '1' as Ord, case td_flag When 'Y' Then 1 else 2 end Flag,ss_Lname ScripName ,''Settlement ,  sum(td_bqty) BuyQty, convert(decimal(15,2),sum(td_bqty*td_rate)) BuyValue ,  case when SUM(td_bqty) <> 0 then convert(decimal(15,2),sum(td_bqty*td_rate)/sum(td_bqty)) else 0 end BuyRate,  sum(td_sqty) SellQty , convert(decimal(15,2),sum(td_sqty*td_rate)) SellValue ,  case when SUM(td_sqty) <> 0 then convert(decimal(15,2),sum(td_sqty*td_rate)/sum(td_sqty)) else 0 end SellRate, ";
                        if (stockValuation == 0)
                        {
                            strsql += " convert(decimal(15,2), sum( case When td_flag <> 'X' Then ((td_sqty-td_bqty) *td_rate) else 0 end)) Realized_PL,  ";
                            strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then (td_bqty-td_sqty)* ((Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) - td_rate) else 0 end)) UnRealized_PL,  ";
                        }
                        else if (stockValuation == 2)
                        {
                            strsql += " 0 PL, ";
                        }
                        strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_bqty-td_sqty)) else 0 end)) NetQty, ";
                        if (stockValuation == 0)
                        {
                            strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_sqty-td_bqty) * (Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) ) else 0 end))  Amount, ";
                            strsql += " case When sum( case when td_flag = 'X'  Then (td_bqty-td_sqty) else 0 end) <> 0 then abs(convert(decimal(15,2),sum(Case When td_flag = 'X' Then (td_sqty-td_bqty)*(Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) else 0 end )/sum(td_bqty-td_sqty))) else 0 end Rate, ";
                        }
                        else if (stockValuation == 2)
                        {
                            strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then Case when td_bqty > td_sqty then td_bqty*td_rate else td_sqty*td_rate end else 0 end))  Amount, ";
                            strsql += " case when sum(td_bqty) > sum(td_sqty) then convert(decimal(15,2),sum(td_bqty*td_rate) / (sum(td_bqty) - sum(td_sqty))) else case when sum(td_bqty) < sum(td_sqty) then convert(decimal(15,2),sum(td_sqty*td_rate) / (sum(td_sqty) - sum(td_bqty))) else 0 end end Cost, ";
                        }
                        strsql += " isnull(td_desc,'') TradeType,td_scripcd ScripCode  ";
                        strsql += " from #VX,securities with(nolock) where td_scripcd=ss_cd ";
                        strsql += " Group by ss_Lname,case td_flag When 'Y' Then 1 else 2 end ,td_desc,td_scripcd,td_clientcd ";
                        strsql += " Union all ";
                        strsql += " select ic_clientcd, '2' Ord,'', ic_desc,'',0,0,0,0,0,0,convert(decimal(15,2),sum(ic_amount)) * (-1)," + (stockValuation == 0 ? "0," : "") + "0,0,0 amt ,'','' from #invcharges";
                        strsql += " where ic_amount > 0 group by ic_clientcd,ic_desc";
                        //strsql += " group by ic_desc ";
                        strsql += " order by td_clientcd,Ord,ss_Lname,Flag desc";

                    }
                    else
                    {

                        strsql = " select td_clientcd, '1' as Ord, case td_flag When 'Y' Then 1 else 2 end Flag,ss_Lname ScripName ,''Settlement , sum(td_bqty) BuyQty, convert(decimal(15,2),sum(td_bqty*td_rate)) BuyValue ,  case when SUM(td_bqty) <> 0 then convert(decimal(15,2),sum(td_bqty*td_rate)/sum(td_bqty)) else 0 end BuyRate,  sum(td_sqty) SellQty , convert(decimal(15,2),sum(td_sqty*td_rate)) SellValue ,  case when SUM(td_sqty) <> 0 then convert(decimal(15,2),sum(td_sqty*td_rate)/sum(td_sqty)) else 0 end SellRate, ";
                        strsql += " convert(decimal(15,2), sum( case When td_flag <> 'X' Then ((td_sqty-td_bqty) *td_rate) else 0 end)) Realized_PL,  ";
                        strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then (td_bqty-td_sqty)* ((Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) - td_rate) else 0 end)) UuRealized_PL,  ";
                        strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_bqty-td_sqty)) else 0 end)) NetQty,  convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_sqty-td_bqty) * (Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) ) else 0 end))  Amount,  ";
                        strsql += " case When sum( case when td_flag = 'X'  Then (td_bqty-td_sqty) else 0 end) <> 0 then abs(convert(decimal(15,2),sum(Case When td_flag = 'X' Then (td_sqty-td_bqty)* ";
                        strsql += " (Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) else 0 end )/sum(td_bqty-td_sqty))) else 0 end Rate, isnull(td_desc,'') TradeType,td_scripcd ScripCode ";
                        strsql += " from #VX,TPSecurities with (nolock) where td_scripcd=ss_cd ";
                        strsql += " Group by ss_Lname,case td_flag When 'Y' Then 1 else 2 end ,td_desc,td_scripcd,td_clientcd ";
                        strsql += " Union all ";
                        strsql += " select ic_clientcd, '2' Ord,'','Charges' ic_desc,'',0,0,0,0,0,0, convert(decimal(15,2),sum(ic_amount)) * (-1),0,0,0,0 amt ,'','' from #invcharges";
                        strsql += " where ic_amount > 0 group by ic_clientcd";
                        //strsql += " group by ic_desc ";
                        strsql += " order by td_clientcd,Ord,ss_Lname,Flag desc";
                    }
                    var ds = objUtility.OpenDataSetTmp(strsql, con);
                    if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                    {
                        if (stockValuation == 2)
                        {
                            foreach (DataRow dr in ds.Tables[0].Rows)
                            {
                                if (dr["Ord"].ToString().Trim() == "1")
                                {
                                    if (Convert.ToDouble(dr["BuyQty"]) < Convert.ToDouble(dr["SellQty"]))
                                    {
                                        dr["PL"] = Convert.ToDecimal(Convert.ToDouble(dr["SellValue"]) - (Convert.ToDouble(dr["Amount"])) - Convert.ToDouble(dr["BuyValue"])).ToString("N");
                                    }
                                    else
                                    {
                                        dr["PL"] = Convert.ToDecimal(Convert.ToDouble(dr["SellValue"]) - (Convert.ToDouble(dr["BuyValue"])) + Convert.ToDouble(dr["Amount"])).ToString("N");
                                    }
                                }
                            }
                        }
                        var data = ds.Tables[0];
                        return data;
                    }
                    return null;
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

