        #region profitLoss combine handler method

        public dynamic ProfitLoss_Combined(string userId, List<ProfitLossCombinedInputModel> model)
        {
            List<ProfitLossCombinedModel> profitLossCombinedList = new List<ProfitLossCombinedModel>();

            foreach (var profitLossCombined in model)
            {
                ProfitLossCombinedModel result = new ProfitLossCombinedModel();

                result.CashSummary = ProfitLoss_Cash_CombineSummary(userId, objUtility.mfnReplaceForSQLInjection(profitLossCombined.FromDate), objUtility.mfnReplaceForSQLInjection(profitLossCombined.ToDate));

                result.FoSummary = ProfitLoss_FO_CombineSummary(userId, objUtility.mfnReplaceForSQLInjection(profitLossCombined.Exchange), objUtility.mfnReplaceForSQLInjection(profitLossCombined.Segment), objUtility.mfnReplaceForSQLInjection(profitLossCombined.FromDate), objUtility.mfnReplaceForSQLInjection(profitLossCombined.ToDate));

                result.CommoditySummary = ProfitLoss_Commodity_CombineSummary(userId, objUtility.mfnReplaceForSQLInjection(profitLossCombined.Exchange), objUtility.mfnReplaceForSQLInjection(profitLossCombined.FromDate), objUtility.mfnReplaceForSQLInjection(profitLossCombined.ToDate));

                profitLossCombinedList.Add(result);
            }

            return profitLossCombinedList;
        }

        public dynamic ProfitLoss_Cash_CombineSummary(string userId, string fromDate, string toDate)
        {
            try
            {
                SqlConnection con;
                using (var db = new DataContext())
                {
                    con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                    con.Open();
                    ProfitLoss_Cash_Process(userId, fromDate, toDate, con);

                    strsql = " select '1' as Ord, case td_flag When 'Y' Then 1 else 2 end Flag,ss_Lname ScripName,'' Settlement, sum(td_bqty) BuyQty, convert(decimal(15,2),sum(td_bqty*td_rate)) BuyValue ,  case when SUM(td_bqty) <> 0 then convert(decimal(15,2),sum(td_bqty*td_rate)/sum(td_bqty)) else 0 end BuyRate,  sum(td_sqty) Sell , convert(decimal(15,2),sum(td_sqty*td_rate)) SellValue ,  case when SUM(td_sqty) <> 0 then convert(decimal(15,2),sum(td_sqty*td_rate)/sum(td_sqty)) else 0 end SellRate, ";
                    strsql += " convert(decimal(15,2), sum( case When td_flag <> 'X' Then ((td_sqty-td_bqty) *td_rate) else 0 end)) Realised_PL,  ";
                    strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then (td_bqty-td_sqty)* ((Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) - td_rate) else 0 end)) UnRealised_PL,  ";
                    strsql += " convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_bqty-td_sqty)) else 0 end)) NetQty,  convert(decimal(15,2), sum( case When td_flag = 'X' Then ((td_sqty-td_bqty) * (Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) ) else 0 end))  Amount,  ";
                    strsql += " case When sum( case when td_flag = 'X'  Then (td_bqty-td_sqty) else 0 end) <> 0 then abs(convert(decimal(15,2),sum(Case When td_flag = 'X' Then (td_sqty-td_bqty)*(Case Left(td_stlmnt,1) when 'N' then ss_NSERate else ss_BSERate end) else 0 end )/sum(td_bqty-td_sqty))) else 0 end Rate, ";
                    strsql += " isnull(td_desc,'') TrdDlv,td_scripcd ScripCode ";
                    strsql += " from ##VX,securities with(nolock) where td_scripcd=ss_cd ";
                    strsql += " Group by ss_Lname,case td_flag When 'Y' Then 1 else 2 end ,td_desc,td_scripcd ";
                    strsql += " Union all ";
                    strsql += " select '2' Ord,'','Charges' ic_desc,'',0,0,0,0,0,0,convert(decimal(15,2),sum(ic_amount)) * (-1),0,0,0,0 amt ,'','' from ##invcharges";
                    strsql += " where ic_amount > 0";
                    strsql += " order by Ord,ss_Lname,flag desc";
                    var ds = objUtility.OpenDataSetTmp(strsql, con);
                    if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                    {
                        return ds.Tables[0];
                    }
                    return null;
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

