                strsql += " select MPT_clientcd,MPT_scripcd,'',sum(case When MPT_DRCR ='D' Then MPT_Qty else -MPT_Qty  end) MPT_Qty ,im_isin,ss_name,0,0,'MR' bh_type ";
                strsql += " from Isin with (nolock) ,securities ,MrgPledge_TRX  ";
                strsql += " Where im_scripcd = ss_cd and im_active = 'Y' and im_priority = (select min(im_priority) from Isin Where im_scripcd = MPT_scripcd and im_active = 'Y' )";
                strsql += " and MPT_scripcd = im_scripcd and ss_cd = MPT_scripcd ";
                strsql += " and MPT_OurDP in (" + strOurdp + ") ";
                strsql += " and MPT_TRXFlag = 'R' and MPT_clientcd='" + userid + "' ";
                strsql += " group by MPT_clientcd,MPT_scripcd,im_isin, ss_name ";
                strsql += " having abs(sum(case When MPT_DRCR ='D' Then MPT_Qty else -MPT_Qty  end)) > 0 ";
                objUtility.ExecuteSQLTmp(strsql, con);
            }

            DsMPTrx = objUtility.OpenDataSet("select * from SysObjects where name= 'CUSAPledge_TRX'");
            if (DsMPTrx.Tables[0].Rows.Count > 0)
            {
                string strOurdp = string.Empty;
                DataTable dt = objUtility.OpenDataTable("select distinct CUP_OurDP from CUSAPledge_TRX Where CUP_TRXFlag ='P'");
                if (dt.Rows.Count > 0)
                {
                    for (int i = 0; i <= dt.Rows.Count - 1; i++)
                    {
                        strOurdp += "'" + dt.Rows[i]["CUP_OurDP"].ToString().Trim() + "',";
                    }
                    strOurdp = strOurdp.Remove(strOurdp.Length - 1);
                }
                else
                {
                    strOurdp = "''";
                }
                strsql = "Insert into ##PreserveHld ";
                strsql += " select CUP_clientcd,CUP_scripcd,'',sum(case When CUP_DRCR ='C' Then CUP_Qty else -CUP_Qty  end) CUP_Qty ,im_isin,ss_name,0,0,'CP' bh_type ";
                strsql += " from Isin with (nolock) ,securities ,CUSAPledge_TRX  ";
                strsql += " Where im_scripcd = ss_cd and im_active = 'Y' and im_priority = (select min(im_priority) from Isin Where im_scripcd = CUP_scripcd and im_active = 'Y' )";
                strsql += " and CUP_scripcd = im_scripcd and ss_cd = CUP_scripcd ";
                strsql += " and CUP_OurDP in (" + strOurdp + ") ";
                strsql += " and CUP_clientcd='" + userid + "' ";
                strsql += " group by CUP_clientcd,CUP_scripcd,im_isin, ss_name ";
                strsql += " having abs(sum(case When CUP_DRCR ='C' Then CUP_Qty else -CUP_Qty  end)) > 0 ";
                objUtility.ExecuteSQLTmp(strsql, con);
                strsql = "Insert into ##PreserveHld ";
                strsql += " select CUP_clientcd,CUP_scripcd,'',sum(case When CUP_DRCR ='D' Then CUP_Qty else -CUP_Qty  end) CUP_Qty ,im_isin,ss_name,0,0,'CR' bh_type ";
                strsql += " from Isin with (nolock) ,securities ,CUSAPledge_TRX  ";
                strsql += " Where im_scripcd = ss_cd and im_active = 'Y' and im_priority = (select min(im_priority) from Isin Where im_scripcd = CUP_scripcd and im_active = 'Y' )";
                strsql += " and CUP_scripcd = im_scripcd and ss_cd = CUP_scripcd ";
                strsql += " and CUP_OurDP in (" + strOurdp + ") ";
                strsql += " and CUP_TRXFlag = 'R' and CUP_clientcd='" + userid + "' ";
                strsql += " group by CUP_clientcd,CUP_scripcd,im_isin, ss_name ";
                strsql += " having abs(sum(case When CUP_DRCR ='D' Then CUP_Qty else -CUP_Qty  end)) > 0 ";
                objUtility.ExecuteSQLTmp(strsql, con);
            }
            strsql = " Insert into ##TmpRates ";
            strsql += " select distinct dm_scripcd , 0 from ##PreserveHld ";
            objUtility.ExecuteSQLTmp(strsql, con);

            strsql = "update ##TmpRates set dm_bserate = mk_closerate from Market_rates";
            strsql += " where mk_scripcd = dm_scripcd and mk_exchange = 'B'";
            strsql += " and mk_dt = (select max(mk_dt) from Market_rates where mk_exchange = 'B'";
            strsql += " and mk_scripcd = dm_scripcd ";
            if (Conversion.Val(strRMSVALATLTRT) > 0)
            {
                string StrNewRMSVALATLTRT;
                DateTime DtRMSVALATLTRT = objUtility.ConvertDT(AsOnDt).AddDays(-Conversion.Val(strRMSVALATLTRT));
                StrNewRMSVALATLTRT = DtRMSVALATLTRT.ToString("yyyyMMdd");
                strsql += " and mk_dt >='" + StrNewRMSVALATLTRT + "'";
            }
            strsql += " and mk_dt <='" + AsOnDt + "' )";
            objUtility.ExecuteSQLTmp(strsql, con);

            strsql = "update ##TmpRates set dm_bserate = mk_closerate from Market_rates";
            strsql += " where mk_scripcd = dm_scripcd and mk_exchange ='N'";
            strsql += " and mk_dt = (select max(mk_dt) from Market_rates where mk_exchange = 'N'";
            strsql += " and mk_scripcd = dm_scripcd ";
            if (Conversion.Val(strRMSVALATLTRT) > 0)
            {
                string StrNewRMSVALATLTRT;
                DateTime DtRMSVALATLTRT = objUtility.ConvertDT(AsOnDt).AddDays(-Conversion.Val(strRMSVALATLTRT));
                StrNewRMSVALATLTRT = DtRMSVALATLTRT.ToString("yyyyMMdd");
                strsql += " and mk_dt >='" + StrNewRMSVALATLTRT + "'";
            }
            strsql += " and mk_dt <='" + AsOnDt + "' )";
            objUtility.ExecuteSQLTmp(strsql, con);

            strsql = "update A set A.dm_bserate = B.dm_bserate";
            strsql += " from ##PreserveHld A, ##TmpRates B Where A.dm_scripcd = B.dm_scripcd ";
            objUtility.ExecuteSQLTmp(strsql, con);

            strsql = " update ##PreserveHld set dm_valuation = (dm_bcqty*dm_bserate) ";
            objUtility.ExecuteSQLTmp(strsql, con);

            strsql = " select dm_clientcd ClientCode, dm_scripcd ScripCode , dm_isin ISIN,dm_Scripname ScripName,  sum(dm_bcqty) Quantity , convert(decimal(15,2) ,dm_bserate) Rate , convert(decimal(15,2), sum(dm_valuation)) Value ";
            strsql += " from ##PreserveHld ";
            strsql += " group by dm_clientcd,dm_scripcd,dm_isin,dm_Scripname,dm_bserate ";

            try
            {
                var ds = objUtility.OpenDataSetTmp(strsql, con);
                if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                {
                    var data = ds.Tables[0];
                    return data;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic Holding_MyDematAct_List(string userid)
        {
            string strsql = string.Empty;

            //if (_configuration["Cross"] != "")
            //{
            //    string[] ArrCross = _configuration["Cross"].Split("/");
            //    strsql = "select cm_blsavingcd ClientCode ,cm_cd DematActNo from ";
            //    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_master c ";
            //    strsql = strsql + " where cm_blsavingcd = '" + userid + "'";
            //}
            //else if (_configuration["Estro"] != "")
            //{
            //    string[] ArrCross = _configuration["Estro"].Split("/");
            //    strsql = " Select  case left(da_dpid, 2) when 'IN' then rtrim(da_dpid)+rtrim(da_actno) else da_actno end as DematActNo,da_name as ClientCode, da_clientcd ";
            //    strsql = strsql + " from dematact with(nolock) where da_clientcd = '" + userid + "'";
            // }
            strsql = "select  case left(da_dpid,2) when 'IN' then  rtrim(da_dpid)+rtrim(da_actno) else da_actno end as DematActNo,da_name as Name, da_clientcd as ClientCode ,'N' MasterRecord  from dematact with (nolock) where da_clientcd = '" + userid + "' ";

            try
            {
                var ds = objUtility.OpenDataSet(strsql);
                if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                {
                    DataTable data = ds.Tables[0];
                    if (_configuration["IsTradeWeb"] == "O" && objUtility.GetWebParameter("DPReports") == "Y")
                    {
                        Boolean blnCross = false;
                        foreach (DataRow gr in data.Rows)
                        {
                            if (gr["DematActNo"].ToString().Trim().Substring(0, 2).ToString() != "IN")
                            {
                                blnCross = true;
                                if (_configuration["Cross"] != "" && blnCross == true)
                                {
                                    char[] ArrSeparators = new char[1];
                                    ArrSeparators[0] = '/';
                                    string[] ArrCross = _configuration["Cross"].Split(ArrSeparators);

                                    string strBOID = gr["DematActNo"].ToString().Trim();
                                    if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb(ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".client_master", "count(0)", "cm_cd", strBOID, true)) > 0)
                                    {
                                        gr["MasterRecord"] = "Y";
                                    }
                                }
                            }
                        }
                    }
                    return data;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
        public dynamic Holding_MyDemat_Current_Graph(string userid, string dematActNo, string strtable, int graphDays)
        {
            string strsql = string.Empty;
            //if (_configuration["Cross"] != "")
            //{
            //    string[] ArrCross = _configuration["Cross"].Split("/");
            //    strsql = "select cm_blsavingcd ClientCode ,hld_ac_code DematAc, a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity, ";
            //    strsql = strsql + " d.bt_description BalanceType ,cast((sc_rate) as decimal(15,2)) as Rate, ";
            //    strsql = strsql + " cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as Value ";
            //    strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + "." + strtable + " a,";
            //    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Security b ,";
            //    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_master c ,";
            //    strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type d  ";
            //    strsql = strsql + " where a.hld_ac_code = cm_cd and cm_blsavingcd = '" + userid + "' and a.hld_ac_code = '" + dematActNo + "' and a.hld_isin_code = b.sc_isincode ";
            //    strsql = strsql + " and d.bt_code = a.hld_ac_type  ";
            //    strsql = strsql + " order by a.hld_ac_code,b.sc_company_name";
            //}
            string dematNo = string.Empty;
            if (dematActNo == "" || dematActNo == null)
            {
                string sqlQ = "Select Distinct Case left(da_dpid,2) when 'IN' then  rtrim(da_dpid)+rtrim(da_actno) else da_actno end as DematActNo from dematact with (nolock) where da_clientcd = '" + userid + "'";
                DataTable dAct = objUtility.OpenDataTable(sqlQ);
                if (dAct.Rows.Count > 0)
                {
                    foreach (DataRow dr in dAct.Rows)
                    {
                        dematNo = dematNo + "'" + dr["DematActNo"] + "',";
                    }
                }
            }
            else
            {
                string[] dematAcArry = new string[] { };
                if (dematActNo != "" && dematActNo != null)
                    dematAcArry = Convert.ToString(dematActNo).Split(',');
                for (int i = 0; i < dematAcArry.Length; i++)
                {
                    dematNo = dematNo + "'" + dematAcArry[i] + "',";
                }
            }

            if (dematNo.Length - 1 > 1)
                dematNo = dematNo.Substring(0, dematNo.Length - 1);
            if (_configuration["IsTradeWeb"] == "O")
            {
                char[] ArrSeparators = new char[1];
                ArrSeparators[0] = '/';
                if (_configuration["Cross"] != "")
                {
                    string[] ArrCross = _configuration["Cross"].Split(ArrSeparators);
                    strsql = "select a.hld_isin_code,b.sc_company_name,b.sc_isinname,cast((a.hld_ac_pos) as decimal(15,3)) hld_ac_pos,a.hld_ac_type, ";
                    strsql = strsql + " '" + userid + "' ClientCode ,hld_ac_code DematAc,a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity, d.bt_description BalanceType ,cast((sc_rate) as decimal(15,2)) as Rate, cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as Value, ";
                    strsql = strsql + " d.bt_description 'bt_description', hld_market_type,a.hld_settlement,cast((sc_rate) as decimal(15,2)) as sc_security_rate, ";
                    strsql = strsql + " cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as valuation,bt_description as BType";
                    strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Holding a,";
                    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Security b ,";
                    strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type d ";
                    strsql = strsql + " where a.hld_isin_code = b.sc_isincode  and d.bt_code = a.hld_ac_type ";
                    strsql = strsql + " and a.hld_ac_code in (" + dematNo + " ) ";
                    strsql = strsql + "   order by BType,a.hld_ac_code,b.sc_company_name ";
                }
                else if (_configuration["Estro"] != "")
                {
                    string[] ArrEstro = _configuration["Estro"].Split(ArrSeparators);

                    strsql = "select a.hld_isin_code,b.sc_company_name,b.sc_isinname,cast((a.hld_ac_pos) as decimal(15,3)) hld_ac_pos,a.hld_ac_type, ";
                    strsql = strsql + " '" + userid + "' ClientCode ,hld_ac_code DematAc, a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity, d.bt_description BalanceType ,cast((sc_rate) as decimal(15,2)) as Rate, cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as Value, ";
                    strsql = strsql + " d.bt_description 'bt_description', hld_market_type,a.hld_settlement,cast((sc_rate) as decimal(15,2)) as sc_security_rate, ";
                    strsql = strsql + " cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as valuation, bt_description as BType";
                    strsql = strsql + " from " + ArrEstro[0].Trim() + "." + ArrEstro[1].Trim() + "." + ArrEstro[2].Trim() + ".Holding a,";
                    strsql = strsql + ArrEstro[0].Trim() + "." + ArrEstro[1].Trim() + "." + ArrEstro[2].Trim() + ".Security b ,";
                    strsql = strsql + ArrEstro[0].Trim() + "." + ArrEstro[1].Trim() + "." + ArrEstro[2].Trim() + ".Beneficiary_type d, " + ArrEstro[0].Trim() + "." + ArrEstro[1].Trim() + "." + ArrEstro[2].Trim() + ".sysParameter ";
                    strsql = strsql + " where Rtrim(sp_sysValue) + a.hld_ac_code in (" + dematNo + " ) and a.hld_isin_code = b.sc_isincode and sp_parmcd = 'DPID' ";
                    strsql = strsql + " and d.bt_code = Case When hld_blf = 'L' then Case hld_ac_type when  '22' then '17' when  '21' then '17'  when '29' then '18' else hld_ac_type end ";
                    strsql = strsql + " else case hld_ac_type when '25' then '28' else hld_ac_type end end ";
                    strsql = strsql + " order by BType,a.hld_ac_code,b.sc_company_name ";
                }
            }
            else
            {//-----------------------------------------------------------Tradeweb------------------------------------------------------------
                strsql = "select  a.hld_isin_code,b.sc_company_name,b.sc_isinname,sc_company_name + '  ' + '(' + sc_isinname + ')' as Type,cast((a.hld_ac_pos) as decimal(15,3)) hld_ac_pos,a.hld_ac_type, ";
                strsql = strsql + " '" + userid + "'  ClientCode ,hld_ac_code DematAc, a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity, d.bt_description BalanceType ,cast((sc_rate) as decimal(15,2)) as Rate, cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as Value, ";
                strsql = strsql + " d.bt_description 'bt_description', hld_market_type,a.hld_settlement, cast((sc_security_rate) as decimal(15,2)) sc_security_rate, ";
                strsql = strsql + " cast(( ( a.hld_ac_pos * sc_security_rate)) as decimal(15,2))  as valuation , bt_description + case When Len(Rtrim(hld_settlement)) = 8 and  left(hld_dpid,2) = 'IN'  Then ' Locked Till : ' + Ltrim(Rtrim(convert(char,convert(datetime,hld_settlement),103))) else '' end as BType from Holding a with (nolock),Security b with (nolock) , ";
                strsql = strsql + " Beneficiary_type d with (nolock) where hld_dpid+hld_ac_code in (" + dematNo + " ) and a.hld_isin_code = b.sc_isincode ";
                strsql = strsql + "  and d.bt_code = a.hld_ac_type order by BType,d.bt_description, a.hld_ac_code,b.sc_company_name ";
            }
            try
            {
                var dt = objUtility.OpenDataTable(strsql);
                List<Holding_DematAct_Graph> graphData = new List<Holding_DematAct_Graph>();
                List<Holding_DematAct_Graph> holding_Graph_Res = new List<Holding_DematAct_Graph>();

                if (dt.Rows.Count > 0)
                {
                    if (graphDays > 0)
                    {
                        string[] ArrCross = null;
                        if (_configuration["Cross"] != "")
                        {
                            ArrCross = _configuration["Cross"].Split("/");
                        }
                        else
                        {
                            ArrCross = _configuration["Estro"].Split("/");
                        }
                        string dayDate = DateTime.Now.AddDays(-graphDays).ToString("yyyyMMdd");
                        var isinList = dt.AsEnumerable().Select(r => r.Field<String>("ISIN")).ToList();
                        string joined = string.Join("','", isinList);

                        strsql = "select rm_isin_code ISIN,convert(varchar,rm_trx_date,112) RateDt,rm_rate Rate from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".RAte_master  ";
                        strsql += " Where rm_ISIN_code in ('" + joined + "') And rm_trx_date >= '" + dayDate + "'   Order by rm_trx_date";
                        DataTable sub_dt = objUtility.OpenDataTable(strsql);

                        for (int i = 0; i < dt.Rows.Count; i++)
                        {
                            Holding_DematAct_Graph holdingGraph = new Holding_DematAct_Graph();
                            holdingGraph.graphDetails = new List<Holding_DematAct_GraphData>();
                            holdingGraph.ClientCode = dt.Rows[i]["ClientCode"].ToString();
                            holdingGraph.DematAc = dt.Rows[i]["DematAc"].ToString();
                            holdingGraph.ISIN = dt.Rows[i]["ISIN"].ToString();
                            holdingGraph.CompanyName = dt.Rows[i]["CompanyName"].ToString();
                            holdingGraph.ISINName = dt.Rows[i]["ISINName"].ToString();
                            holdingGraph.Quantity = dt.Rows[i]["Quantity"].ToString();
                            holdingGraph.BalanceType = dt.Rows[i]["BalanceType"].ToString();
                            holdingGraph.Rate = dt.Rows[i]["Rate"].ToString();
                            holdingGraph.Value = dt.Rows[i]["Value"].ToString();
                            if (sub_dt.Rows.Count > 0)
                            {
                                try
                                {
                                    DataTable tblFiltered = sub_dt.AsEnumerable()
                                  .Where(row => row.Field<String>("ISIN") == holdingGraph.ISIN)
                                  .OrderBy(row => row.Field<String>("RateDt")).CopyToDataTable();

                                    var graphJson = JsonConvert.SerializeObject(tblFiltered, Formatting.Indented);
                                    var resGraph = JsonConvert.DeserializeObject<List<Holding_DematAct_GraphData>>(graphJson);
                                    holdingGraph.graphDetails = resGraph;
                                }
                                catch (Exception e) { string aa = e.Message.ToString(); }
                            }

                            graphData.Add(holdingGraph);
                        }
                        return graphData;
                    }
                    else
                    {
                        var graphJson = dt;
                        //var resGraph = JsonConvert.DeserializeObject<List<Holding_DematAct_Graph>>(graphJson);
                        //return resGraph;
                        return graphJson;
                    }
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic Holding_MyDemat_Current(string userid, string dematActNo, string strtable)
        {
            string strsql = string.Empty;
            dematActNo = dematActNo.Replace(",", "','");
            if (_configuration["Cross"] != "")
            {
                string[] ArrCross = _configuration["Cross"].Split("/");
                strsql = "select cm_blsavingcd ClientCode ,hld_ac_code DematAc, a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity, ";
                strsql = strsql + " d.bt_description BalanceType ,cast((hld_Rate) as decimal(15,2)) as Rate, ";
                strsql = strsql + " cast(( ( a.hld_ac_pos * hld_Rate)) as decimal(15,2))  as Value ";
                strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + "." + strtable + " a,";
                strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Security b ,";
                strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_master c ,";
                strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type d  ";
                strsql = strsql + " where a.hld_ac_code = cm_cd and cm_blsavingcd = '" + userid + "' and a.hld_ac_code in ('" + dematActNo + "') and a.hld_isin_code = b.sc_isincode ";
                strsql = strsql + " and d.bt_code = a.hld_ac_type  and a.hld_ac_type not in ('52')  ";
                strsql = strsql + " order by a.hld_ac_code,b.sc_company_name";
            }
            else
            {
                string[] ArrCross = _configuration["Estro"].Split("/");
                //string strTable = "Holding_" + Strings.Right(cmbAson.Text, 4) + Strings.Mid(cmbAson.Text, 4, 2) + Strings.Left(cmbAson.Text, 2);
                strsql = "select name from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Sysobjects where xtype = 'U' and name='" + strtable + "'";
                DataSet objChk = objUtility.OpenDataSet(strsql);
                if (objChk.Tables[0].Rows.Count > 0)
                {
                    strsql = "select a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity,a.hld_ac_type, ";
                    strsql = strsql + " d.bt_description BalanceType, cast((hld_Rate) as decimal(15,2)) as Rate, ";
                    strsql = strsql + " cast(( ( a.hld_ac_pos * hld_Rate)) as decimal(15,2))  as Value,bt_description as BType";
                    strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + "." + strtable + " a,";
                    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Security b ,";
                    strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type d, " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".sysParameter ";
                    strsql = strsql + " where  Rtrim(sp_sysValue) + a.hld_ac_code in ('" + dematActNo + "' ) and a.hld_isin_code = b.sc_isincode and sp_parmcd = 'DPID' ";
                    strsql = strsql + " and d.bt_code = Case When hld_blf = 'L' then Case hld_ac_type when  '22' then '17' when  '21' then '17'  when '29' then '18' else hld_ac_type end ";
                    strsql = strsql + "  else case hld_ac_type when '25' then '28' else hld_ac_type end end  order by BType,a.hld_ac_code,b.sc_company_name  ";
                }
            }
            try
            {
                var ds = objUtility.OpenDataSet(strsql);

