                    strsql = strsql + " ,rm.rm_isin_code ISIN, rm.rm_trx_date RateDt, rm.rm_rate Rate "; // For graph data
                    strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + "." + strtable + " a,";
                    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Security b ,";
                    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_master c ,";
                    strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type d , ";
                    strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".RAte_master rm "; // for graph data table
                    strsql = strsql + " where a.hld_ac_code = cm_cd and cm_blsavingcd = '" + userid + "' and a.hld_ac_code = '" + dematActNo + "' and a.hld_isin_code = b.sc_isincode ";
                    strsql = strsql + " and d.bt_code = a.hld_ac_type and rm.rm_ISIN_code=a.hld_isin_code and rm.rm_trx_date between  '" + fromDate + "' and  '" + toDate + "' ";
                    strsql = strsql + " order by a.hld_ac_code,b.sc_company_name, rm.rm_trx_date ";
                }
                else
                {
                    strsql = "select cm_blsavingcd ClientCode ,hld_ac_code DematAc, a.hld_isin_code ISIN,b.sc_company_name CompanyName,b.sc_isinname ISINName,cast((a.hld_ac_pos) as decimal(15,3)) Quantity, ";
                    strsql = strsql + " d.bt_description BalanceType ,cast((sc_rate) as decimal(15,2)) as Rate, ";
                    strsql = strsql + " cast(( ( a.hld_ac_pos * sc_Rate)) as decimal(15,2))  as Value ";
                    strsql = strsql + " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + "." + strtable + " a,";
                    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Security b ,";
                    strsql = strsql + " " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_master c ,";
                    strsql = strsql + "" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type d  ";
                    strsql = strsql + " where a.hld_ac_code = cm_cd and cm_blsavingcd = '" + userid + "' and a.hld_ac_code = '" + dematActNo + "' and a.hld_isin_code = b.sc_isincode ";
                    strsql = strsql + " and d.bt_code = a.hld_ac_type  ";
                    strsql = strsql + " order by a.hld_ac_code,b.sc_company_name";
                }
            }
            try
            {
                var dt = objUtility.OpenDataTable(strsql);
                List<Holding_DematAct_Graph> graphData = new List<Holding_DematAct_Graph>();
                List<Holding_DematAct_Graph> holding_Graph_Res = new List<Holding_DematAct_Graph>();

                if (dt.Rows.Count > 0)
                {
                    string[] ArrCross = _configuration["Cross"].Split("/");
                    if (isGraph == true)
                    {
                        for (int i = 0; i < dt.Rows.Count - 1; i++)
                        {
                            Holding_DematAct_Graph holdingGraph = new Holding_DematAct_Graph();
                            holdingGraph.graphDetails = new List<Holding_DematAct_GraphData>();
                            Holding_DematAct_GraphData gdetail = new Holding_DematAct_GraphData();
                            holdingGraph.ClientCode = dt.Rows[i]["ClientCode"].ToString();
                            holdingGraph.DematAc = dt.Rows[i]["DematAc"].ToString();
                            holdingGraph.ISIN = dt.Rows[i]["ISIN"].ToString();
                            holdingGraph.CompanyName = dt.Rows[i]["CompanyName"].ToString();
                            holdingGraph.ISINName = dt.Rows[i]["ISINName"].ToString();
                            holdingGraph.Quantity = dt.Rows[i]["Quantity"].ToString();
                            holdingGraph.BalanceType = dt.Rows[i]["BalanceType"].ToString();
                            holdingGraph.Rate = dt.Rows[i]["Rate"].ToString();
                            holdingGraph.Value = dt.Rows[i]["Value"].ToString();

                            strsql = "select top 2 rm_isin_code ISIN,rm_trx_date RateDt,rm_rate Rate from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".RAte_master  ";
                            strsql += " Where rm_ISIN_code = '" + holdingGraph.ISIN + "' ";
                            strsql += " and rm_trx_date between  '" + fromDate + "' and  '" + toDate + "' Order by rm_trx_date";
                            var sub_dt = objUtility.OpenDataTable(strsql);
                            var graphJson = JsonConvert.SerializeObject(sub_dt, Formatting.Indented);
                            var resGraph = JsonConvert.DeserializeObject<List<Holding_DematAct_GraphData>>(graphJson);
                            holdingGraph.graphDetails = resGraph;

                            graphData.Add(holdingGraph);
                        }
                        return graphData;
                    }
                    else
                    {
                        return dt;
                    }
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

