        public DpHoldingDetail GetDpHoldingDetail(string BOID)
        {
            DpHoldingDetail dpHoldingDetail = new DpHoldingDetail();
            string Strsql = "";
            string strDPID = BOID;

            char[] ArrSeparators = new char[1];
            ArrSeparators[0] = '/';
            if (_configuration["Cross"] != "")
            {
                dpHoldingDetail.BoId = strDPID;
                string[] ArrCross = _configuration["Cross"].Split(ArrSeparators);
                string strBkCode = "";
                Strsql = "select * from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".client_master where cm_cd='" + strDPID + "'";
                DataTable dt = new DataTable();
                dt = objUtility.OpenDataTable(Strsql);
                if (dt.Rows.Count > 0)
                {
                    dpHoldingDetail.Name = dt.Rows[0]["cm_name"].ToString();
                    dpHoldingDetail.Address1 = dt.Rows[0]["cm_add1"].ToString();
                    dpHoldingDetail.Address2 = dt.Rows[0]["cm_add2"].ToString();
                    dpHoldingDetail.Address3 = dt.Rows[0]["cm_add3"].ToString();
                    dpHoldingDetail.City = dt.Rows[0]["cm_city"].ToString();
                    dpHoldingDetail.Pincode = dt.Rows[0]["cm_pin"].ToString();
                    dpHoldingDetail.MobileNo = dt.Rows[0]["cm_tele1"].ToString();
                    dpHoldingDetail.EmailId = dt.Rows[0]["cm_email"].ToString();
                    dpHoldingDetail.SecondHolderName = dt.Rows[0]["cm_sech_name"].ToString();
                    dpHoldingDetail.ThirdHolderName = dt.Rows[0]["cm_thih_name"].ToString();
                    dpHoldingDetail.Occupation = objUtility.fnFireQueryTradeWeb(ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_occupation", "bo_description", "bo_code", dt.Rows[0]["cm_occupation"].ToString().Trim(), true);
                    dpHoldingDetail.AccountType = objUtility.fnFireQueryTradeWeb(ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Beneficiary_type", "bt_description", "bt_code", dt.Rows[0]["cm_clienttype"].ToString().Trim(), true);
                    dpHoldingDetail.POAForPayin = (dt.Rows[0]["cm_poaforpayin"].ToString().Trim() == "Y" ? "Yes" : "No");
                    strBkCode = dt.Rows[0]["cm_divbankcode"].ToString();
                    if (strBkCode != "")
                    {
                        dpHoldingDetail.BankAccountNo = dt.Rows[0]["cm_divbankacno"].ToString();
                        dpHoldingDetail.MICRCode = strBkCode;
                    }
                    if (string.IsNullOrEmpty(dt.Rows[0]["cm_divbranchno"].ToString()) == false)
                    {
                        switch (dt.Rows[0]["cm_divbranchno"].ToString().Trim())
                        {
                            case "10":
                                dpHoldingDetail.BankAccountType = "Saving Account";
                                break;
                            case "11":
                                dpHoldingDetail.BankAccountType = "Current Account";
                                break;
                            case "13":
                                dpHoldingDetail.BankAccountType = "Cash Credit";
                                break;
                            default:
                                dpHoldingDetail.BankAccountType = "";
                                break;
                        }
                    }
                }
                Strsql = "select * from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".client_backoffice where cb_cmcd='" + strDPID + "'";
                dt = objUtility.OpenDataTable(Strsql);
                if (dt.Rows.Count > 0)
                {
                    dpHoldingDetail.PanNo = dt.Rows[0]["cb_panno"].ToString();
                    dpHoldingDetail.UID = dt.Rows[0]["cb_UID1"].ToString();
                    dpHoldingDetail.SecondHolderMobileNo = dt.Rows[0]["cb_bankcity"].ToString();
                    dpHoldingDetail.ThirdHolderMobileNo = dt.Rows[0]["cb_bankcountry"].ToString();
                    dpHoldingDetail.SecondHolderEmailId = dt.Rows[0]["cb_bankstate"].ToString();
                    dpHoldingDetail.ThirdHolderEmailId = dt.Rows[0]["cb_bankpin"].ToString();
                    dpHoldingDetail.AnnualIncome = objUtility.fnFireQueryTradeWeb(ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Clientsub_master", "cs_desc", "cs_module='CS03' and cs_code", dt.Rows[0]["cb_annualincome"].ToString(), true);
                    dpHoldingDetail.AccountFlag = (dt.Rows[0]["cb_FillerX2"].ToString().Trim() == "Y" ? "Yes" : "No");
                    dpHoldingDetail.SmartIndicator = (dt.Rows[0]["cb_SmartIndicator"].ToString().Trim() == "Y" ? "Yes" : "No");
                    dpHoldingDetail.BankName = objUtility.fnFireQueryTradeWeb("" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Bank_master", "bk_name", "bk_micr", strBkCode.Trim() + "' and bk_branch = '" + dt.Rows[0]["cb_voicemail"].ToString(), true);
                    if (dpHoldingDetail.BankName == "")
                    {
                        dpHoldingDetail.BankName = objUtility.fnFireQueryTradeWeb("" + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Bank_master", "bk_name", "bk_branch", dt.Rows[0]["cb_voicemail"].ToString(), true);
                    }
                    dpHoldingDetail.IFSCCode = dt.Rows[0]["cb_voicemail"].ToString();
                }

                Strsql = "Select cpd_poaid, case cpd_holderno when '1' then '1st Holder' when '2' then '2nd Holder' when '3' then '3rd Holder' else 'All' end cpd_holderno, ";
                Strsql += " case cpd_POAStatus When 'D' Then 'Deleted' When 'E' then 'Expired' else 'Setup' End cpd_POAStatus, case cpd_cacharfield when 'G' then 'General POA' else 'Specific POA' end cpd_cacharfield ";
                Strsql += " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".client_poa_details," + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".client_master where cpd_boid=cm_cd and cm_cd='" + strDPID + "'";
                dt = objUtility.OpenDataTable(Strsql);
                dpHoldingDetail.POADetails = new List<POADetail>();
                if (dt.Rows.Count > 0)
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        dpHoldingDetail.POADetails.Add(new POADetail
                        {
                            POAID = dt.Rows[i]["cpd_poaid"].ToString(),
                            POAType = dt.Rows[i]["cpd_cacharfield"].ToString(),
                            POAStatus = dt.Rows[i]["cpd_POAStatus"].ToString(),
                            POAHolder = dt.Rows[i]["cpd_holderno"].ToString(),
                        });
                    }
                }

                Strsql = "Select cud_consent, case cud_Exchnge When '11' Then 'BSE' When '12' Then 'NSE' When '29' Then 'MCX' else bp_name end + ' - ' + cs_desc cud_Exchnge,cud_UCC,cud_cmid,cud_tmid ";
                Strsql += " from " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_UCC_Details," + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".client_master," + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Bpmaster," + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Clientsub_master where cud_segment=cs_code and cud_boid=cm_cd and bp_id=cud_Exchnge and cs_module = 'CS25' and Bp_role = '02' and cm_cd='" + strDPID + "'";
                dt = objUtility.OpenDataTable(Strsql);
                dpHoldingDetail.UCCMappings = new List<UCCMapping>();
                if (dt.Rows.Count > 0)
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        dpHoldingDetail.UCCMappings.Add(new UCCMapping
                        {
                            ExchangeSegment = dt.Rows[i]["cud_Exchnge"].ToString(),
                            UCC = dt.Rows[i]["cud_UCC"].ToString(),
                            TmId = dt.Rows[i]["cud_tmid"].ToString(),
                            CmId = dt.Rows[i]["cud_cmid"].ToString(),
                        });
                    }
                }

                Strsql = "select '' as cn_srNo, cn_purposeCd, cn_NomSrno, cn_NomName + ' ' + cn_NomMidNm + ' ' + cn_NomlastNm as NomineeName ,cn_PH1,cn_nomemail,cs_desc as Relation, Case Ltrim(Rtrim(Convert(Char,cn_purposeCd))) +'|'+ Ltrim(Rtrim(Convert(Char,cn_NomSrno))) ";
                Strsql += " When '7|1' then 1 When '7|0' then 1 ";
                Strsql += " When  '6|1' then 2 When '8|1'  then 3 ";
                Strsql += " When  '6|2' then 4 When '8|2'  then 5 ";
                Strsql += " When  '6|3' then 6 When '8|3'  then 7 Else 8 End OrderCd ";
                Strsql += " From " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".Client_NomineeDetails, " + ArrCross[0].Trim() + "." + ArrCross[1].Trim() + "." + ArrCross[2].Trim() + ".clientsub_master ";
                Strsql += " Where cn_relation = cs_code and cs_module='CS19' and cn_cmcd = '" + strDPID + "' Order by cn_purposeCd, cn_NomSrno ";
                dt = objUtility.OpenDataTable(Strsql);
                dpHoldingDetail.NomineeDetails = new List<NomineeDetail>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows)
                    {
                        switch (dr["cn_purposeCd"].ToString().Trim() + "|" + dr["cn_NomSrno"].ToString().Trim())
                        {
                            case "6|1":
                                dr["cn_srNo"] = "1st Nominee";
                                break;
                            case "8|1":
                                dr["cn_srNo"] = "1st Guardian";
                                break;
                            case "6|2":
                                dr["cn_srNo"] = "2nd Nominee";
                                break;
                            case "8|2":
                                dr["cn_srNo"] = "2nd Guardian";
                                break;
                            case "6|3":
                                dr["cn_srNo"] = "3rd Nominee";
                                break;
                            case "8|3":
                                dr["cn_srNo"] = "3rd Guardian";
                                break;
                            case "7|1":
                                dr["cn_srNo"] = "1 Guardian";
                                break;
                            case "7|0":
                                dr["cn_srNo"] = "1 Guardian";
                                break;
                            default:
                                dr["cn_srNo"] = "";
                                break;
                        }

                        dpHoldingDetail.NomineeDetails.Add(new NomineeDetail
                        {
                            SrNo = dr["cn_srNo"].ToString(), //dt.Rows[i]["cud_Exchnge"].ToString(),
                            Name = dr["NomineeName"].ToString(),
                            MobileNo = dr["cn_PH1"].ToString(),
                            EmailId = dr["cn_nomemail"].ToString(),
                            Relation = dr["relation"].ToString(),
                        });
                    }

                    //rptNominee.DataSource = dt;
                    //rptNominee.DataBind();
                }
                else
                {
                    //divNominee.Visible = false;
                }
            }

            return dpHoldingDetail;
        }

