        #region Reset Password method
        public string Login_GetPassword_Execute(string userId, string otpType)
        {
            string Strsql = "";
            try
            {
                string strMobileNo = string.Empty;
                string strEmailId = string.Empty;
                string strPass = string.Empty;
                string strMsgTxt = string.Empty;
                string strUser = string.Empty;
                string strMaskMobile = string.Empty;
                string strMaskEmail = string.Empty;
                string strUserCd = string.Empty;
                string strResponseMessage = "";
                DataSet ds = new DataSet();

                Strsql = "Select * from Client_master where cm_cd = '" + userId.Trim() + "'";
                ds = objUtility.OpenDataSet(Strsql);

                if (ds.Tables[0].Rows.Count == 0)
                {
                    return "No Records Found";
                }
                if (ds.Tables[0].Rows[0]["cm_mobile"].ToString().Trim() == "")
                {
                    return "Mobile Number is not available";
                }
                strMobileNo = ds.Tables[0].Rows[0]["cm_mobile"].ToString().Trim();
                strEmailId = ds.Tables[0].Rows[0]["cm_email"].ToString().Trim();

                if (otpType == "FP")
                {
                    if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Sysparameter", "count(0)", "sp_parmcd", "SMSTWEBPWD", true)) > 0)
                    {
                        strMsgTxt = objUtility.fnFireQueryTradeWeb("sysparameter", "SP_SYSVALUE", "sp_parmcd", "SMSTWEBPWD", true);
                    }
                    else if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Webparameter", "count(0)", "sp_parmcd", "SMSGETPWD", true)) > 0)
                    {
                        strMsgTxt = objUtility.fnFireQueryTradeWeb("Webparameter", "SP_SYSVALUE", "sp_parmcd", "SMSGETPWD", true);
                    }
                    else
                    {
                        strMsgTxt = "Client code <Client>, your OTP to Login in Tradeweb is : <OTP>";
                    }
                }
                else if (otpType == "2FA")
                {
                    strMsgTxt = objUtility.fnFireQueryTradeWeb("webparameter", "SP_SYSVALUE", "sp_parmcd", "SMS2FA", true);
                }
                //strMsgTxt = "Your OTP to Initiate password reset for TradeWeb is <OTP> login ID : <Client>";
                strUserCd = ds.Tables[0].Rows[0]["cm_cd"].ToString().Trim();

                string chars1 = "1234567890";
                char[] stringChars1 = new char[4];
                Random random1 = new Random();
                for (int i = 0; i < stringChars1.Length; i++)
                {
                    stringChars1[i] = chars1[random1.Next(chars1.Length)];
                }
                string strSotp = new String(stringChars1);

                StringBuilder sb = new StringBuilder(strMobileNo);
                for (int i = 2; i <= strMobileNo.Length - 3; i++)
                {
                    sb[i] = 'x';
                }
                strMaskMobile = sb.ToString();
                sb = new StringBuilder(strUserCd.ToUpper());
                for (int j = 1; j < strUserCd.Length - 1; j++)
                {
                    sb[j] = 'x';
                }
                strUser = sb.ToString();
                sb = new StringBuilder(strEmailId);
                for (int i = 2; i <= strEmailId.Length - 3; i++)
                {
                    sb[i] = 'x';
                }
                strMaskEmail = sb.ToString();
                strMsgTxt = strMsgTxt.Replace("<Client>", strUser);
                strMsgTxt = strMsgTxt.Replace("<OTP>", strSotp);

                strMsgTxt = strMsgTxt.Replace("<&>", "<~>");
                strMsgTxt = strMsgTxt.Replace("&", "");
                strMsgTxt = strMsgTxt.Replace("<~>", "&");

                string resp = objUtility.SendSmsCommon(userId, strMsgTxt, strMobileNo);

                if (objUtility.GetWebParameter("SMTPSERVER").Trim() != "" && strEmailId != "")
                {
                    try
                    {
                        string strHost = string.Empty;
                        int intPort;
                        string strUserID = string.Empty;
                        string strPWD = string.Empty;
                        string fromEmail = string.Empty;
                        string strSSL = string.Empty;
                        string strSMTPParamVal = objUtility.GetWebParameter("SMTPSERVER");
                        string toEmailID = strEmailId;

                        strHost = strSMTPParamVal.Split('/')[0];
                        intPort = Convert.ToInt32(strSMTPParamVal.Split('/')[1]);
                        strUserID = strSMTPParamVal.Split('/')[2];
                        strPWD = strSMTPParamVal.Split('/')[3];
                        fromEmail = strSMTPParamVal.Split('/')[4];
                        strSSL = strSMTPParamVal.Split('/')[5];

                        MailMessage Msg = new MailMessage();

                        Msg.From = new MailAddress(fromEmail);
                        Msg.To.Add(toEmailID);
                        Msg.Subject = "Change Request OTP For Client " + userId;
                        Msg.Body = strMsgTxt;
                        Msg.IsBodyHtml = true;
                        SmtpClient smtp = new SmtpClient();
                        smtp.Host = strHost;
                        smtp.Port = intPort;
                        smtp.Credentials = new System.Net.NetworkCredential(strUserID, strPWD);
                        smtp.EnableSsl = strSSL == "N" ? false : true;
                        System.Net.ServicePointManager.ServerCertificateValidationCallback = delegate (object s,
                        System.Security.Cryptography.X509Certificates.X509Certificate certificate,
                        System.Security.Cryptography.X509Certificates.X509Chain chain,
                        System.Net.Security.SslPolicyErrors sslPolicyErrors)
                        {
                            return true;
                        };
                        smtp.Send(Msg);
                        smtp.Dispose();
                        strResponseMessage = " and Email " + strMaskEmail;
                    }
                    catch (Exception)
                    {
                        strResponseMessage = " ,but failed to sent otp on email " + strMaskEmail;
                    }
                }
                if (resp.ToLower().Contains("success"))
                {
                    string otpResp = objUtility.InsertUpdateOTPmaster(userId, "BT", strSotp, strMobileNo + strEmailId, "FP", "TradeWeb", 5);
                    return "OTP sent to your registered mobile " + strMaskMobile + strResponseMessage;
                }
                else
                {
                    return "Error in sending SMS " + resp;
                }
            }
            catch (Exception e)
            {
                return "Error in sending SMS : " + e.Message.ToString();
            }
        }

        private static string DecodeFrom64(string encodedData)
        {
            try
            {
                string returnValue = null;
                byte[] encodedDataAsBytes = System.Convert.FromBase64String(encodedData);
                returnValue = System.Text.ASCIIEncoding.ASCII.GetString(encodedDataAsBytes);
                return returnValue;
            }
            catch (Exception ex)
            {
                return "";
            }
        }
