        public dynamic CapitalGainLoss_TradeListingSummary_Process(string ClientWhere, string FromDate, string ToDate)
        {
            DataTable dt = new DataTable();
            string strSql = "";

            string connectionString = objUtility.GetConnectionStr();
            using (SqlConnection curCon = new SqlConnection(connectionString))
            {
                curCon.Open();

                strSql = "select Rtrim(td_clientcd) td_clientcd, td_scripcd , Rtrim(ss_lname) as ScripName,";
                strSql += " convert(decimal(15,0) ,sum(td_bqty)) Bqty,convert(decimal(15,2) ,case When sum(td_rate*td_bqty) > 0 then sum(td_rate*td_bqty)/sum(td_bqty) else 0 end) BRate,convert(decimal(15,2),sum(td_bqty*td_rate)) BAmt,";
                strSql += " convert(decimal(15,0) ,sum(td_sqty)) sqty,convert(decimal(15,2) ,case When sum(td_rate*td_sqty) > 0 then sum(td_rate*td_sqty)/sum(td_sqty) else 0 end) SRate,";
                strSql += " convert(decimal(15,2),sum(td_sqty*td_rate)) SAmt,convert(decimal(15,0) ,sum(td_bqty-td_sqty)) NetQty  ,convert(decimal(15,2) ,sum((td_bqty-td_sqty)*td_rate)) NAmt from TRX_INVPL,Securities,Client_master ";
                strSql += " Where td_clientcd = cm_cd and td_scripcd = ss_cd and td_dt between '" + FromDate + "' and '" + ToDate + "' " + ClientWhere;
                strSql += " group by td_clientcd,td_scripcd,Rtrim(ss_lname) order by Rtrim(td_clientcd),Rtrim(ss_lname)";
                dt = objUtility.OpenDataTable(strSql, curCon);
            }

            if (dt?.Rows?.Count > 0)
            {
                List<GainLossTradeListingSummaryResponse> gainLossTradeListingSummaries = new List<GainLossTradeListingSummaryResponse>();

                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    gainLossTradeListingSummaries.Add(new GainLossTradeListingSummaryResponse
                    {
                        ClientCode = dt.Rows[i]["td_clientcd"].ToString(),
                        ScripCode = dt.Rows[i]["td_scripcd"].ToString(),
                        ScripName = dt.Rows[i]["ScripName"].ToString(),
                        BuyQuantity = dt.Rows[i]["Bqty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Bqty"]),
                        BuyRate = dt.Rows[i]["BRate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["BRate"]),
                        BuyAmount = dt.Rows[i]["BAmt"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["BAmt"]),
                        SellQuantity = dt.Rows[i]["sqty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["sqty"]),
                        SellRate = dt.Rows[i]["SRate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["SRate"]),
                        SellAmount = dt.Rows[i]["SAmt"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["SAmt"]),
                        NetQuantity = dt.Rows[i]["NetQty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["NetQty"]),
                        NetAmount = dt.Rows[i]["NAmt"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["NAmt"]),
                    });
                }

                return gainLossTradeListingSummaries;
            }
            return null;
        }

        public dynamic CapitalGainLoss_ActualPLDetail_Process(string ClientWhere, string FromDate, string ToDate, bool blnignore112A, string scripCd)
        {
            try
            {
                string strSql = "";
                string strwhere = "";
                DataTable dt = new DataTable();

                string connectionString = objUtility.GetConnectionStr();
                using (SqlConnection curCon = new SqlConnection(connectionString))
                {
                    curCon.Open();

                    prGainLoss("ActualPL", ClientWhere, FromDate, ToDate, scripCd, false, blnignore112A ? "Y" : "N", "", curCon);

                    objUtility.ExecuteSQL("Create Index #Idx_TmpGainLoss_Clientcd_Scripcd on #TmpGainLossRep (Tmp_Clientcd ,Tmp_Scripcd )", curCon);

                    strSql = " select Rtrim(Tmp_Clientcd) Tmp_Clientcd,TMp_Scripcd,case When Tmp_Flag not in ('B') and Tmp_SDt <> ''  Then ltrim(rtrim(convert(char,convert(datetime,Tmp_SDt),103)))  else ''  End  as Tmp_SDt," + Constants.vbNewLine;
                    strSql += " Tmp_SRate , cast(case Tmp_Flag When 'S' Then -Tmp_Qty else Tmp_Qty End as decimal(15,0)) Tmp_Qty ," + Constants.vbNewLine;
                    strSql += " case when  Tmp_Flag not in ('S')and Tmp_BDt <> ''  then ltrim(rtrim(convert(char,convert(datetime,Tmp_BDt),103)))  else '' end as Tmp_BDt,Tmp_BRate," + Constants.vbNewLine;
                    strSql += " CAST((Tmp_ActualRate* Tmp_Qty) as decimal(15,2)) BAmount, " + Constants.vbNewLine;
                    strSql += " CAST((Tmp_SRate* Tmp_Qty) as decimal(15,2)) SAmount, " + Constants.vbNewLine;
                    strSql += " CAST((Tmp_112ARate* Tmp_Qty) as decimal(15,2)) as '112AAmount', " + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag in ('B','S') Then ((Tmp_BRate-Tmp_SRate)*Tmp_Qty) else 0 End as decimal(15,2)) StockAtCost," + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag in ('B','S') Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End*Tmp_MarketRate  else 0 End as decimal(15,2)) StockAtMkt," + Constants.vbNewLine;
                    strSql += " cast(case Tmp_Flag When 'T'  Then ((Tmp_SRate-Tmp_BRate)*Tmp_Qty) else 0 End as decimal(15,2)) Trading ," + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag ='X' and dateDiff(d,Tmp_BDt,Tmp_SDt) >= 365 Then case when ((Tmp_LTCG='*') and (Tmp_SRate+Tmp_SStt) < Tmp_BRate) then 0 else ((Tmp_SRate-Tmp_BRate)*Tmp_Qty) end else 0 End as decimal(15,2)) LongTerm," + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag ='X' and dateDiff(d,Tmp_BDt,Tmp_SDt) < 365 Then  ((Tmp_SRate-Tmp_BRate)*Tmp_Qty)  else 0 End as decimal(15,2)) ShortTerm," + Constants.vbNewLine;
                    strSql += " cast(case Tmp_Flag When 'B' Then Tmp_Qty*(Tmp_MarketRate-Tmp_BRate) When 'S' Then Tmp_Qty*(Tmp_SRate-Tmp_MarketRate) else 0 end as decimal(15,2)) UnRealGain ," + Constants.vbNewLine;
                    strSql += " case Tmp_Flag when 'T' then 'Trading' when 'X' then 'Delivery' when 'B' then 'Stock' when 'S' then 'Excess Sell' else '' end Type," + Constants.vbNewLine;
                    strSql += " dateDiff(d,Tmp_BDt,Tmp_SDt)  days," + Constants.vbNewLine;
                    strSql += " cast(case Tmp_BSFlag when 'B' then Tmp_BRate when 'S' then Tmp_SRate else '' end as decimal(15,2))  Rate,ss_lname," + Constants.vbNewLine;
                    strSql += "  case Tmp_Flag when 'T' then 0 else (Case when right(tmp_sdt,4) between '0401' and '0615' then  1 " + Constants.vbNewLine;
                    strSql += " when right(tmp_sdt,4) between '0616' and '0915' then  2 " + Constants.vbNewLine;
                    strSql += " when right(tmp_sdt,4) between '0916' and '1215' then  3 " + Constants.vbNewLine;
                    strSql += " when right(tmp_sdt,4) between '0316' and '0331' then  5" + Constants.vbNewLine;
                    strSql += " else 4 end) end  QtrSlab, TMp_Scripcd +' [ ' +  ss_lname  + ' ]  ISIN : ' + Tmp_ISIN as scripcode  ,cast((Tmp_BStt*Tmp_Qty) + (Tmp_SStt*Tmp_Qty) as decimal(15,2)) STT,Tmp_LTCG,Tmp_ActualRate,Tmp_112ARate";
                    strSql += " from #TmpGainLoss ,Securities " + Constants.vbNewLine;
                    strSql += " Where Tmp_Scripcd = ss_cd " + Constants.vbNewLine;
                    strSql += " and Tmp_SDt between '" + FromDate + "' and '" + ToDate + "'" + Constants.vbNewLine;
                    if (!string.IsNullOrEmpty(Strings.Trim(scripCd)))
                    {
                        strSql += "  and TMp_Scripcd = '" + scripCd + "'" + Constants.vbNewLine;
                    }

                    strSql += " order by Tmp_Clientcd,ss_lname,case When Tmp_Flag in ('B','S') Then 1 else 0 end, convert(Char,Tmp_SDt,112),convert(Char,Tmp_BDt,112) ";
                    dt = objUtility.OpenDataTable(strSql, curCon);
                }

                if (dt?.Rows?.Count > 0)
                {
                    List<GainLossActualPLDetailResponse> gainLossActualPLDetails = new List<GainLossActualPLDetailResponse>();

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        gainLossActualPLDetails.Add(new GainLossActualPLDetailResponse
                        {
                            ClientCode = dt.Rows[i]["Tmp_Clientcd"].ToString(),
                            ScripCode = dt.Rows[i]["TMp_Scripcd"].ToString(),
                            ScripName = dt.Rows[i]["ss_lname"].ToString(),
                            ISIN = dt.Rows[i]["scripcode"].ToString(),
                            Qty = dt.Rows[0]["Tmp_Qty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Tmp_Qty"]),
                            SellDate = objUtility.dtos(dt.Rows[i]["Tmp_SDt"].ToString().Trim()),
                            SellRate = dt.Rows[0]["Tmp_SRate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Tmp_SRate"]),
                            BuyDate = objUtility.dtos(dt.Rows[i]["Tmp_BDt"].ToString().Trim()),
                            BuyRate = dt.Rows[0]["Tmp_BRate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Tmp_BRate"]),
                            Trading = dt.Rows[0]["Trading"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Trading"]),
                            LongTerm = dt.Rows[0]["LongTerm"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["LongTerm"]),
                            ShortTerm = dt.Rows[0]["ShortTerm"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["ShortTerm"]),
                            STT = dt.Rows[0]["STT"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["STT"]),
                            QtrSlab = dt.Rows[i]["QtrSlab"].ToString(),
                            LTCG = dt.Rows[i]["Tmp_LTCG"].ToString(),
                            Rate112A = dt.Rows[0]["Tmp_112ARate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Tmp_112ARate"]),
                            Cost = dt.Rows[0]["Rate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Rate"]),
                        });
                    }
                    return dt;
                }
                return null;
            }
            catch (Exception e)
            {
                throw e;
            }
        }

        public dynamic CapitalGainLoss_TradeListingDetail_Process(string ClientWhere, string fromDate, string toDate, string scripCode)
        {
            try
            {
                string strSql = "";
                DataTable dt = new DataTable();

                string connectionString = objUtility.GetConnectionStr();
                using (SqlConnection curCon = new SqlConnection(connectionString))
                {
                    curCon.Open();
                    strSql = " select Rtrim(td_clientcd) td_clientcd,td_srno,td_TRXFlag,case td_TRDType when 'DL' then 'Delivery' When 'SQ' then 'Jobbing' else '' end  td_TRDType , ";
                    strSql += " ltrim(rtrim(convert(char,convert(datetime,td_dt),103))) as td_dt,td_stlmnt ,";
                    strSql += " case td_bsflag when 'B' then 'Buy' when 'S' then 'Sell' else '' end td_bsflag , ";
                    strSql += " convert(decimal(15,0) , td_bqty+td_sqty) as Qty, ";
                    strSql += " convert(decimal(15,2) ,td_Rate) td_Rate,convert(decimal(15,2) ,td_Rate*(td_bqty+td_sqty)) Value , convert(decimal(15,2) ,td_ServiceTax*(td_bqty+td_sqty)) td_ServiceTax,";
                    strSql += " convert(decimal(15,2) ,td_STT *(td_bqty+td_sqty)) td_STT,convert(decimal(15,2) ,td_OtherChrgs1*(td_bqty+td_sqty)) td_OtherChrgs1,convert(decimal(15,2) ,td_OtherChrgs2*(td_bqty+td_sqty)) td_OtherChrgs2 ";
                    strSql += " from TRX_INVPL,Securities,Client_master where td_clientcd = cm_cd and td_scripcd = ss_cd ";
                    strSql += " and td_scripcd = '" + scripCode + "' and td_dt between '" + fromDate + "' and '" + toDate + "' " + ClientWhere;
