        public dynamic CapitalGainLoss_TradeInsert_Process(string userId, string date, string settlement, string bsFlag, string tradeType, double quantity, double netRate, double serviceTax, double STT, double otherCharge1, double otherCharge2, string scripcode)
        {
            try
            {
                DataSet ObjDataSet = new DataSet();
                double MarketRate = netRate;
                string strSql = "";
                int intAdvisory = 0;
                string strcomcode = objUtility.fnFireQuery("Entity_master", "min(em_cd)", "Len(Ltrim(Rtrim(em_cd)))", "1", false);

                if (date.ToString() != "")
                {
                    //date = objUtility.stod(date).ToString("dd/MM/yyyy").Replace('-', '/');
                    if (InvalidDateCheck(objUtility.stod(date).ToString("dd/MM/yyyy").Replace('-', '/')) == false)
                    {
                        throw new Exception("Invalid Date");
                    }
                }
                else
                {
                    throw new Exception("Date Cannot Be Blank");
                }
                if (quantity.ToString() == "" || Conversion.Val(quantity.ToString()) <= 0)
                {
                    throw new Exception("Quantity Cannot Be Blank !");
                }
                if (string.IsNullOrEmpty(scripcode))
                {
                    throw new Exception("Scrip Code Cannot Be Blank !");
                }

                if (string.IsNullOrWhiteSpace(objUtility.fnFireQueryTradeWeb("Securities", "ss_name", "ss_cd", scripcode, true)))
                {
                    throw new Exception("Security  Not Found");
                }
                if (objUtility.fnFireQueryTradeWeb("Settlements", "count(0)", "se_stlmnt", settlement, true) == "0")
                {
                    throw new Exception("Settlement not found");
                }
                if (!(tradeType == "DL" || tradeType == "SQ"))
                {
                    throw new Exception("Invalid  Trade  Type");
                }
                if (bsFlag != "B" && bsFlag != "S")
                {
                    throw new Exception("Invalid  B/S Flag");
                }
                if (Conversion.Val(quantity) <= 0d)
                {
                    throw new Exception("Quantity Should be greater than zero");
                }
                if (Conversion.Val(netRate) < 0d)
                {
                    throw new Exception("Rate Can not be Negative");
                }

                double dblservicetax, dblstt, dblchrg1, dblchrg2;
                dblservicetax = Math.Round((serviceTax / quantity), 4);
                dblstt = Math.Round((STT / quantity), 4);
                dblchrg1 = Math.Round((otherCharge1 / quantity), 4);
                dblchrg2 = Math.Round((otherCharge2 / quantity), 4);

                strSql = " insert into TRX_INVPL(td_companycode, td_dt,td_stlmnt,td_TRXFlag,td_TRDType,td_clientcd,td_scripcd,td_bsflag,td_bqty,";
                strSql += " td_Sqty,td_marketrate,td_brokerage,td_Rate,td_ServiceTax,td_STT,td_OtherChrgs1,td_OtherChrgs2,mkrid,mkrdt,";
                strSql += " td_Filler1 ,td_Filler2,td_Filler3,td_NFiller1,td_NFiller2,td_NFiller3,td_Remark)";
                strSql += " values('" + strcomcode + "','" + date + "', '" + settlement.ToString().Trim() + "','M','" + tradeType + "','" + Strings.Trim(userId).ToUpper() + "','" + Strings.Trim(scripcode) + "',";
                strSql += "'" + bsFlag + "', ";
                if (bsFlag == "B")
                {
                    strSql += " " + quantity + ",";
                    strSql += " 0 , ";
                }
                else
                {
                    strSql += " 0, ";
                    strSql += "" + quantity + ", ";
                }

                strSql += " " + netRate + ",0," + netRate + "," + dblservicetax + ",";
                strSql += " " + dblstt + ", " + dblchrg1 + "," + dblchrg2 + ",'" + userId.Trim().ToUpper() + ("','" + DateTime.Today.Date.ToString("yyyyMMdd") + "',");
                strSql += "'','',''," + intAdvisory + ",0,0,'')";
                int intRowAffected = objUtility.ExecuteSQLXML(strSql);

                if (intRowAffected > 0)
                {
                    return "Saved";
                }
                return null;
            }
            catch (Exception ex)
            {
                return ex;
            }
        }

        public dynamic CapitalGainLoss_NationalDetail_Process(string userId, string strDate, bool blnignore112A, string scripCd)
        {
            try
            {
                DataTable dt = new DataTable();
                string strSql = "";

                string connectionString = objUtility.GetConnectionStr();
                using (SqlConnection curCon = new SqlConnection(connectionString))
                {
                    curCon.Open();

                    prGainLoss("Notional", userId, strDate, strDate, scripCd, false, blnignore112A ? "Y" : "B", "", curCon);

                    strSql = " select Rtrim(Tmp_Clientcd) Tmp_Clientcd, case When Tmp_Flag not in ('B') and Tmp_SDt <> ''  Then ltrim(rtrim(convert(char,convert(datetime,Tmp_SDt),103)))  else ''  End  as Tmp_SDt," + Constants.vbNewLine;
                    strSql += " cast(Tmp_SRate as decimal(15,2)) Tmp_SRate , cast(case Tmp_Flag When 'S' Then -Tmp_Qty else Tmp_Qty End as decimal(15,0)) Tmp_Qty ," + Constants.vbNewLine;
                    strSql += " case when  Tmp_Flag not in ('S')and Tmp_BDt <> ''  then ltrim(rtrim(convert(char,convert(datetime,Tmp_BDt),103)))  else '' end as Tmp_BDt, cast(Tmp_BRate as decimal(15,2)) Tmp_BRate ," + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag in ('B','S') Then ((Tmp_BRate-Tmp_SRate)*Tmp_Qty) else 0 End as decimal(15,2)) StockAtCost," + Constants.vbNewLine;
                    strSql += " cast(Round (case When Tmp_Flag in ('B','S') Then ((Tmp_BRate-Tmp_SRate)*Tmp_Qty) else 0 End  /cast(case Tmp_Flag When 'S' Then -Tmp_Qty else Tmp_Qty End as decimal(15,3)),2,1) as decimal(15,2)) Avgrate,";
                    strSql += " cast(case When Tmp_Flag in ('B','S') Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End*Tmp_MarketRate  else 0 End as decimal(15,2)) StockAtMkt," + Constants.vbNewLine;
                    strSql += " cast(case Tmp_Flag When 'T'  Then ((Tmp_SRate-Tmp_BRate)*Tmp_Qty) else 0 End as decimal(15,2)) Trading ," + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag ='X' and dateDiff(d,Tmp_BDt,Tmp_SDt) >= 365 Then  ((Tmp_SRate-Tmp_BRate)*Tmp_Qty)  else 0 End as decimal(15,2)) LongTerm," + Constants.vbNewLine;
                    strSql += " cast(case When Tmp_Flag ='X' and dateDiff(d,Tmp_BDt,Tmp_SDt) < 365 Then  ((Tmp_SRate-Tmp_BRate)*Tmp_Qty)  else 0 End as decimal(15,2)) ShortTerm," + Constants.vbNewLine;
                    strSql += " CAST((case Tmp_Flag When 'B' Then (case when DATEDIFF(d,Tmp_BDt,'" + strDate + "') < 365 then Tmp_Qty*(Tmp_MarketRate-Tmp_BRate) else 0 end)" + Constants.vbNewLine;
                    strSql += " When 'S' Then  (case when DATEDIFF(d,Tmp_SDt,'" + strDate + "') < 365 then Tmp_Qty*(Tmp_SRate-Tmp_MarketRate)  else 0 end) " + Constants.vbNewLine;
                    strSql += " else 0 end) as decimal(15,2))  UnRealGainShort," + Constants.vbNewLine;
                    strSql += " CAST((case Tmp_Flag When 'B' Then (case when DATEDIFF(d,Tmp_BDt,'" + strDate + "') >= 365 then case when ((Tmp_LTCG='*') and Tmp_MarketRate < Tmp_BRate+Tmp_BStt) then 0 else Tmp_Qty*(Tmp_MarketRate-Tmp_BRate) end else 0 end)" + Constants.vbNewLine;
                    strSql += " When 'S' Then  (case when DATEDIFF(d,Tmp_SDt,'" + strDate + "') >= 365 then Tmp_Qty*(Tmp_SRate-Tmp_MarketRate)  else 0 end)" + Constants.vbNewLine;
                    strSql += " else 0 end) as decimal(15,2))  UnRealGainLong," + Constants.vbNewLine;
                    strSql += " case Tmp_Flag when 'T' then 'Trading' when 'X' then 'Delivery' when 'B' then 'Stock' when 'S' then 'Excess Sell' else '' end Type," + Constants.vbNewLine;
                    strSql += " case Tmp_Flag when 'B' then dateDiff(d,Tmp_BDt,'" + strDate + "') when 'S'   then dateDiff(d,Tmp_SDt,'" + strDate + "') else 0  end days," + Constants.vbNewLine;
                    strSql += " case Tmp_BSFlag when 'B' then ltrim(rtrim(convert(char,convert(datetime,Tmp_BDt),103))) when 'S' then ltrim(rtrim(convert(char,convert(datetime,Tmp_SDt),103))) else '' end TrxDate," + Constants.vbNewLine;
                    strSql += " cast(Tmp_MarketRate as decimal(15,2))  Rate, TMp_Scripcd,ss_lname,TMp_Scripcd +' [ ' +  ss_lname  + ' ] ' + '  ISIN : ' + Tmp_ISIN as scripcode,cast((Tmp_BStt*Tmp_Qty)+ (Tmp_SStt*Tmp_Qty) as decimal(15,2)) STT,Tmp_LTCG,Tmp_ActualRate,cast(Tmp_112ARate as decimal(15,2)) Tmp_112ARate" + Constants.vbNewLine;
                    strSql += " from #TmpGainLoss ,Securities " + Constants.vbNewLine;
                    strSql += " Where  Tmp_Flag in ('B','S') and  Tmp_Scripcd = ss_cd" + Constants.vbNewLine;
                    if (!string.IsNullOrEmpty(Strings.Trim(scripCd)))
                    {
                        strSql += "  and TMp_Scripcd = '" + scripCd + "'" + Constants.vbNewLine;
                    }

                    strSql += " order by Tmp_Clientcd,ss_lname,case Tmp_Flag When  'B' Then Tmp_BDt when  'S' then Tmp_SDt end ,Tmp_SDt,Tmp_BDt" + Constants.vbNewLine;
                    dt = objUtility.OpenDataTable(strSql, curCon);
                }

                if (dt?.Rows?.Count > 0)
                {
                    List<GainLossNationalDetailResponse> gainLossNationalDetails = new List<GainLossNationalDetailResponse>();
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        gainLossNationalDetails.Add(new GainLossNationalDetailResponse
                        {
                            ClientCode = dt.Rows[i]["Tmp_Clientcd"].ToString(),
                            date = dt.Rows[i]["TrxDate"].ToString(),
                            ScripCode = dt.Rows[i]["Tmp_Scripcd"].ToString(),
                            ScripName = dt.Rows[i]["ss_lname"].ToString(),
                            ISIN = dt.Rows[i]["scripcode"].ToString(),
                            Qty = dt.Rows[i]["Tmp_Qty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Tmp_Qty"].ToString()),
                            Rate = dt.Rows[i]["Avgrate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Avgrate"].ToString()),
                            Cost = dt.Rows[i]["StockAtCost"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["StockAtCost"].ToString()),
                            ClosingRate = dt.Rows[i]["Rate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Rate"].ToString()),
                            ClosingAmount = dt.Rows[i]["StockAtMkt"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["StockAtMkt"].ToString()),
                            ShortTerm = dt.Rows[i]["UnRealGainShort"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["UnRealGainShort"].ToString()),
                            LongTerm = dt.Rows[i]["UnRealGainLong"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["UnRealGainLong"].ToString()),
                            STT = dt.Rows[i]["STT"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["STT"].ToString()),
                            Days = dt.Rows[i]["days"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["days"].ToString()),
                            Rate112A = dt.Rows[i]["Tmp_112ARate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Tmp_112ARate"].ToString()),
                            LTCG = dt.Rows[i]["Tmp_LTCG"].ToString(),
                        });
                    }
                    return gainLossNationalDetails;
                }
                return null;
            }
            catch (Exception e)
            {
                throw e;
            }
        }

        public dynamic CapitalGainLoss_NationalSummary_Process(string strClientWhere, string strDate, Boolean blnIgnoreSection)
        {
            try
            {
                DataTable dt = new DataTable();
                string strSql = "";

                string connectionString = objUtility.GetConnectionStr();
                using (SqlConnection curCon = new SqlConnection(connectionString))
                {
                    curCon.Open();

                    prGainLoss("Notional", strClientWhere, strDate, strDate, "", false, blnIgnoreSection ? "Y" : "N", "", curCon);

                    strSql = " select Rtrim(Tmp_Clientcd) Tmp_Clientcd,Tmp_Scripcd,Tmp_Flag,ss_lname , cast(Sum(case Tmp_Flag When 'S'  Then 0 else Tmp_Qty End) as decimal(15,0)) BQty," + Constants.vbNewLine;
                    strSql += " Sum(case Tmp_Flag When 'S'  Then 0 else  CAST((Tmp_BRate* Tmp_Qty) as decimal(15,2))  End) BAmount, cast(Sum(case Tmp_Flag When 'B'  Then 0 else Tmp_Qty End) as decimal(15,0)) SQty," + Constants.vbNewLine;
                    strSql += " Sum(case Tmp_Flag When 'B'  Then 0 else   cast((Tmp_SRate* Tmp_Qty) as decimal(15,2))  End) SAmount," + Constants.vbNewLine;
                    strSql += " cast(Sum (case When Tmp_Flag in ('B','S')  Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End else 0 End) as decimal(15,0))  NetQty," + Constants.vbNewLine;
                    strSql += " Sum(case When Tmp_Flag in ('B','S')  Then cast(((Tmp_BRate-Tmp_SRate)*Tmp_Qty) as decimal(15,2)) else 0 End) StockAtCost," + Constants.vbNewLine;
                    //  strSql += " cast(Sum(case When Tmp_Flag in ('B','S')  Then cast(((Tmp_BRate-Tmp_SRate)*Tmp_Qty) as decimal(15,2)) else 0 End) /  cast(Sum (case When Tmp_Flag in ('B','S')  Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End else 0 End) as decimal(15,0)) as decimal(15,2)) HoldingRate," + Constants.vbNewLine;
                    strSql += " Sum(case Tmp_Flag When 'T'  Then   cast(((Tmp_SRate-Tmp_BRate)*Tmp_Qty) as decimal(15,2))  else 0 End) Trading,";
                    strSql += " Sum(case When Tmp_Flag = 'X' and dateDiff(d,Tmp_BDt,Tmp_SDt) < 365  Then cast(((Tmp_SRate-Tmp_BRate)*Tmp_Qty) as decimal(15,2)) else 0 End) ShortTerm," + Constants.vbNewLine;
                    strSql += " Sum(case When Tmp_Flag ='X' and dateDiff(d,Tmp_BDt,Tmp_SDt) >= 365 Then  cast(((Tmp_SRate-Tmp_BRate)*Tmp_Qty) as decimal(15,2)) else 0 End) LongTerm, cast(Tmp_MarketRate as decimal(15,2)) MarketRate," + Constants.vbNewLine;
                    strSql += " CAST((Sum(case When Tmp_Flag in ('B','S')  Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End*Tmp_MarketRate else 0 End)) as decimal(15,2)) StockAtMkt," + Constants.vbNewLine;
                    strSql += " CAST((Sum( case Tmp_Flag When 'B' Then (case when DATEDIFF(d,Tmp_BDt,'" + strDate + "') < 365 then Tmp_Qty*(Tmp_MarketRate-Tmp_BRate) else 0 end)";
                    strSql += " When 'S' Then  (case when DATEDIFF(d,'" + strDate + "',Tmp_SDt) < 365 then Tmp_Qty*(Tmp_SRate-Tmp_MarketRate)  else 0 end) ";
                    strSql += " else 0 end)) as decimal(15,2))  UnRealGainShort,";
                    strSql += " CAST((Sum( case Tmp_Flag When 'B' Then (case when DATEDIFF(d,Tmp_BDt,'" + strDate + "') >= 365 then case when ((Tmp_LTCG='*') and Tmp_MarketRate < Tmp_BRate+Tmp_BStt) then 0 else Tmp_Qty*(Tmp_MarketRate-Tmp_BRate) end else 0 end)";
                    strSql += " When 'S' Then  (case when DATEDIFF(d,'" + strDate + "',Tmp_SDt) >= 365 then Tmp_Qty*(Tmp_SRate-Tmp_MarketRate)  else 0 end)";
                    strSql += " else 0 end)) as decimal(15,2))  UnRealGainLong,";
                    strSql += " cast(sum((Tmp_BStt*Tmp_Qty)+ (Tmp_SStt*Tmp_Qty)) as decimal(15,2)) STT,Tmp_ISIN" + Constants.vbNewLine;
                    strSql += " from #TmpGainLoss,Securities,Client_master,Branch_master Where Tmp_Clientcd = cm_cd and Tmp_Flag in ('B','S') and  Tmp_Scripcd = ss_cd and cm_brboffcode = bm_branchcd Group By Tmp_Clientcd,Tmp_Scripcd,ss_lname ,Tmp_MarketRate ,Tmp_Flag,Tmp_ISIN, bm_branchcd  " + Constants.vbNewLine;
                    // strSql += " having abs(round(Sum (case When Tmp_Flag in ('B','S')  Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End else 0 End),0)) > 0";
                    strSql += "Order by Tmp_Clientcd, Tmp_Flag, ss_lname ";
                    dt = objUtility.OpenDataTable(strSql, curCon);
                }

                if (dt?.Rows?.Count > 0)
                {
                    List<GainLossNationalSummaryResponse> gainLossNationalSummaries = new List<GainLossNationalSummaryResponse>();

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        double cost = dt.Rows[i]["StockAtCost"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["StockAtCost"]);
                        double qty = dt.Rows[i]["NetQty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["NetQty"]);
                        qty = qty == 0 ? 1 : qty;
                        gainLossNationalSummaries.Add(new GainLossNationalSummaryResponse
                        {
                            ClientCode = dt.Rows[i]["Tmp_Clientcd"].ToString(),
                            ScripCode = dt.Rows[i]["Tmp_Scripcd"].ToString(),
                            ScripName = dt.Rows[i]["ss_lname"].ToString(),
                            ISIN = dt.Rows[i]["Tmp_ISIN"].ToString(),
                            Qty = dt.Rows[i]["NetQty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["NetQty"]),
                            Cost = dt.Rows[i]["StockAtCost"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["StockAtCost"]),
                            Rate = cost / qty,
                            //dt.Rows[i]["HoldingRate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["HoldingRate"]),
                            ClosingRate = dt.Rows[i]["MarketRate"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["MarketRate"]),
                            ClosingAmount = dt.Rows[i]["StockAtMkt"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["StockAtMkt"]),
                            ShortTerm = dt.Rows[i]["UnRealGainShort"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["UnRealGainShort"]),
                            LongTerm = dt.Rows[i]["UnRealGainLong"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["UnRealGainLong"]),
                            STT = dt.Rows[i]["STT"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["STT"]),
                        });
                    }

                    return gainLossNationalSummaries;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        private void prGainLoss(string ReportType, string strClientWhere, string strFromDt, string strToDt, string strScripCd, bool blndividend = true, string strIgnoresection = "N", string AdvisoryTrade = "I", SqlConnection curCon = null)
        {
            DataTable dtTestFrom;

            string strSql = "";
            string strRateYear = "2018";
            bool blnTrdStlmnt;
            bool blnIncSttDel;
            bool blnIncSttTrd;

            //  strToDt = "20210219";
            DataTable dtFrom;
            DataTable dtTo;
            blnTrdStlmnt = Convert.ToBoolean((objUtility.GetSysParmSt("TRDPLONSTLMT", "") == "Y") ? true : false);
            blnIncSttDel = Convert.ToBoolean((objUtility.GetSysParmSt("GAINLOSSTTDL", "") == "Y") ? true : false);
            blnIncSttTrd = Convert.ToBoolean((objUtility.GetSysParmSt("GAINLOSSTTTR", "") == "Y") ? true : false);


            prCreateTempTableGainLoss(curCon);
            try
            {
                strSql = "Insert into #TmpTRX ";
                strSql += " select td_SRNO,td_NFiller2,td_dt, td_Stlmnt,td_TRXFlag ,td_TRDType,td_clientcd ,td_scripcd ,td_bsflag ,td_bqty,td_Sqty,td_Rate ,Round(td_ServiceTax+td_OtherChrgs1+td_OtherChrgs2,4),td_STT,td_Filler2,td_Remark,td_Filler1";
                strSql += " From TRX_INVPL, Client_mAster ,Branch_master Where cm_cd=td_clientcd and cm_brboffcode = bm_branchcd and td_dt <= '" + strToDt + "' " + strClientWhere;

                if (strScripCd != "")
                {
                    strSql += " and td_scripcd = '" + strScripCd + "'";
                }

                if (ReportType == "Notional")
                {
                    // strSql += " and td_Filler2 = 'D' ";
                    strSql += " and isNull(td_Filler2,'') <> 'T' ";
                }

                if (AdvisoryTrade == "E")
                {
                    strSql += " and td_NFiller1 <> 1 ";
                }
                else if (AdvisoryTrade == "O")
                {
                    strSql += " and td_NFiller1 = 1 ";
                }

                strSql += " Order by td_clientcd,td_scripcd ,td_dt,td_TRXFlag,td_TRDType,td_Stlmnt,td_bsflag";
                objUtility.ExecuteSQL(strSql, curCon);

                if (ReportType == "Notional")
                {
                }
                else
                {
                    strSql = " select * from #TmpTRX Where Tmp_RefNo > 0 Order by Tmp_tdSRNO ";

                    dtFrom = objUtility.OpenDataTable(strSql, curCon);

                    for (int lngFrom = 0; lngFrom < dtFrom.Rows.Count; lngFrom++)
                    {
                        strSql = " Update a set a.Tmp_Bqty = a.Tmp_Bqty - b.Tmp_sqty ";
                        strSql += "  From #TmpTRX a , #TmpTRX b ";
                        strSql += " Where a.Tmp_tdSRNO = " + dtFrom.Rows[lngFrom]["Tmp_tdSRNO"] + " and b.Tmp_tdSRNO  = " + dtFrom.Rows[lngFrom]["Tmp_RefNo"];
                        objUtility.ExecuteSQL(strSql, curCon);
                        strSql = " Delete #TmpTRX ";
