        private dynamic GainLossPL_Summary(string ClientWhere, string FromDate, string ToDate, bool blnIgnoreSection)
        {
            try
            {
                //DataSet ds = new DataSet();
                DataTable dt = new DataTable();
                string strSql = "";
                string strwhere = "";

                string connectionString = objUtility.GetConnectionStr();
                using (SqlConnection curCon = new SqlConnection(connectionString))
                {
                    curCon.Open();
                    prGainLoss("ActualPL", ClientWhere, FromDate, ToDate, "", false, blnIgnoreSection ? "Y" : "N", "", curCon);
                    strwhere = "Tmp_SDt between '" + FromDate + "' and '" + ToDate + "' and ";

                    strSql = " select Rtrim(Tmp_Clientcd) Tmp_Clientcd,Tmp_Scripcd,ss_lname ,Tmp_ISIN, cast(Sum(case Tmp_Flag When 'S' Then 0 else Tmp_Qty End) as decimal(15,0)) BQty," + Constants.vbNewLine;
                    strSql += " Sum(case Tmp_Flag When 'S'  Then 0 else  CAST((Tmp_BRate* Tmp_Qty) as decimal(15,2))  End) BAmount, cast(Sum(case Tmp_Flag When 'B'  Then 0 else Tmp_Qty End) as decimal(15,0)) SQty," + Constants.vbNewLine;
                    strSql += " Sum(case Tmp_Flag When 'B'  Then 0 else   cast((Tmp_SRate* Tmp_Qty) as decimal(15,2))  End) SAmount," + Constants.vbNewLine;
                    strSql += "  cast(Sum (case When Tmp_Flag in ('B','S')  Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End else 0 End) as decimal(15,0))  NetQty," + Constants.vbNewLine;
                    strSql += " Sum(case When Tmp_Flag in ('B','S')  Then cast(((Tmp_BRate-Tmp_SRate)*Tmp_Qty) as decimal(15,2)) else 0 End) StockAtCost," + Constants.vbNewLine;
                    strSql += " Sum(case Tmp_Flag When 'T'  Then   cast(((Tmp_SRate-Tmp_BRate)*Tmp_Qty) as decimal(15,2))  else 0 End) Trading," + Constants.vbNewLine;
                    strSql += " Sum(case When Tmp_Flag = 'X' and dateDiff(d,Tmp_BDt,Tmp_SDt) < 365  Then cast(((Tmp_SRate-Tmp_BRate)*Tmp_Qty) as decimal(15,2)) else 0 End) ShortTerm," + Constants.vbNewLine;
                    strSql += " Sum(case When Tmp_Flag ='X' and dateDiff(d,Tmp_BDt,Tmp_SDt) >= 365 Then  case when ((Tmp_LTCG='*') and (Tmp_SRate+Tmp_SStt) < Tmp_BRate) then 0 else  cast(((Tmp_SRate-Tmp_BRate)*Tmp_Qty) as decimal(15,2)) end else 0 End) LongTerm, Tmp_MarketRate MarketRate," + Constants.vbNewLine;
                    strSql += " CAST((Sum(case When Tmp_Flag in ('B','S')  Then case Tmp_Flag When 'B' Then Tmp_Qty else -Tmp_Qty End*Tmp_MarketRate else 0 End)) as decimal(15,2)) StockAtMkt," + Constants.vbNewLine;
                    strSql += " CAST((Sum( case Tmp_Flag When 'B' Then Tmp_Qty*(Tmp_MarketRate-Tmp_BRate) When 'S' Then Tmp_Qty*(Tmp_SRate-Tmp_MarketRate) else 0 end)) as decimal(15,2))  UnRealGain ,cast(sum((Tmp_BStt*Tmp_Qty)+ (Tmp_SStt*Tmp_Qty)) as decimal(15,2)) STT" + Constants.vbNewLine;
                    strSql += " from #TmpGainLoss,Securities Where " + strwhere + " Tmp_Scripcd = ss_cd and Tmp_Flag in ('T','X') Group By Tmp_Clientcd,Tmp_Scripcd,ss_lname ,Tmp_ISIN ,Tmp_MarketRate  Order by Tmp_Clientcd,ss_lname " + Constants.vbNewLine;

                    dt = objUtility.OpenDataTable(strSql, curCon);
                }

                if (dt?.Rows.Count > 0 && dt?.Rows?.Count > 0)
                {
                    List<GainLossActualPLSummaryResponse> gainLossActualPLSummaries = new List<GainLossActualPLSummaryResponse>();

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        gainLossActualPLSummaries.Add(new GainLossActualPLSummaryResponse
                        {
                            ClientCode = dt.Rows[i]["Tmp_Clientcd"].ToString(),
                            ScripCode = dt.Rows[i]["Tmp_Scripcd"].ToString(),
                            ScripName = dt.Rows[i]["ss_lname"].ToString(),
                            ISIN = dt.Rows[i]["Tmp_ISIN"].ToString(),
                            BuyQty = dt.Rows[i]["BQty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["BQty"]),
                            BuyAmount = dt.Rows[i]["BAmount"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["BAmount"]),
                            SellQty = dt.Rows[i]["SQty"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["SQty"]),
                            SellAmount = dt.Rows[i]["SAmount"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["SAmount"]),
                            Trading = dt.Rows[i]["Trading"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["Trading"]),
                            ShortTerm = dt.Rows[i]["ShortTerm"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["ShortTerm"]),
                            LongTerm = dt.Rows[i]["LongTerm"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["LongTerm"]),
                            STT = dt.Rows[i]["STT"].ToString() == "" ? 0.0 : Convert.ToDouble(dt.Rows[i]["STT"]),
                        });
                    }
                    return gainLossActualPLSummaries;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

