                    //        }
                    //    }
                    //}

                    if (dt.Rows.Count > 0)
                    {
                        List<GainLossActualPLDetailsResponse> gainLossActualPLSummaries = new List<GainLossActualPLDetailsResponse>();

                        for (int i = 0; i < dt.Rows.Count; i++)
