        //// Insert Fund Request value after button click
        public dynamic Request_Post_FundRequest(FundRequest_Model model, string userId)
        {
            try
            {
                bool blnIdentityOn = false;
                DataSet Dstemp = new DataSet();
                string StrDTTm = "";
                StrDTTm = objUtility.GetWebParameter("FP_CL_RQ_TM");
                Dstemp = objUtility.OpenDataSet("SELECT isnull (IDENT_CURRENT('FundsRequest'),0)");
                long intcnt = 0;
                if (Convert.ToInt64(Dstemp.Tables[0].Rows[0][0]) > 0)
                {
                    blnIdentityOn = true;
                    DataSet DsReqId = new DataSet();
                    DsReqId = objUtility.OpenDataSet("SELECT IDENT_CURRENT('FundsRequest')");
                    intcnt = Convert.ToInt64(DsReqId.Tables[0].Rows[0][0]);
                }
                else
                {
                    blnIdentityOn = false;
                    DataSet Dsmax = new DataSet();
                    Dsmax = objUtility.OpenDataSet("SELECT isNull(Max(Rq_srNo),0) from FundsRequest");
                    intcnt = Convert.ToInt64(Dsmax.Tables[0].Rows[0][0]) + 1;
                }
                if (StrDTTm != "")
                {
                    string[] arrStrDtTm;
                    char[] Separators = new char[1];
                    Separators[0] = ',';
                    arrStrDtTm = StrDTTm.Split(Separators);
                    DataSet Dstime = new DataSet();
                    Dstime = objUtility.OpenDataSet("select substring(convert(char,convert(datetime,GETDATE()),108),1,5) as Times");
                    string strTime = Dstime.Tables[0].Rows[0]["Times"].ToString().Trim();

                    if ((Convert.ToDateTime(arrStrDtTm[0].ToString()) > Convert.ToDateTime(strTime.ToString())) || (Convert.ToDateTime(arrStrDtTm[1].ToString()) < Convert.ToDateTime(strTime.ToString())))
                    {
                        return "Payout Request can be Post between " + arrStrDtTm[0] + " and " + arrStrDtTm[1] + " hours";
                    }
                }
                string rtnMessage = "No record found";
                string gstrToday = DateTime.Today.ToString("yyyyMMdd");
                string strHostAdd = Dns.GetHostName();
                if (_configuration["IsTradeWeb"] == "O")//live
                {
                    double rmsAmount = model.rmsAmt;
                    double totalReq = model.totalReqAmt;
                    if (totalReq > rmsAmount && Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Sysparameter", "count(0)", "sp_parmcd Like 'RMSHEAD%' and sp_sysvalue", "FUNDPAYOUT", true)) > 0)
                    {
                        return "Request Amount is greater than RMS Amount.";
                    }
                    if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("PayOut_release", "count(*)", "rq_relflag='N' and rq_clientcd", userId, true)) > 0)
                    {
                        if (totalReq > model.branchReqAmt)
                        {
                            return "Request Amount Can Not Be Greater Than Branch Request Amount.";
                        }
                        else
                        {
                            objUtility.ExecuteSQL(" Update PayOut_release set rq_relflag = 'R' where rq_clientcd='" + userId + "' and rq_relflag = 'N'");
                        }
                    }
                    rtnMessage = "Request amount should be greater then zero";
                    objUtility.ExecuteSQL("delete  from FundsRequest  where rq_clientcd='" + userId + "' and  Rq_Satus1 = 'P' "); //// Delete all records
                    foreach (var val in model.data)
                    {
                        val.Amount = objUtility.mfnReplaceForSQLInjection(val.Amount);
                        double amt = Conversion.Val(val.Amount);
                        string rqNote = val.CESCd;
                        rqNote = objUtility.mfnReplaceForSQLInjection(rqNote);
                        if (amt > 0)
                        {
                            rtnMessage = "Your request has been registered.";
                            if (blnIdentityOn)
                            {
                                strsql = "insert into FundsRequest values ( ";
                            }
                            else
                            {
                                strsql = "insert into FundsRequest values ( " + intcnt + ", ";
                            }
                            strsql += " '" + userId + "','A'," + Conversion.Val(amt) + ",'" + strHostAdd + "',";
                            strsql += " '" + gstrToday + "',";
                            strsql += " convert(char(8),getdate(),108),";
                            strsql += " 'P','P','P','" + objUtility.Encrypt(gstrToday).ToString().Trim() + "','" + rqNote + "'";
                            if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Information_Schema.Columns", "count(*)", "Table_Name='FundsRequest' and Column_Name", "rq_bankactno", true)) > 0)
                            {
                                strsql += ",''";
                            }
                            strsql += ")";
                            objUtility.ExecuteSQL(strsql);
                        }
                    }
                    return rtnMessage;
                }
                else
                {
                    string StrRs = string.Empty;
                    string StrType = string.Empty;
                    //if (RdBtnRs.Checked == true && objUtility.mfnReplaceForSQLInjection(txtRs.Text) == "")
                    //{
                    //    return " Rs. Can not be left blank!";
                    //}
                    //if (RdBtnRs.Checked == true)
                    //{
                    //    StrRs = objUtility.mfnReplaceForSQLInjection(txtRs.Text);
                    //    StrType = "A";
                    //}
                    //if (RdBtnMaxPossible.Checked == true)
                    //{
                    //    StrRs = "";
                    //    StrType = "M";
                    //}
                    StrRs = "";
                    StrType = "A";
                    if (objUtility.fnFireQueryTradeWeb("FundsRequest", "count(*)", "Rq_Clientcd", userId + "' and Rq_Satus1= 'P", true) != "0")
                    {
                        return " Request Already Exists.";
                    }

                    if (blnIdentityOn)
                        strsql = "insert into FundsRequest values ( ";
                    else
                        strsql = "insert into FundsRequest values ( " + intcnt + ",";

                    strsql += " '" + userId + "','" + StrType + "','" + StrRs + "','" + strHostAdd + "',";
                    strsql += " '" + gstrToday + "',";
                    strsql += " convert(char(8),getdate(),108),";
                    strsql += " 'P','P','P','" + objUtility.Encrypt(gstrToday) + "','')";
                    objUtility.ExecuteSQL(strsql);

                    if (objUtility.fnFireQueryTradeWeb("WebParameter", "SP_SysValue", "sp_parmcd", "REQ_HOEMAIL", true) != "")
                    {
                        string StrClientName = objUtility.fnFireQueryTradeWeb("Client_master", "cm_name", "cm_cd", userId, true);
                        string strHost = string.Empty;
                        int intPort;
                        string strUserID = string.Empty;
                        string strPWD = string.Empty;
                        string strEmail = string.Empty;
                        DataSet ds = new DataSet();
                        string strBody;
                        strHost = objUtility.GetWebParameter("SMTPHOST");
                        intPort = Convert.ToInt16(objUtility.GetWebParameter("SMTPPORT"));
                        strUserID = objUtility.GetWebParameter("SMTPUSER");
                        strPWD = objUtility.GetWebParameter("SMTPPWD");
                        strEmail = objUtility.GetWebParameter("SMTPEMAIL");
                        MailMessage Msg = new MailMessage();
                        // Sender e-mail address.
                        strsql = "Select * from WebParameter where sp_parmcd = 'REQ_HOEMAIL'";
                        ds = objUtility.OpenDataSet(strsql);

                        if (ds.Tables[0].Rows.Count > 0)
                        {
                            Msg.From = new MailAddress(strEmail);
                            // Recipient e-mail address.
                            Msg.To.Add(ds.Tables[0].Rows[0]["SP_SysValue"].ToString().Trim());
                            Msg.Subject = " Funds Request Of Client " + StrClientName + " [ " + userId + " ]";
                            strBody = " Funds Request Of Client " + StrClientName + " [ " + userId + " ]<br/> Request No : " + intcnt + "<br/> Request Date : " + System.DateTime.Today.Date.ToShortDateString() + "";
                            //if (RdBtnRs.Checked == true)
                            //{
                            strBody += "<br/> For Rs : " + objUtility.mfnReplaceForSQLInjection(StrRs) + "";
                            //}
                            //else if (RdBtnMaxPossible.Checked == true)
                            //{
                            //    strBody += "<br/> Maximum Possible";
                            //}
                            Msg.Body = strBody;

                            Msg.IsBodyHtml = true;
                            // your remote SMTP server IP.
                            SmtpClient smtp = new SmtpClient();
                            smtp.Host = strHost;
                            smtp.Port = intPort;
                            smtp.Credentials = new System.Net.NetworkCredential(strEmail, strPWD);
                            smtp.EnableSsl = true;
                            System.Net.ServicePointManager.ServerCertificateValidationCallback = delegate (object s,
                            System.Security.Cryptography.X509Certificates.X509Certificate certificate,
                            System.Security.Cryptography.X509Certificates.X509Chain chain,
                            System.Net.Security.SslPolicyErrors sslPolicyErrors)
                            {
                                return true;
                            };
                            smtp.Send(Msg);
                        }
                    }
                    rtnMessage = "Your request has been registered with reference ID :" + intcnt;
                }

                return rtnMessage;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic Request_Report_Setting()
        {
            try
            {
                string STTCert = "", STTYear = "", Ledger = "", PNL = "", DPHold = "", RetHold = "", Fund = "", MaxFund = "", FundShare = "";
                strsql = "select * from Webparameter where sp_parmcd in ('REQ_STT','REQ_STTCURRYR','REQ_LEDGER','REQ_PNL','REQ_DPHLD','REQ_BENHLD','REQ_FUNDS','REQ_FUNDSMAX','REQ_SHARES')";
                DataTable dt = objUtility.OpenDataTable(strsql);
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_BENHLD")
                    {
                        RetHold = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_DPHLD")
                    {
                        DPHold = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_LEDGER")
                    {
                        Ledger = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_PNL")
                    {
                        PNL = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_STT")
                    {
                        STTCert = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_STTCURRYR")
                    {
                        STTYear = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_FUNDS")
                    {
                        Fund = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_FUNDSMAX")
                    {
                        MaxFund = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                    else if (dt.Rows[i]["sp_parmcd"].ToString().Trim() == "REQ_SHARES")
                    {
                        FundShare = dt.Rows[i]["sp_sysvalue"].ToString().Trim();
                    }
                }

                Dictionary<string, object> DictData = new Dictionary<string, object>();
                if (STTCert != "N")
                {
                    DictData.Add("STTCertificate", new Dictionary<string, string>()
                    {
                        {"PastYears", STTCert},
                        {"CurrentYear", STTYear}
                    });
                }
                if (Fund != "N")
                {
                    DictData.Add("FundPayout", new Dictionary<string, string>()
                    {
                        {"MaximumPossible", MaxFund}
                    });
                }
                if (FundShare != "N")
                {
                    DictData.Add("SharePayout", FundShare);
                }
                if (Ledger != "N")
                {
                    DictData.Add("Ledger_Transaction", new Dictionary<string, string>()
                    {
                        {"PastYears", Ledger}
                    });
                }
                if (PNL != "N")
                {
                    DictData.Add("ProfitLossStatement", new Dictionary<string, string>()
                    {
                        {"PastYears", PNL}
                    });
                }
                if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("WebParameter", "count(*)", "sp_parmcd", "REQ_DPHLD", true)) > 0)
                {
                    if (DPHold != "N")
                    {
                        DictData.Add("DPHolding", new Dictionary<string, string>()
                        {
                           {"PastYears", DPHold}
                        });
                    }
                }
                if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("WebParameter", "count(*)", "sp_parmcd", "REQ_BENHLD", true)) > 0)
                {
                    if (RetHold != "N")
                    {
                        DictData.Add("RetainedHolding", new Dictionary<string, string>()
                        {
                           {"PastYears", RetHold}
                        });
                    }
                }

                return DictData;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        #region Request usefull method


        //// Radio button shares checked
        private DataSet Request_Get_ShareRequest_Query(string cm_cd)
        {

            strsql = "select dm_scripcd ScripCode,isNull(IM_ISIN,'') ISIN,ss_Name ScripName,sum(-dm_qty) Quantity ,";
            strsql += "  CAST(sum(-dm_qty *(case when ss_bseratedt > ss_nseratedt then ss_bserate else ss_nserate end)) as decimal(15,2)) Value,";
            strsql += " isNull((select sum(Rq_Qty) From SharesRequest Where Rq_Clientcd = '" + cm_cd + "' and Rq_Scripcd=dm_scripcd and Rq_Satus1 = 'P'),0) Request, ";
            strsql += " (case when ss_bseratedt > ss_nseratedt then ss_bserate else ss_nserate end) Rate";
            strsql += " From Demat left outer join ISIN on dm_scripcd = im_scripcd  ,settlements,ourdps,SECURITIES";
            strsql += " Where dm_type = 'BC' and dm_locked = 'N' and dm_transfered = 'N'and dm_stlmnt = se_stlmnt and dm_ourdp = od_cd and dm_Scripcd = ss_cd";
            strsql += " and dm_clientcd = '" + cm_cd + "' and im_active = 'Y' ";
            strsql += " and im_priority =(select min(im_priority) from ISIN  Where im_active = 'Y'  and im_scripcd = dm_Scripcd)";
            strsql += " and od_acttype  in ('B','M') and se_shpayoutdt <= CONVERT(CHAR,getdaTE(),112)Group by dm_scripcd ,ss_Name,IM_ISIN,ss_bseratedt,ss_nseratedt,ss_bserate,ss_nserate  having (sum(-dm_qty)) >0order by ss_Name ";

            return objUtility.OpenDataSet(strsql);
        }

        //// Get rms request
        private PayOut_FundRequest Request_Get_FundRequest_Query(string userId)
        {
            DataSet Dstemp = new DataSet();
            StringBuilder strsql = new StringBuilder();
            strsql.Append("select  (ltrim(rtrim(ces_exchange)) + '/' + ltrim(rtrim(ces_segment)))Exch ,cm_cd ,cm_name,ld_dpid,  cast((-1*sum(ld_amount)) as decimal(15,2)) amt, ");
            strsql.Append(" isNull((select CAST(Sum(Rq_Amount) as decimal(15,2)) from FundsRequest Where rq_clientcd = ld_clientcd and Rq_Note = ld_dpid and Rq_Satus1 = 'P' ),0) rq_amt ");
            strsql.Append(" from  Client_Master, companyexchangesegments, Ledger ");
            strsql.Append(" where ld_clientcd = cm_cd and CES_Cd=ld_dpid  and ld_clientcd = '" + userId + "'  ");
            strsql.Append("group by  ld_clientcd ,cm_brkggroup,cm_cd,cm_name,ld_dpid,ltrim(rtrim(ces_exchange)) + '/' + ltrim(rtrim(ces_segment)),ld_dpid,ld_clientcd having abs(sum(ld_amount)) > 0");

            Dstemp = objUtility.OpenDataSet(strsql.ToString());

            if (Dstemp.Tables[0].Rows.Count > 0)
            {
                PayOut_FundRequest payOutRequest = new PayOut_FundRequest();
                double rmsAmount = 0;
                double BranchRequest = 0;
                payOutRequest.Data = new List<FundRquest>();

                for (int i = 0; i < Dstemp.Tables[0].Rows.Count; i++)
                {
                    payOutRequest.Data.Add(new FundRquest
                    {
                        ExchSeg = Dstemp.Tables[0].Rows[i]["Exch"].ToString(),
                        CESCd = Dstemp.Tables[0].Rows[i]["ld_dpid"].ToString(),
                        PayOut = Convert.ToDouble(Dstemp.Tables[0].Rows[i]["amt"]),
                        ReqAmt = Convert.ToDouble(Dstemp.Tables[0].Rows[i]["rq_amt"]),
                    });
                }

                if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Sysparameter", "count(0)", "sp_parmcd Like 'RMSHEAD%' and sp_sysvalue", "FUNDPAYOUT", true)) > 0)
                {
                    rmsAmount = Convert.ToDouble(objUtility.fnFireQueryTradeWeb("Rms_summary", "isnull(CAST((-1 * sum(rs_fundpayout)) as decimal(15,2)),0) Rmsamt", " rs_Dt = (select MAX(rs_Dt) From RMS_Summary)  and  rs_clientcd", userId, true));
                }

                BranchRequest = Microsoft.VisualBasic.Conversion.Val(objUtility.fnFireQueryTradeWeb("PayOut_release", "isnull(cast(sum(rq_amt) as decimal(15,2)),0) rq_amt", "rq_relflag='N' and rq_clientcd", userId, true));

                payOutRequest.RmsAmount = rmsAmount;
                payOutRequest.BranchRequest = BranchRequest;

                return payOutRequest;
            }
            else
            {
                return null;
            }
        }

        #region Request Report module

        private string Request_Post_Process_Report(string userId, string strLstSeg, string cmbRequest, string strFromDt, string strToDt)
        {
            if (cmbRequest == "DP Holding" || cmbRequest == "Retained Holding")
            {
                strFromDt = "";
                //strToDt = strToDt;

                if (objUtility.fnFireQueryTradeWeb("dematact", "count(*)", "da_clientcd", userId + "' and  da_status = 'A", true) == "0")
                {
                    return "Active Demat a/c not found in Client Master.";
                }
            }
            if (objUtility.fnFireQueryTradeWeb("Requests", "count(*)", "Rq_Clientcd", userId + "' and Rq_Type='" + cmbRequest + "' and Rq_DateFrom='" + strFromDt + "' and Rq_DateTo='" + strToDt + "' and Rq_Satus1= 'P", true) != "0")
            {
                return "Request Already Exists...";
            }
            string gstrToday = DateTime.Today.ToString("yyyyMMdd");
            string strHostAdd = Dns.GetHostName();
            bool blnIdentityOn = false;
            DataSet Dstemp = new DataSet();
            Dstemp = objUtility.OpenDataSet("SELECT isnull (IDENT_CURRENT('Requests'),0)");
            long intcnt = 0;
            if (Convert.ToInt64(Dstemp.Tables[0].Rows[0][0]) > 0)
            {
                blnIdentityOn = true;
                DataSet DsReqId = new DataSet();
                DsReqId = objUtility.OpenDataSet("SELECT IDENT_CURRENT('Requests')");
                intcnt = Convert.ToInt64(DsReqId.Tables[0].Rows[0][0]);
            }
            else
            {
                blnIdentityOn = false;
                DataSet Dsmax = new DataSet();
                Dsmax = objUtility.OpenDataSet("SELECT isNull(Max(Rq_srNo),0) from Requests");
                intcnt = Convert.ToInt64(Dsmax.Tables[0].Rows[0][0]) + 1;
            }

            if (blnIdentityOn)
                strsql = "insert into Requests values ( ";
            else
                strsql = "insert into Requests values ( " + intcnt + ",";

            strsql += " '" + userId + "','" + cmbRequest + "','" + strFromDt + "','" + strToDt + "','" + strHostAdd + "',";
            strsql += " '" + gstrToday + "',";
            strsql += " convert(char(8),getdate(),108),";
            strsql += " 'P','P','P','" + objUtility.Encrypt((gstrToday).ToString().Trim()) + "','',";
            strsql += " '" + strLstSeg + "')";
            objUtility.ExecuteSQL(strsql);

            return "Your request has been registered with reference ID: " + intcnt.ToString();
        }


