        public dynamic GetStatusMainGridData(string cm_cd, string strCompanyCode)
        {
            List<MargingFinanceStatusCombineModel> MargingFinanceStatusCombineList = new List<MargingFinanceStatusCombineModel>();

            foreach (char StatusCombined in strCompanyCode)
            {
                MargingFinanceStatusCombineModel result = new MargingFinanceStatusCombineModel();

                result.Status = TempRMSSummaryData(cm_cd, strCompanyCode);

                result.Funded = StatusFundData(cm_cd, strCompanyCode);

                result.Collateral = StatusCollateralData(cm_cd, strCompanyCode);

