        public dynamic TempRMSSummaryData(string cm_cd, string strCompanyCode)
        {
            try
            {
                SqlConnection con;
                using (var db = new DataContext())
                {
                    con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                    con.Open();

                    CreateTempTable(cm_cd, con, strCompanyCode);

                    strsql = "select  " + UtilityCommon.strTempRMSSummary + ".*,cm_name from " + UtilityCommon.strTempRMSSummary + ", Client_master WHERE cm_cd= TMP_CLIENTCD and TMP_CLIENTCD='" + cm_cd + "'";
                    strsql += " order by  cm_name";

                    var ds = objUtility.OpenDataSetTmp(strsql, con);
                    //if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                    //{
                    //    return ds.Tables[0];
                    //}
                    //return null;

                    //List<MargingFinanceStatusCombineModel> StatusResponse = new List<MargingFinanceStatusCombineModel>();
                    MTFRMSReport MTFRMSDetail;
                    MargingFinanceStatusCombineModel MTFRMS;
                    int i;

                    MTFRMS = new MargingFinanceStatusCombineModel();
                    MTFRMS.Status = new List<MTFRMSReport>();
                    var uccCode = cm_cd;
                    string uccName = objUtility.fnFireQueryTradeWeb("client_master", "cm_name", "cm_cd", uccCode, true);
                    if (!string.IsNullOrEmpty(uccName))
                    {
                        for (i = 0; i < ds.Tables[0].Rows.Count; i++)
                        {
                            MTFRMSDetail = new MTFRMSReport();
                            MTFRMSDetail.Client = ds.Tables[0].Rows[i]["Tmp_Clientcd"].ToString();
                            MTFRMSDetail.ClientName = ds.Tables[0].Rows[i]["cm_name"].ToString();
                            MTFRMSDetail.Limit = ds.Tables[0].Rows[i]["Tmp_Limit"].ToString();
                            MTFRMSDetail.TradingBalance = ds.Tables[0].Rows[i]["Tmp_TplusBal"].ToString();
                            MTFRMSDetail.LoanBalance = ds.Tables[0].Rows[i]["Tmp_LoanBal"].ToString();
                            MTFRMSDetail.FundedAmount = ds.Tables[0].Rows[i]["Tmp_FundedAmount"].ToString();
                            MTFRMSDetail.InitialMarginReq = ds.Tables[0].Rows[i]["Tmp_FundedMrgReq"].ToString();
                            MTFRMSDetail.CollateralFund = ds.Tables[0].Rows[i]["Tmp_CollateralFund"].ToString();
                            MTFRMSDetail.CollateralStock = ds.Tables[0].Rows[i]["Tmp_CollateralValue"].ToString();
                            MTFRMSDetail.ShortFallExcess = ds.Tables[0].Rows[i]["Tmp_ShortFallExcess"].ToString();
                            MTFRMSDetail.TradeValue = ds.Tables[0].Rows[i]["Tmp_TradeValue"].ToString();
                            MTFRMSDetail.M2MLoss = ds.Tables[0].Rows[i]["Tmp_M2MLoss"].ToString();

                            MTFRMS.Status.Add(MTFRMSDetail);
                        }
                    }
                    //StatusResponse.Add(MTFRMS);

                    return MTFRMS.Status;
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
