                {
                    strsql = " select ltrim(rtrim(convert(char,convert(datetime,MTtd_dt),112))) as TradeDate,rtrim(ss_name) as ScripName,MTtd_scripcd ScripCode ,MTtd_Stlmnt Settlement, sum(MTtd_bqty) PurchaseQty, convert(decimal(15,2), case  ";
                    strsql = strsql + "when sum(MTtd_bqty) >0 then  sum(MTtd_bqty*MTtd_rate)/sum(MTtd_bqty) else 0 end )PurchaseRate,  convert(decimal(15,2),";
                    strsql = strsql + "sum(MTtd_bqty*MTtd_rate)) PurchaseAmount, sum(MTtd_sqty) SellQty,convert(decimal(15,2),case when sum";
                    strsql = strsql + " (MTtd_sqty) > 0 then sum(MTtd_sqty*MTtd_rate)/sum(MTtd_sqty) else  0 end)  SellRate,convert(decimal(15,2),sum(MTtd_sqty*MTtd_rate))  SellAmount,sum(MTtd_bqty-MTtd_sqty) NetQty, convert(decimal(15,2),sum((MTtd_bqty-MTtd_sqty)*MTtd_rate)) NetAmount ";
                    strsql = strsql + " from MrgTdgFin_TRX with (" + StrMTFTRXIndex + "nolock),securities with(nolock) where MTtd_clientcd='" + cm_cd + "'";
                    strsql = strsql + " and MTtd_dt between '" + FromDate + "' and '" + ToDate + "' and MTtd_scripcd = ss_cd ";
                    strsql = strsql + "group by ss_name,MTtd_scripcd, ";  //order by td_dt, td_stlmnt
                    strsql = strsql + "MTtd_Stlmnt,MTtd_dt order by ss_name,MTtd_scripcd,MTtd_Stlmnt ";
                }
                else
                {
                    strsql = " select ltrim(rtrim(convert(char,convert(datetime,MTtd_dt),112))) as TradeDate,rtrim(ss_name) as ScripName,MTtd_scripcd ScripCode ,MTtd_Stlmnt Settlement, sum(MTtd_bqty) PurchaseQty, convert(decimal(15,2), case  ";
                    strsql = strsql + "when sum(MTtd_bqty) >0 then  sum(MTtd_bqty*MTtd_rate)/sum(MTtd_bqty) else 0 end )PurchaseRate,  convert(decimal(15,2),";
                    strsql = strsql + "sum(MTtd_bqty*MTtd_rate)) PurchaseAmount, sum(MTtd_sqty) SellQty,convert(decimal(15,2),case when sum";
                    strsql = strsql + " (MTtd_sqty) > 0 then sum(MTtd_sqty*MTtd_rate)/sum(MTtd_sqty) else  0 end)  SellRate,convert(decimal(15,2),sum(MTtd_sqty*MTtd_rate))  SellAmount,sum(MTtd_bqty-MTtd_sqty) NetQty, convert(decimal(15,2),sum((MTtd_bqty-MTtd_sqty)*MTtd_rate)) NetAmount ";
                    strsql = strsql + " from MrgTdgFin_TRX with (" + StrMTFTRXIndex + "nolock),securities with(nolock) where MTtd_clientcd='" + cm_cd + "'";
                    strsql = strsql + " and MTtd_scripcd='" + ScripCode + "' and MTtd_dt between '" + FromDate + "' and '" + ToDate + "' and MTtd_scripcd = ss_cd ";
                    strsql = strsql + "group by ss_name,MTtd_scripcd, ";  //order by td_dt, td_stlmnt
                    strsql = strsql + "MTtd_Stlmnt,MTtd_dt order by ss_name,MTtd_scripcd,MTtd_Stlmnt ";
                }
            }
            ds = objUtility.OpenDataSet(strsql);
            return ds;
        }
        public DataSet BindGrid(string cm_cd, string SelectedIndex, string FromDate, string ToDate)
        {
            DataSet ds = new DataSet();
            if (SelectedIndex == "0")
            {
                ds = ShowMasterGridItemWise(cm_cd, FromDate, ToDate);
            }
            else
            {
                ds = ShowMasterGridDateWise(cm_cd, FromDate, ToDate);
            }
            return ds;
        }
