        //Get margin trading finance shortfall main grid data
        public dynamic GetQueryShortFallMainGridData(string cm_cd, int IntNtxtDays, string frDate)
        {
            DataSet dsMainDataSet = new DataSet();
            DataSet DsDrClient = new DataSet();
            DataSet dsDetails = new DataSet();
            string strdate = frDate;// DateTime.Today.ToString("dd/MM/yyyy").Replace("-", "/");
            string strSql = "";
            int i;
            SqlConnection con;
            using (var db = new DataContext())
            {
                con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                con.Open();
                DataSet dsDates = new DataSet();
                Temptable(con);

                for (i = 0; i < IntNtxtDays; i++)
                {
                    AgainT2:
                    strSql = "select * from Tholiday_master where  ";

                    if (objUtility.GetSysParmSt("MTFP_LICBSE", "") == "Y")
                        strSql += "  hm_exchange in ('B')";
                    else if (objUtility.GetSysParmSt("MTFP_LICNSE", "") == "Y")
                        strSql += "  hm_exchange in ('N')";
                    else if (objUtility.GetSysParmSt("MTFP_LICBSE", "") == "Y" && objUtility.GetSysParmSt("MTFP_LICNSE", "") == "Y")
                        strSql += " hm_exchange in ('B','N')";

                    strSql += " and hm_Segment = 'C' and hm_dt = '" + strdate + "'";
                    dsDates = objUtility.OpenDataSet(strSql);

                    if (dsDates.Tables[0].Rows.Count > 0)
                    {
                        strdate = ConvertDT(objUtility.dtos(strdate)).AddDays(-1).ToString("yyyyMMdd");
                        goto AgainT2;
                    }
                    else
                    {
                        objUtility.prProcess(strdate, "", " and cm_cd = '" + cm_cd + "'", false, false, false, con);
                        strSql = " insert into #TmpDebitClient ";
                        strSql += "select Tmp_Clientcd,'" + strdate + "',Tmp_Limit,Tmp_TplusBal,Tmp_LoanBal,Tmp_FundedAmount,Tmp_FundedMrgReq,Tmp_CollateralFund,Tmp_CollateralValue,Tmp_ShortFallExcess,Tmp_TradeValue,Tmp_M2MLoss";
                        strSql += " From " + UtilityCommon.strTempRMSSummary + ", Client_master WHERE cm_cd= TMP_CLIENTCD order by cm_name";
                        objUtility.ExecuteSQLTmp(strSql, con);
                        if (strdate == DateTime.Today.ToString("yyyyMMdd"))
                        {
                            strSql = " insert into #TmpDebitClntDetail ";
                            strSql += " select Tmp_Type,'" + strdate + "',Tmp_Exchange,Tmp_Clientcd,Tmp_Scripcd,Tmp_RegForFO,Tmp_Qty,Tmp_Rate,Tmp_MarketRate,Tmp_Value,Tmp_MrgHairCut,Tmp_NetValue";
