                            objUtility.ExecuteSQLTmp(strSql, con);
                        }
                    }
                    strdate = ConvertDT(strdate).AddDays(-1).ToString("yyyyMMdd");// ToString("dd/MM/yyyy").Replace("-", "/");

                    strSql = " delete from #TmpDebitClient where Td_Clientcd in ( Select Td_Clientcd from #TmpDebitClient where Td_ShortFallExcess >= 0  )  ";
                    objUtility.ExecuteSQLTmp(strSql, con);
                    strSql = " delete from #TmpDebitClntDetail where Tcd_Clientcd not in ( Select Distinct Td_Clientcd from #TmpDebitClient )  ";
                    objUtility.ExecuteSQLTmp(strSql, con);

                    strSql = "select #TmpDebitClient.*,cm_name,bm_email,cm_email,bm_branchcd,cm_panno,cm_pincode, cm_dob";
                    strSql += " from #TmpDebitClient, Client_master ,Branch_master";
                    strSql += " WHERE cm_cd= Td_Clientcd and cm_brboffcode = bm_branchcd and Td_dt = '" + strdate + "'";

                    DsDrClient = objUtility.OpenDataSetTmp(strSql, con);
                    //dsMainDataSet.Tables.Add(objUtility.OpenNewDataTableTmp(strSql, con));

                    strSql = "select (case when Tcd_Exchange='D' then 'BSE' when Tcd_Exchange='F' then'NSE' when Tcd_Exchange='M' then'MCX' else Tcd_Exchange +'SE' end) Exchange,Tcd_Scripcd ScripCode,ss_name ScripName, SUM(Tcd_Qty) Qty,  cast(SUM(Tcd_Value) as decimal(15,2))  ActualCost,";
                    strSql += "  cast(SUM(Tcd_Qty * Tcd_MarketRate)  as decimal(15,2)) ClosePrice, cast(((SUM(Tcd_Qty * Tcd_MarketRate))-(SUM(Tcd_Value))) as decimal(15,2)) MTM, cast(SUM(Tcd_NetValue) as decimal(15,2)) MarginReq,cast(Tcd_MrgHairCut as decimal(15,2)) MarginPerc ,Tcd_Clientcd Client";
                    strSql += " from #TmpDebitClntDetail,Client_master,securities";
                    strSql += " where cm_cd=Tcd_Clientcd and Tcd_Scripcd=ss_cd ";
                    strSql += " Group By Tcd_Exchange,Tcd_Clientcd,cm_name,Tcd_MrgHairCut,Tcd_Scripcd,ss_name ";
                    strSql += " Order By ss_name,Tcd_Clientcd";

                    dsDetails = objUtility.OpenDataSetTmp(strSql, con);
                    //dsMainDataSet.Tables.Add(objUtility.OpenNewDataTableTmp(strSql, con));
                }
            }
            ShortFall ShortFallDetail;
            MargingFinanceShortFallModel MTFRMS;

            MTFRMS = new MargingFinanceShortFallModel();
            MTFRMS.ShortFall = new List<ShortFall>();
            var uccCode = cm_cd;
            string uccName = objUtility.fnFireQueryTradeWeb("client_master", "cm_name", "cm_cd", uccCode, true);

            for (int j = 2; j < DsDrClient.Tables[0].Rows.Count; j++)
            {
                ShortFallDetail = new ShortFall();
                ShortFallDetail.Client = DsDrClient.Tables[0].Rows[j]["Td_Clientcd"].ToString();
                ShortFallDetail.ClientName = DsDrClient.Tables[0].Rows[j]["cm_name"].ToString();
                ShortFallDetail.Limit = DsDrClient.Tables[0].Rows[j]["Td_Limit"].ToString();
                ShortFallDetail.TradingBalance = DsDrClient.Tables[0].Rows[j]["Td_TplusBal"].ToString();
                ShortFallDetail.LoanBalance = DsDrClient.Tables[0].Rows[j]["Td_LoanBal"].ToString();
                ShortFallDetail.FundedAmount = DsDrClient.Tables[0].Rows[j]["Td_FundedAmount"].ToString();
                ShortFallDetail.Initial_MarginReq = DsDrClient.Tables[0].Rows[j]["Td_FundedMrgReq"].ToString();
                ShortFallDetail.Collateral_Fund = DsDrClient.Tables[0].Rows[j]["Td_CollateralFund"].ToString();
                ShortFallDetail.Collateral_Stock = DsDrClient.Tables[0].Rows[j]["Td_CollateralValue"].ToString();
                ShortFallDetail.ShortFallExcess = DsDrClient.Tables[0].Rows[j]["Td_ShortFallExcess"].ToString();
                ShortFallDetail.TradeValue = DsDrClient.Tables[0].Rows[j]["Td_TradeValue"].ToString();
                ShortFallDetail.M2MLoss = DsDrClient.Tables[0].Rows[j]["Td_M2MLoss"].ToString();
                ShortFallDetail.ContinuousShortfall = IntNtxtDays.ToString();

                MTFRMS.ShortFall.Add(ShortFallDetail);
            }
            return MTFRMS.ShortFall;
