        public dynamic ShortFallGrid(string cm_cd, int IntNtxtDays, string frDate)
        {
            DataSet dsMainDataSet = new DataSet();
            DataSet DsDrClient = new DataSet();
            DataSet dsDetails = new DataSet();
            string strdate = frDate;// DateTime.Today.ToString("dd/MM/yyyy").Replace("/", "-");
            string strSql = "";
            int i;
            SqlConnection con;
            using (var db = new DataContext())
            {
                con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                con.Open();
                DataSet dsDates = new DataSet();
                Temptable(con);

                for (i = 0; i < IntNtxtDays; i++)
                {
                    AgainT2:
                    strSql = "select * from Tholiday_master where  ";

                    if (objUtility.GetSysParmSt("MTFP_LICBSE", "") == "Y")
                        strSql += "  hm_exchange in ('B')";
                    else if (objUtility.GetSysParmSt("MTFP_LICNSE", "") == "Y")
                        strSql += "  hm_exchange in ('N')";
                    else if (objUtility.GetSysParmSt("MTFP_LICBSE", "") == "Y" && objUtility.GetSysParmSt("MTFP_LICNSE", "") == "Y")
                        strSql += " hm_exchange in ('B','N')";

                    strSql += " and hm_Segment = 'C' and hm_dt = '" + strdate + "'";
                    dsDates = objUtility.OpenDataSet(strSql);

                    if (dsDates.Tables[0].Rows.Count > 0)
                    {
                        strdate = ConvertDT(strdate).AddDays(-1).ToString("yyyyMMdd");
                        goto AgainT2;
                    }
                    else
                    {
                        objUtility.prProcess(strdate, "", " and cm_cd = '" + cm_cd + "'", false, false, false, con);
                        strSql = " insert into #TmpDebitClient ";
                        strSql += "select Tmp_Clientcd,'" + strdate + "',Tmp_Limit,Tmp_TplusBal,Tmp_LoanBal,Tmp_FundedAmount,Tmp_FundedMrgReq,Tmp_CollateralFund,Tmp_CollateralValue,Tmp_ShortFallExcess,Tmp_TradeValue,Tmp_M2MLoss";
                        strSql += " From " + UtilityCommon.strTempRMSSummary + ", Client_master WHERE cm_cd= TMP_CLIENTCD order by cm_name";
                        objUtility.ExecuteSQLTmp(strSql, con);
                        if (strdate == DateTime.Today.ToString("yyyyMMdd"))
                        {
                            strSql = " insert into #TmpDebitClntDetail ";
                            strSql += " select Tmp_Type,'" + strdate + "',Tmp_Exchange,Tmp_Clientcd,Tmp_Scripcd,Tmp_RegForFO,Tmp_Qty,Tmp_Rate,Tmp_MarketRate,Tmp_Value,Tmp_MrgHairCut,Tmp_NetValue";
                            strSql += " From " + UtilityCommon.strTempRMSDetail + ", Client_master WHERE cm_cd= Tmp_Clientcd and Tmp_Type = 'M' order by cm_name";
                            objUtility.ExecuteSQLTmp(strSql, con);
                        }
                    }
                    strdate = ConvertDT(strdate).AddDays(-1).ToString("yyyyMMdd");

                    strSql = " delete from #TmpDebitClient where Td_Clientcd in ( Select Td_Clientcd from #TmpDebitClient where Td_ShortFallExcess >= 0  )  ";
                    objUtility.ExecuteSQLTmp(strSql, con);
                    strSql = " delete from #TmpDebitClntDetail where Tcd_Clientcd not in ( Select Distinct Td_Clientcd from #TmpDebitClient )  ";
                    objUtility.ExecuteSQLTmp(strSql, con);

                    strSql = "select #TmpDebitClient.*,cm_name,bm_email,cm_email,bm_branchcd,cm_panno,cm_pincode, cm_dob";
                    strSql += " from #TmpDebitClient, Client_master ,Branch_master";
                    strSql += " WHERE cm_cd= Td_Clientcd and cm_brboffcode = bm_branchcd and Td_dt = '" + strdate + "'";

                    DsDrClient = objUtility.OpenDataSetTmp(strSql, con);
                    //dsMainDataSet.Tables.Add(objUtility.OpenNewDataTableTmp(strSql, con));

                    strSql = "select (case when Tcd_Exchange='D' then 'BSE' when Tcd_Exchange='F' then'NSE' when Tcd_Exchange='M' then'MCX' else Tcd_Exchange +'SE' end) Exchange,Tcd_Scripcd ScripCode,ss_name ScripName, SUM(Tcd_Qty) Qty,  cast(SUM(Tcd_Value) as decimal(15,2))  ActualCost,";
                    strSql += "  cast(SUM(Tcd_Qty * Tcd_MarketRate)  as decimal(15,2)) ClosePrice, cast(((SUM(Tcd_Qty * Tcd_MarketRate))-(SUM(Tcd_Value))) as decimal(15,2)) MTM, cast(SUM(Tcd_NetValue) as decimal(15,2)) MarginReq,cast(Tcd_MrgHairCut as decimal(15,2)) MarginPerc ,Tcd_Clientcd Client";
                    strSql += " from #TmpDebitClntDetail,Client_master,securities";
                    strSql += " where cm_cd=Tcd_Clientcd and Tcd_Scripcd=ss_cd ";
                    strSql += " Group By Tcd_Exchange,Tcd_Clientcd,cm_name,Tcd_MrgHairCut,Tcd_Scripcd,ss_name ";
                    strSql += " Order By ss_name,Tcd_Clientcd";

                    dsDetails = objUtility.OpenDataSetTmp(strSql, con);
                    //dsMainDataSet.Tables.Add(objUtility.OpenNewDataTableTmp(strSql, con));
                }
            }
            Funded ShortFallMainDetail;
            MargingFinanceShortFallModel ShortFallGrid;

            ShortFallGrid = new MargingFinanceShortFallModel();
            ShortFallGrid.Funded = new List<Funded>();

            for (int j = 0; j < dsDetails.Tables[0].Rows.Count; j++)
            {
                ShortFallMainDetail = new Funded();
                ShortFallMainDetail.ScripCode = dsDetails.Tables[0].Rows[j]["ScripCode"].ToString();
                ShortFallMainDetail.ScripName = dsDetails.Tables[0].Rows[j]["ScripName"].ToString();
                ShortFallMainDetail.Qty = dsDetails.Tables[0].Rows[j]["Qty"].ToString();
                ShortFallMainDetail.ActualCost = dsDetails.Tables[0].Rows[j]["ActualCost"].ToString();
                ShortFallMainDetail.ClosePrice = dsDetails.Tables[0].Rows[j]["ClosePrice"].ToString();
                ShortFallMainDetail.MTM = dsDetails.Tables[0].Rows[j]["MTM"].ToString();
                ShortFallMainDetail.MarginPerc = dsDetails.Tables[0].Rows[j]["MarginPerc"].ToString();
                ShortFallMainDetail.MarginReq = dsDetails.Tables[0].Rows[j]["MarginReq"].ToString();
                ShortFallMainDetail.Exchange = dsDetails.Tables[0].Rows[j]["Exchange"].ToString();

                ShortFallGrid.Funded.Add(ShortFallMainDetail);
            }
            return ShortFallGrid.Funded;

        }

        //Method for convert date
        public DateTime ConvertDT(string Date)
        {
            int Year = int.Parse(Date.Substring(0, 4));
            int Month = int.Parse(Date.Substring(4, 2));
            int Day = int.Parse(Date.Substring(6, 2));
            return new DateTime(Year, Month, Day);
        }

        //Create temp table for ShortFall Webform
        protected void Temptable(SqlConnection con)
        {
            string strSql = "";
            try
            {
                strSql = " Drop Table #TmpDebitClient";
                objUtility.ExecuteSQLTmp(strSql, con);

                strSql = "Create Table #TmpDebitClient (";
                strSql += " Td_Clientcd VarChar(8),";
                strSql += " Td_dt VarChar(10),";
                strSql += " Td_Limit Money,";
                strSql += " Td_TplusBal Money,";
                strSql += " Td_LoanBal Money,";
                strSql += " Td_FundedAmount Money,";
                strSql += " Td_FundedMrgReq Money,";
                strSql += " Td_CollateralFund Money,";
                strSql += " Td_CollateralValue Money,";
                strSql += " Td_ShortFallExcess Money,";
                strSql += " Td_TradeValue Money,";
                strSql += " Td_M2MLoss Money)";
                objUtility.ExecuteSQLTmp(strSql, con);
            }
            catch (Exception ex)
            {
                strSql = "Create Table #TmpDebitClient (";
                strSql += " Td_Clientcd VarChar(8),";
                strSql += " Td_dt VarChar(10),";
                strSql += " Td_Limit Money,";
                strSql += " Td_TplusBal Money,";
                strSql += " Td_LoanBal Money,";
                strSql += " Td_FundedAmount Money,";
                strSql += " Td_FundedMrgReq Money,";
