                strSql = "Create Table #TmpDebitClntDetail (";
                strSql += " Tcd_Type Char(1),";
                strSql += " Tcd_dt VarChar(10),";
                strSql += " Tcd_Exchange Char(1),";
                strSql += " Tcd_Clientcd VarChar(8),";
                strSql += " Tcd_Scripcd VarChar(6),";
                strSql += " Tcd_RegForFO VarChar(1),";
