                strSql += " Tcd_MarketRate Money,";
                strSql += " Tcd_Value Money,";
                strSql += " Tcd_MrgHairCut Money,";
                strSql += " Tcd_NetValue Money)";
                objUtility.ExecuteSQLTmp(strSql, con);
            }
        }
