            strsql += StrAccC;
            strsql += " cast(sum(ld_amount) as decimal(15,2)) as  'Total' ";
            strsql += " from Ledger WITH (nolock) inner join Companyexchangesegments on LD_DPID = CES_Cd ";
            strsql += " Where ld_clientcd in (" + StrCDC + " )";
