        public FamilyCommonJson FamilyBalanceQueryJson(List<string> UCC_Codes)
        {
            string SelectedCLCode = "";
            string uccName = "";
            foreach (var uccCode in UCC_Codes)
            {
                uccName = objUtility.fnFireQueryTradeWeb("client_master", "cm_name", "cm_cd", objUtility.mfnReplaceForSQLInjection(uccCode), true);

                if (!String.IsNullOrEmpty(uccName))
                {
                    SelectedCLCode = SelectedCLCode + objUtility.mfnReplaceForSQLInjection(uccCode).Trim().ToUpper() + "~" + uccName.Trim() + "/";
                }
            }
            int CurrentYear = DateTime.Now.Year;
            if (DateTime.Today.Month < 3)
            {
                CurrentYear = CurrentYear - 1;
            }
            string Fromdt = objUtility.dtos(new DateTime(CurrentYear, 4, 1).ToString());
            string Todt = objUtility.dtos(new DateTime(CurrentYear + 1, 3, 31).ToString());
            string StrDataFields = "";
            string StrHeaderTitles = "";
            string StrSubTotalsFor = "";
            string StrTextAlign = "";
            string StrTextLength = "";
            string Strcolhide = "";
            string StrCDC = "";
            string StrAccC = "";
            string StrCDM = "";
            string StrAccM = "";
            string StrCDL = "";
            string StrAccL = "";
            char[] ArrSeparters = new char[1];
            ArrSeparters[0] = '/';
            string[] StrClCd;
            StrClCd = Convert.ToString(SelectedCLCode).Split(ArrSeparters);
            int i = 0;
            for (i = 0; i < StrClCd.Length - 1; i++)
            {
                string StrName = Strings.Left(StrClCd[i].Trim().Split('~')[1].Trim(), 15);

                StrAccC += " cast(sum(Case When ld_clientcd = '" + StrClCd[i].Trim().Split('~')[0].Trim() + "' then ld_amount else 0 end) as decimal(15,2)) as  '" + StrClCd[i].Trim().Split('~')[0].Trim() + "_bal',";
                StrCDC += "'" + StrClCd[i].Trim().Split('~')[0].Trim() + "',";
                StrAccL += " cast(sum(Case When ld_clientcd = '" + StrClCd[i].Trim().Split('~')[0].Trim() + objUtility.GetSysParmSt("MTFP_SUFFIX", "") + "' then ld_amount else 0 end) as decimal(15,2)) as  '" + StrClCd[i].Trim().Split('~')[0].Trim() + "_" + StrName.Trim() + "',";
                StrCDL += "'" + StrClCd[i].Trim().Split('~')[0].Trim() + objUtility.GetSysParmSt("MTFP_SUFFIX", "") + "',";

                string StrMrg = objUtility.fnFireQueryTradeWeb("client_master", "distinct cm_brkggroup", "cm_cd", StrClCd[i].Trim().Split('~')[0].Trim(), true).Trim();
                StrAccM += (StrMrg.Trim() == "" ? "0" : "cast(sum(Case When ld_clientcd = '" + StrMrg.Trim() + "' then ld_amount else 0 end) as decimal(15,2))") + " as  '" + StrClCd[i].Trim().Split('~')[0].Trim() + "_" + StrName.Trim() + "',";
                StrCDM += "'" + StrMrg.Trim() + "',";
                StrDataFields += StrClCd[i].Trim().Split('~')[0].Trim() + "_" + StrName.Trim() + ",";
                StrHeaderTitles += StrClCd[i].Trim().Split('~')[0].Trim() + "_" + StrName.Trim() + ",";
                StrSubTotalsFor += StrClCd[i].Trim().Split('~')[0].Trim() + "_" + StrName.Trim() + ",";
                StrTextAlign += "R,";
                StrTextLength += "15,";
                Strcolhide += i + 1 + ",";
            }
            Strcolhide += i + 1;
            StrCDC = Strings.Left(StrCDC, StrCDC.Length - 1);
            StrCDL = Strings.Left(StrCDL, StrCDL.Length - 1);
            StrCDM = Strings.Left(StrCDM, StrCDM.Length - 1);


            strsql = "select  'C' as account, ld_dpid As CESCD , ";
            strsql += " Rtrim(CES_Exchange) + '-' + CES_Segment as ExchSeg,";
            strsql += StrAccC;
            strsql += " cast(sum(ld_amount) as decimal(15,2)) as  'Total' ";
            strsql += " from Ledger WITH (nolock) inner join Companyexchangesegments on LD_DPID = CES_Cd ";
            strsql += " Where ld_clientcd in (" + StrCDC + " )";
            strsql += " Group By ld_dpid,CES_Exchange, CES_Segment";

            //strsql += " Union all select  'M' as account, ld_dpid As CESCD ,";
            //strsql += " Rtrim(CES_Exchange) + '-' + CES_Segment as ExchSeg,";
            //strsql += StrAccM;
            //strsql += " cast(sum(ld_amount) as decimal(15,2)) as  'Total' ";
            //strsql += " from Ledger WITH (nolock) inner join Companyexchangesegments on LD_DPID = CES_Cd";
            //strsql += " Where ld_clientcd in (" + StrCDM + " )";
            //strsql += " Group By ld_dpid ,CES_Exchange, CES_Segment";
            //MTF ledger
            if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects", "count(*)", "name", "MrgTdgFin_TRX", true)) > 0)
            {
                strsql += " union all select  'L' as account, ld_dpid As CESCD ,Rtrim(CES_Exchange) + '-' + CES_Segment as ExchSeg ,";
                strsql += StrAccL;
                strsql += " cast(sum(ld_amount) as decimal(15,2)) as  'Total' ";
                strsql += " from ledger with (nolock),MrgTdgFin_Clients , Companyexchangesegments ";
                strsql += " where ld_clientcd in (" + StrCDL + " ) and ld_dt <= '20210331' And  LD_DPID = CES_Cd ";
                strsql += "  and ld_clientcd =  Rtrim(MTFC_CMCD) + '" + objUtility.GetSysParmSt("MTFP_SUFFIX", "") + "' group by ld_dpid,CES_Exchange, CES_Segment";
            }
            // NBFC
            if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects", "count(*)", "name", "nbfc_clients", true)) > 0)
            {
                strsql += " union all ";
                strsql += "select 'N' as account, ld_dpid As CESCD , 'NBFC',";
                strsql += StrAccC;
                strsql += " cast(sum(ld_amount) as decimal(15,2)) as  'Total' ";
                strsql += " from NBFC_Ledger WITH (nolock)  where ld_clientcd in (" + StrCDC + " ) and ld_dt <= '" + Todt + "' group by ld_dpid ";
            }
            if (_configuration["Commex"] != null && _configuration["Commex"] != string.Empty)
            {
                string StrCommexConn = "";
                StrCommexConn = objUtility.GetCommexConnection();
                strsql += " union all select 'CM' as account, ld_dpid As CESCD , ";
                strsql += " Rtrim(CES_Exchange) + '-' + CES_Segment as ExchSeg ,";
                strsql += StrAccC;
                strsql += " cast(sum(ld_amount) as decimal(15,2)) as  'Total' ";
                strsql += " from   " + StrCommexConn + ".ledger  WITH (nolock) inner join Companyexchangesegments on LD_DPID = CES_Cd ";
                strsql += " where ld_clientcd in (" + StrCDC + " ) and ld_dt <= '" + Todt + "' ";
                strsql += " group by ld_dpid ,CES_Exchange, CES_Segment";

                strsql += " order by account";
            }
            DataSet ObjDataSet = new DataSet();
            ObjDataSet = objUtility.OpenDataSet(strsql);

            FamilyCommonJson familyRetained = new FamilyCommonJson();
            List<FamilyData> familyData = new List<FamilyData>();
            familyRetained.Header = familyData;
            familyRetained.Data = ObjDataSet.Tables[0];
            if (ObjDataSet.Tables[0].Rows.Count > 0)
            {
                foreach (var uccCode in UCC_Codes)
                {
                    uccName = objUtility.fnFireQueryTradeWeb("client_master", "cm_name", "cm_cd", uccCode, true);

                    familyData.Add(new FamilyData
                    {
                        Code = uccCode,
                        Name = uccCode + " " + uccName
                    });
                }
                if (UCC_Codes != null)
                {
                    familyData.Add(new FamilyData
                    {
                        Code = "Total",
                        Name = "Total"
                    });
                }
                //// Family Retain stock
                DataTable dt = new DataTable();
                dt = ObjDataSet.Tables[0];
                foreach (DataColumn d in dt.Columns)
                {
                    d.ColumnName = d.ColumnName.Replace("family_", "");
                }
                dt.AcceptChanges();
                familyRetained.Header = familyData;
                familyRetained.Data = dt;
                return familyRetained;
            }
            return null;
        }

        public FamilyCommonJson FamilyRetainedStokeJson(List<string> UCC_Codes)
