        public dynamic CollateralAllocation(string userId)
        {
            string strsql = string.Empty;
            CollateralAllocationModel caModel = new CollateralAllocationModel();

            strsql = "Select Max(cl_Date) AsOnDate From CollateralAtCM_Latest ";
            try
            {
                var asOn = objUtility.OpenStringVal(strsql);
                caModel.AsOnDate = asOn;
            }
            catch (Exception)
            {
            }

            strsql = "Select Case cl_Segment When 'C' Then 'Cash' When 'F' Then 'F&O' When 'K' Then 'FX' When 'XM' Then 'MCX Comm' When 'XF' Then 'NCDEX Comm' When 'XN' Then 'NSE Comm' When 'S' Then 'SLBM' When 'O' Then 'OFS' Else cl_Segment End as Segment ";
            strsql = strsql + " ,Sum(Case When cl_type='MRG' Then cl_Amount Else 0 End) as Margin ";
            strsql = strsql + " ,Sum(Case When cl_type IN ('LEDCC','LEC') Then cl_Amount Else 0 End) as Ledger ";
            strsql = strsql + " ,Sum(Case When cl_type IN ('SHCC','CHCC')  Then cl_Amount Else 0 End) as RePledge ";
            strsql = strsql + " From CollateralAtCM_Latest Where cl_ClientCode = '" + userId + "' Group By cl_Segment ";

            strsql = strsql + " Select Sum(Case When cl_type='LEDTM' Then cl_Amount Else 0 End) as Ledger ";
            strsql = strsql + " ,Sum(Case When cl_type IN ('SHTM','CHTM') Then cl_Amount Else 0 End) as Share ";
            strsql = strsql + " ,Sum(Case When cl_type IN ('EP')  Then cl_Amount Else 0 End) as EarlyPayIn  ";
            strsql = strsql + " From CollateralAtCM_Latest Where cl_ClientCode = '" + userId + "'   ";

            try
            {
                var ds = objUtility.OpenDataSet(strsql);
                if (ds?.Tables?.Count > 0 && ds?.Tables[0]?.Rows?.Count > 0)
                {
                    caModel.WithCC = ds.Tables[0];
                    caModel.WithTM = ds.Tables[1];
                    return caModel;
                }
                return caModel;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

