        public dynamic SendEmail(string emailId, string subjectLine, string msgBody)
        {
            try
            {
                Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
                Match match = regex.Match(emailId);
                if (match.Success)
                {
                    if (emailId.ToUpper().Contains("NOEMAIL") == true || emailId.ToUpper().Contains("NOTPROVIDED") == true || emailId.ToUpper().Contains("XYZ") == true || char.IsDigit(emailId.Split('@')[1][0]) == true)
                    {
                        throw new Exception("Invalid Email ID");
                    }

                }
                else
                {
                    throw new Exception("Invalid Email ID");
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
            return "Email has been sent successfully!!";
        }
        public GenerateOtpResponseModel GetOtpForChangeDetail(string userId, GenerateOtpModel model)
        {
            DataTable dt = objUtility.OpenDataTable($"select cm_mobile,cm_email from client_master where cm_cd='{userId}';");

            if (dt.Rows.Count > 0)
            {
                string ChangeMethod = string.Empty;
                string type = "MO", reqFor = "", strMobile = "", strEmail = "";
                if (model.IsChangeEmail)
                {
                    ChangeMethod += (string.IsNullOrEmpty(ChangeMethod)) ? "EMAIL" : "|EMAIL";
                    type = "EI";
                    reqFor = dt.Rows[0]["cm_email"].ToString().Trim();
                    strEmail = dt.Rows[0]["cm_email"].ToString().Trim();
                }
                if (model.IsChangeIncome)
                {
                    ChangeMethod += (string.IsNullOrEmpty(ChangeMethod)) ? "INCOME" : "|INCOME";
                    type = "GI";
                    reqFor = dt.Rows[0]["cm_mobile"].ToString().Trim();
                    strMobile = dt.Rows[0]["cm_mobile"].ToString().Trim();
                    strEmail = dt.Rows[0]["cm_email"].ToString().Trim();
                }
                if (model.IsChangeMobile)
                {
                    ChangeMethod += (string.IsNullOrEmpty(ChangeMethod)) ? "MOBILE" : "|MOBILE";
                    type = "MO";
                    reqFor = dt.Rows[0]["cm_mobile"].ToString().Trim();
                    strMobile = dt.Rows[0]["cm_mobile"].ToString().Trim();
                }

                if (!string.IsNullOrEmpty(strMobile) || !string.IsNullOrEmpty(strEmail))
                {
                    string chars1 = "1234567890";
                    char[] stringChars1 = new char[4];

                    Random random1 = new Random();
                    for (int i = 0; i < stringChars1.Length; i++)
                    {
                        stringChars1[i] = chars1[random1.Next(chars1.Length)];
                    }
                    string strOTP = new String(stringChars1);
                    //// ****** Call Generate OTP method for send OTP on Mobile and Email.
                    string responseGenOtp = GenerateOtp(userId, strMobile, strEmail, strOTP);
                    // var motp = _httpContextAccessor.HttpContext.Session.GetString("MOTP");
                    // _configuration["MOTP_" + userId] = strSotp;

                    if (!responseGenOtp.Contains("successfully"))
                    {
                        return new GenerateOtpResponseModel() { ChangeMethod = ChangeMethod, Message = responseGenOtp, Otp = "error" };
                    }

                    int intOTPValidTime = 5;
                    objUtility.CreateOTPMasterTable();

                    strsql = "Update OTP_Master set OTP_Status = 'E' where OTP_ClientCode='" + userId.ToUpper() + "' and OTP_Product = 'TradeWeb' and OTP_Type = 'RKC' and OTP_Status = 'P' and OTP_SentTo = '" + reqFor + "' ";
                    objUtility.ExecuteSQL(strsql);
                    strsql = "Insert into OTP_Master values('" + userId.ToUpper() + "', '" + type + "', '" + strOTP.Trim() + "','" + reqFor + "', CONVERT(CHAR(8),GETDATE(),112), CONVERT(VARCHAR(8), GETDATE(), 108), CONVERT(CHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 112),CONVERT(VARCHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 108),'P','TradeWeb', 'RKC','','','',0,0,0)";
                    objUtility.ExecuteSQL(strsql);

                    string strMessage = string.Empty;
                    if (!string.IsNullOrEmpty(strEmail) && !string.IsNullOrEmpty(strMobile))
                    {
                        strMessage = "OTP sent to Mobile & Email";
                    }
                    else if (!string.IsNullOrEmpty(strMobile))
                    {
                        strMessage = "OTP sent to Mobile";
                    }
                    else if (!string.IsNullOrEmpty(strEmail))
                    {
                        strMessage = "OTP sent to Email";
                    }
                    // strMessage = strMessage + ": " + motp;
                    return new GenerateOtpResponseModel() { ChangeMethod = ChangeMethod, Message = strMessage, Otp = "success" };
                }
            }
            return new GenerateOtpResponseModel() { Message = "Mobile number & Email not found", Otp = "not found" };
        }

        public GenerateOtpResponseModel GetGenerateOtpNew(string userId, GenerateOtpNew model)
        {
            string ChangeMethod = string.Empty;
            string type = "MO", responseGenOtp = "", strMessage = "OTP for new mobile verification has been sent.";

            try
            {
                string chars1 = "1234567890";
                char[] stringChars1 = new char[4];
                Random random1 = new Random();
                for (int i = 0; i < stringChars1.Length; i++)
                {
                    stringChars1[i] = chars1[random1.Next(chars1.Length)];
                }
                string strOTP = new String(stringChars1);

                //// ****** Call Generate OTP method for send OTP on Mobile and Email.
                if (model.reqType.ToLower() == "email")
                {
                    type = "EI";
                    strMessage = "OTP for new email verification has been sent.";
                    responseGenOtp = GenerateOtp(userId, "", model.reqValue, strOTP);
                }
                else
                {
                    responseGenOtp = GenerateOtp(userId, model.reqValue, "", strOTP);
                }

                if (!responseGenOtp.Contains("successfully"))
                {
                    return new GenerateOtpResponseModel() { ChangeMethod = ChangeMethod, Message = responseGenOtp, Otp = "error" };
                }
                int intOTPValidTime = 5;
                objUtility.CreateOTPMasterTable();

                strsql = "Update OTP_Master set OTP_Status = 'E' where OTP_ClientCode='" + userId.ToUpper() + "' and OTP_Product = 'TradeWeb' and OTP_Type = 'RKC' and OTP_Status = 'P' and OTP_SentTo = '" + model.reqValue + "' ";
                objUtility.ExecuteSQL(strsql);
                strsql = "Insert into OTP_Master values('" + userId.ToUpper() + "', '" + type + "', '" + strOTP.Trim() + "','" + model.reqValue + "', CONVERT(CHAR(8),GETDATE(),112), CONVERT(VARCHAR(8), GETDATE(), 108), CONVERT(CHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 112),CONVERT(VARCHAR(8), DATEADD(MINUTE, " + intOTPValidTime + ", GETDATE()), 108),'P','TradeWeb', 'RKC','','','',0,0,0)";
                objUtility.ExecuteSQL(strsql);

                return new GenerateOtpResponseModel() { ChangeMethod = "", Message = strMessage, Otp = "success" };

            }
            catch (Exception ex)
            {
                return new GenerateOtpResponseModel() { ChangeMethod = "", Message = "Error while sending otp: " + ex.Message.ToString(), Otp = "error" };
            }
        }


        public string GenerateOtp(string userId, string strMobile, string EmailId, string strOTP)
        {
            string Strsql = string.Empty;
            string strMsgTxt = string.Empty, finalResponse = "";
            bool smsLogs = false;

            if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Sysparameter", "count(0)", "sp_parmcd", "SMSCLMMO", true)) > 0)
            {
                strMsgTxt = objUtility.fnFireQueryTradeWeb("sysparameter", "SP_SYSVALUE", "sp_parmcd", "SMSCLMMO", true);
            }
            else
            {
                strMsgTxt = "Your OTP to initiate Mobile/Email/Gross Income change request for <Client> is <OTP>";
            }
            strMsgTxt = strMsgTxt.Replace("<OTP>", strOTP);
            strMsgTxt = strMsgTxt.Replace("<Client>", userId.ToUpper());

            if (!string.IsNullOrEmpty(strMobile))
            {
                try
                {
                    finalResponse = objUtility.SendSmsCommon(userId, strMsgTxt, strMobile);
                    if (finalResponse.ToLower().Contains("success"))
                    {
                        finalResponse = "OTP sent successfully! on mobile";
                        smsLogs = true;
                    }
                }
                catch (Exception ex)
                {
                    return "Error while sending otp on Mobile: " + ex.Message.ToString();
                }
            }
            if (!string.IsNullOrEmpty(EmailId))
            {
                if (!string.IsNullOrEmpty(objUtility.GetWebParameter("SMTPSERVER").Trim()))
                {
                    try
                    {
                        string strHost = string.Empty;
                        int intPort;
                        string strUserID = string.Empty;
                        string strPWD = string.Empty;
                        string strEmail = string.Empty;
                        string strSSL = string.Empty;
                        string strSMTPParamVal = objUtility.GetWebParameter("SMTPSERVER");
                        string strEmailID = EmailId;

                        strHost = strSMTPParamVal.Split('/')[0];
                        intPort = Convert.ToInt32(strSMTPParamVal.Split('/')[1]);
                        strUserID = strSMTPParamVal.Split('/')[2];
                        strPWD = strSMTPParamVal.Split('/')[3];
                        strEmail = strSMTPParamVal.Split('/')[4];
                        strSSL = strSMTPParamVal.Split('/')[5];

                        MailMessage Msg = new MailMessage();

                        Msg.From = new MailAddress(strEmail);
                        Msg.To.Add(strEmailID);
                        Msg.Subject = "Change Request OTP ";
                        Msg.Body = strMsgTxt;
                        Msg.IsBodyHtml = true;
                        SmtpClient smtp = new SmtpClient();
                        smtp.Host = strHost;
                        smtp.Port = intPort;
                        smtp.UseDefaultCredentials = false;
                        smtp.Credentials = new System.Net.NetworkCredential(strUserID, strPWD);
                        smtp.EnableSsl = strSSL == "N" ? false : true;
                        System.Net.ServicePointManager.ServerCertificateValidationCallback = delegate (object s,
                        System.Security.Cryptography.X509Certificates.X509Certificate certificate,
                        System.Security.Cryptography.X509Certificates.X509Chain chain,
                        System.Net.Security.SslPolicyErrors sslPolicyErrors)
                        {
                            return true;
                        };
                        smtp.Send(Msg);
                        if (smsLogs == false)
                        {
                            Strsql = "Insert into sms_Logs values(";
                            Strsql += "'" + userId.ToUpper() + "',Left('" + strEmailID + "',15),'" + strMsgTxt + "',";
                            Strsql += "'OTP sent successfully','" + userId.ToUpper() + "','" + DateTime.Now.ToString("yyyyMMdd") + "','" + DateTime.Now.ToString("HH:mm:ss") + "')";
                            objUtility.ExecuteSQL(Strsql);
                            finalResponse = "OTP sent successfully! on Email.";
                        }
                        else
                        {
                            finalResponse = finalResponse + " and OTP sent successfully! on Email.";
                        }
                    }
                    catch (Exception ex)
                    {
                        //finalResponse = "OTP sent successfully!";
                        return finalResponse + " Error while sending otp on Email: " + ex.Message.ToString();
                    }
                }
                else
                {
                    return finalResponse + " SMTP details not found.";
                }
            }
            //_httpContextAccessor.HttpContext.Session.SetString("MOTP", strSotp);

            return finalResponse;
        }

        public dynamic UpdateDetail(string userId, UpdateDetailModel model)
        {
            string strIDs = "", flag = "", newMobEml = "", oldMobEml = "";
            //var motp = _httpContextAccessor.HttpContext.Session.GetString("MOTP");
            //var newOtp = _configuration["MOTP_" + userId];

            string newIncomeDoc = model.NewIncomeImage;
            returnResponseBlank returnResp = new returnResponseBlank();
            DataTable dtM = objUtility.OpenDataTable($"select cm_mobile,cm_email from client_master where cm_cd='{userId}';");
            string strOldMobile = dtM.Rows[0]["cm_mobile"].ToString().Trim();
            string strOldEmail = dtM.Rows[0]["cm_email"].ToString().Trim();
