        public dynamic UpdateMobileNo(string userId, UpdateMobileNoModel model)
        {
            string strIDs = "";
            //var motp = _httpContextAccessor.HttpContext.Session.GetString("MOTP");
            //var newOtp = _configuration["MOTP_" + userId];
            returnResponseBlank returnResp = new returnResponseBlank();
            ////// Check otp
            string checkOTP = "", strIdentity = "", strMobileNo = "", OTP = model.Otp;
            int maxOtpFailCount = 0;

            #region Mobile validation
            long i;
            if (model.NewMobileNo.Trim().Length != 10)
            {
                return "Mobile number should be 10 digits ";
            }
            else if (!Int64.TryParse(model.NewMobileNo, out i))
            {
                return "Mobile number should be integer value ";
            }

            string oldMobile = objUtility.OpenDataTable($"select cm_mobile from client_master where cm_cd='{userId}'").Rows[0]["cm_mobile"].ToString();

            if (model.NewMobileNo == oldMobile)
            {
                return "New mobile number and old mobile number should not be same ";
            }
            if (model.NewMobileNo.StartsWith("1") || model.NewMobileNo.StartsWith("2") || model.NewMobileNo.StartsWith("3") || model.NewMobileNo.StartsWith("4") || model.NewMobileNo.StartsWith("5"))
            {
                return "Please enter valid mobile Number ";
            }
            Boolean blnRepeat = false;
            for (int j = 0; j < model.NewMobileNo.Length; j++)
            {
                if (model.NewMobileNo[j] != model.NewMobileNo[0])
                {
                    blnRepeat = false;
                    break;
                }
                else
                {
                    blnRepeat = true;
                }
            }
            if (blnRepeat == true)
            {
                return "Please enter valid mobile number";
            }
            #endregion

            string Strsql = "select top 1 OTP_Identity,OTP_OTP,OTP_ValidTillDate,OTP_ValidTillTime, OTP_SentTo, OTP_NFiller1  from OTP_Master with (NoLock) where OTP_ClientCode='" + userId + "' and OTP_Status='P' and OTP_Product='TradeWeb' and OTP_Type = 'RKC' and OTP_SentTo = '" + model.NewMobileNo + "' order by OTP_Identity desc";
            DataTable dtOtp = objUtility.OpenDataTable(Strsql);
            if (dtOtp.Rows.Count > 0)
            {
                checkOTP = dtOtp.Rows[0]["OTP_OTP"].ToString().Trim();
                strIdentity = dtOtp.Rows[0]["OTP_Identity"].ToString().Trim();
                strMobileNo = dtOtp.Rows[0]["OTP_SentTo"].ToString().Trim();
                maxOtpFailCount = Convert.ToInt32(dtOtp.Rows[0]["OTP_NFiller1"].ToString());
            }
            if (maxOtpFailCount >= 3)
            {
                return "Maximum OTP attempts reached. Please generate a new OTP.";
            }
            else if (!string.IsNullOrWhiteSpace(OTP) && !string.IsNullOrWhiteSpace(checkOTP) && OTP == checkOTP)
            {
                DateTime dtNow = objUtility.GetSqlCurrentDateTime();
                DateTime dt3 = objUtility.stod(dtOtp.Rows[0]["OTP_ValidTillDate"].ToString());
                TimeSpan time = TimeSpan.Parse(dtOtp.Rows[0]["OTP_ValidTillTime"].ToString());
                DateTime dtExpiry = dt3 + time;
                if (dtNow > dtExpiry)
                {
                    Strsql = "update OTP_Master set OTP_Status='E' where OTP_Identity='" + strIdentity + "'";
                    objUtility.ExecuteSQL(Strsql);
                    return "OTP has been expired";
                }
                Strsql = "update OTP_Master set OTP_Status='M' where OTP_Identity='" + strIdentity + "'";
                objUtility.ExecuteSQL(Strsql);
                // return "Password has been changed successfully!";
            }
            else
            {
                Strsql = "update OTP_Master set OTP_NFiller1=" + (maxOtpFailCount + 1) + " where OTP_Identity='" + strIdentity + "'";
                objUtility.ExecuteSQL(Strsql);
                return "OTP Mismatched";
            }

            try
            {
                if (!string.IsNullOrEmpty(model.NewMobileNo))
                {
                    string strRelation = "";
                    DataSet dtContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + oldMobile.Trim() + "' and cc_type='M'");

                    DataTable dt = new DataTable();
                    dt = objUtility.OpenDataTable($"select * from master_change_request where MCR_ClientCode='{userId}' and MCR_Status = 'O' and MCR_Item='MO' Order by MCR_ID desc");
                    if (dt.Rows.Count > 0)
                    {
                        objUtility.ExecuteSQL($"update Master_Change_Request set MCR_Status ='N' ,MCR_ReplyOTP='{OTP.Trim()}' , MCR_ReplyDate='{DateTime.Now.ToString("yyyyMMdd")}'  , MCR_ReplyTime='{DateTime.Now.ToString("HH:mm:ss")}' where MCR_ID='{Convert.ToString(dt.Rows[0]["MCR_ID"].ToString().Trim())}'");
                        strIDs = Convert.ToString(dt.Rows[0]["MCR_ID"].ToString().Trim());
                    }
                    else
                    {
                        //objUtility.ExecuteSQL($"delete from master_change_request where MCR_ClientCode='{userId}' and MCR_Status ='N' and MCR_Item='MO'");
                        objUtility.ExecuteSQL($"Insert into Master_Change_Request values( '{userId.ToUpper()}' , 'MO' , '{_httpContextAccessor.HttpContext.Connection.RemoteIpAddress}' ,  '{System.Environment.MachineName.ToString()}' , '{oldMobile}' , 'OTP Sent' , '{DateTime.Now.ToString("yyyyMMdd")}'  , '{DateTime.Now.ToString("HH:mm:ss")}' ,'{OTP.Trim()}', '{DateTime.Now.ToString("yyyyMMdd")}'  , '{DateTime.Now.ToString("HH:mm:ss")}' , '0' ,'{model.NewMobileNo}','" + strRelation.Trim() + "','','','','', '' , 'N','','' )");
                        DataSet dtSet = new DataSet();
                        dtSet = objUtility.OpenDataSet($"select * from master_change_request where MCR_ClientCode='{userId.ToUpper()}' and MCR_Status='N' and MCR_Item='MO'");
                        strIDs = dtSet.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                    }
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
            return "Your Change Request has been Registered. Ref No : " + strIDs;

        }

