                            objUtility.ExecuteSQL($"Insert into Master_Change_Request values( '{userId.ToUpper()}' , 'EI' , '{_httpContextAccessor.HttpContext.Connection.RemoteIpAddress}' ,  '{System.Environment.MachineName.ToString()}' , '{oldEmail}' , 'OTP Sent' , '{DateTime.Now.ToString("yyyyMMdd")}'  , '{DateTime.Now.ToString("HH:mm:ss")}' ,'{OTP.Trim()}', '{DateTime.Now.ToString("yyyyMMdd")}'  , '{DateTime.Now.ToString("HH:mm:ss")}' , '0' ,'{model.NewEmailId}','" + strRelation.Trim() + "','','','','', '' , 'N','','' )");
                            DataSet dtSet = new DataSet();
                            dtSet = objUtility.OpenDataSet($"select * from master_change_request where MCR_ClientCode='{userId.ToUpper()}' and MCR_Status='N' and MCR_Item='EI'");
                            strIDs = dtSet.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                        }
                    }
                }
                catch (Exception ex)
                {
                    throw ex;
                }
                return "Your Change Request has been Registered. Ref No : " + strIDs;

            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

