        public dynamic GetExchSeg()
        {
            string strCompanyCd = "", rekycSegment = "";
            if (Convert.ToInt32(objUtility.fnFireQuery("Entity_master", "count(0)", " em_cd='B' and em_name like 'SYKES & RAY EQUITIES%' and 1", "1", true)) > 0)
            {
                strsql = "select em_name OrgName,em_cd CompnyCd from Entity_Master with (nolock) where em_cd='B'";
            }
            else
            {
                strsql = "select em_name OrgName,em_cd CompnyCd from Entity_Master with (nolock) where em_cd =(select min(em_cd) from Entity_master Where len(em_cd) = 1)";
            }
            DataTable dtTemp = objUtility.OpenDataTable(strsql);
            if (dtTemp.Rows.Count != 0)
            {
                strCompanyCd = dtTemp.Rows[0]["CompnyCd"].ToString().Trim();
            }
            DataTable dtCom = new DataTable();
            rekycSegment = objUtility.GetWebParameter("RKYCSEGMENT");
            dtCom = objUtility.OpenDataTable("Select * From Other_Products where OP_Product='Commex' And OP_Status = 'A' ");
            strsql = "Select CES_Cd CESCd ,CES_Exchange exchange,CES_Segment segment,'T' Product, '" + rekycSegment + "' Enable from companyexchangesegments where CES_CompanyCd='" + strCompanyCd + "'";

            if (dtCom.Rows.Count > 0)
            {
                strsql += " union all ";
                strsql += "Select CES_Cd CESCd ,CES_Exchange exchange,CES_Segment segment,'X' Product , '" + rekycSegment + "' Enable From  " + (dtCom.Rows[0]["OP_DataBase"]).ToString().Trim() + ".dbo.CompanyExchangeSegments where CES_CompanyCd = '" + strCompanyCd + "'";
            }
            DataTable dt = objUtility.OpenDataTable(strsql);
            if (dt.Rows.Count > 0)
            {
                return dt;
            }
            return null;
        }

        public dynamic GetDPID()
        {
            strsql = "";
            string isTradWeb = objUtility.GetWebParameter("isTradeWeb");
            if (isTradWeb == "C")
            {
                if (objUtility.mfnGetSysSplFeatureDP("TBL"))
                {
                    strsql = " Select distinct LEFT(cm_cd,8) DPID from Client_master Where cm_Schedule = 49843750 and LEFT(cm_cd,3)  in ('120','130')";
                }
                else
                {
                    strsql = " Select distinct cm_companycode DPID from Client_master with (nolock) where isNull(cm_companycode,'') <> '' and Left(cm_companycode,3) in ('120','130') order by cm_companycode";
                }
            }
            else if (isTradWeb == "E")
            {
                strsql = " Select distinct cm_companycode DPID from Client_master with (nolock) where isNull(cm_companycode,'') <> '' and Left(cm_companycode,2) in ('IN') order by cm_companycode desc";
            }
            if (!string.IsNullOrEmpty(strsql))
            {
                DataTable dt = objUtility.OpenDataTable(strsql);
                if (dt.Rows.Count > 0)
                {
                    return dt;
                }
            }
            return null;
        }

        // Same company resolution + logo lookup as SP_InitializeLogin's CompanyCode/CompanyName/
        // CompanyLogo output (see SQL/Decrypted/TradeWeb_*.sql), extracted standalone so PDF
        // headers can fetch branding without invoking the full login procedure.
        public dynamic GetCompanyBranding()
        {
            string strsql = @"
DECLARE @DPID VARCHAR(500) = ''
DECLARE @CompanyName VARCHAR(50) = '', @strBase64 NVARCHAR(MAX) = ''

DECLARE @companyCount INT = 0
SELECT @companyCount = ISNULL(SUM(ISNULL(cnt,0)),0)
FROM ( SELECT COUNT(0) Cnt From Entity_master with (NoLock)
WHERE em_bse <> 'N' and isNull(em_bclearingno,'') in ('189')
UNION ALL
SELECT COUNT(0) Cnt From Entity_master with (NoLock)
WHERE em_nse <> 'N' and isNull(em_nclearingno,'') in ('07277') ) a

IF @companyCount = 0
BEGIN
    SELECT @DPID = em_cd, @CompanyName = em_name
    FROM Entity_Master with (nolock) where em_cd = (select min(em_cd) from Entity_master)
END
ELSE
BEGIN
    SELECT @DPID = em_cd, @CompanyName = em_name
    FROM Entity_Master with (nolock) where em_cd = 'B'
END

SELECT @strBase64 =
   (SELECT CAST(img_logo AS VARBINARY(MAX))
    FOR XML PATH(''), BINARY BASE64)
FROM Images(NOLOCK)
WHERE img_desc = 'Company Logo'

SELECT @DPID AS CompanyCode, @CompanyName AS CompanyName, CompanyLogo = @strBase64
";
            DataTable dt = objUtility.OpenDataTable(strsql);
            if (dt != null && dt.Rows.Count > 0)
            {
                return dt;
            }
            return null;
        }
