        public void createTable()
        {
            strsql = "CREATE TABLE IPO_Application(";
            strsql += " [IPA_ClientCd] [varchar](8) NOT NULL,";
            strsql += " [IPA_ScripID] [varchar](10) NOT NULL,";
            strsql += " [IPA_AppNo] [varchar](16) NOT NULL,";
            strsql += " [IPA_DpID] [varchar](8) NOT NULL,";
            strsql += " [IPA_BenID] [varchar](16) NOT NULL,";
            strsql += " [IPA_UPIID] [varchar](50) NOT NULL,";
            strsql += " [IPA_DpStatus] [char](1) NOT NULL,";
            strsql += " [IPA_DpRemark] [varchar](100) NOT NULL,";
            strsql += " [IPA_BnkPayStatus] [char](5) NOT NULL,";
            strsql += " [IPA_BnkActionDt] [char](8) NOT NULL,";
            strsql += " [IPA_BnkActionTime] [char](8) NOT NULL,";
            strsql += " [IPA_BnkBlockedAmt] [decimal](19, 2) NOT NULL,";
            strsql += " [IPA_BnkRejectReason] [varchar](500) NOT NULL,";
            strsql += " [IPA_Errorcode] [char](3) NOT NULL,";
            strsql += " [IPA_Message] [varchar](250) NOT NULL,";
            strsql += " [IPA_MkrDt] [char](8) NOT NULL,";
            strsql += " [IPA_MkrTime] [char](8) NOT NULL,";
            strsql += " [IPA_Filler1] [char](1) NOT NULL,";
            strsql += " [IPA_Filler2] [char](1) NOT NULL,";
            strsql += " [IPA_Filler3] [char](1) NOT NULL,";
            strsql += " [IPA_NFiller1] [numeric](18, 0) NOT NULL,";
            strsql += " [IPA_NFiller2] [numeric](18, 0) NOT NULL,";
            strsql += " [IPA_NFiller3] [numeric](18, 0) NOT NULL,";
            strsql += " CONSTRAINT [PK_IPO_Application] PRIMARY KEY CLUSTERED ([IPA_ClientCd],[IPA_ScripID],[IPA_AppNo]))";
            objUtility.ExecuteSQL(strsql);
        }
        public dynamic GetQueryIPOSubmit(string userId, IPOSubmitModel model)
        {
            string strCred = objUtility.fnFireQueryTradeWeb("sysparameter", "sp_sysvalue", "sp_parmcd", "BSEIPO", true);
            string strURL1 = objUtility.fnFireQueryTradeWeb("sysparameter", "sp_sysvalue", "sp_parmcd", "BSEIPOURL1", true);
            string strURL2 = objUtility.fnFireQueryTradeWeb("sysparameter", "sp_sysvalue", "sp_parmcd", "BSEIPOURL2", true);
            string[] arrCred = new string[5];
            string strMemberCode, strLoginID, strPassword, strIBBSID, strKey;
            string strChk1 = "", strChk2 = "", strChk3 = "";
            string strJson, strAppNo, strDepository;
            var strResponse = "";
            IBBSResponse ibbsRes = new IBBSResponse();
            //string strToken = string.Empty;
            //string strAppNo = string.Empty;
            //lblPay.Text = hdnPay.Value;

            if (strCred.Trim() != "")
            {
                arrCred = strCred.Split('/');
                strMemberCode = arrCred[0].ToString();
                strLoginID = arrCred[1].ToString();
                strPassword = arrCred[2].ToString();
                strIBBSID = arrCred[3].ToString();
                strKey = arrCred[4].ToString();
            }
            else
            {
                return "Invalid Credentials";
            }

            //if (chkAccept.Checked == false)
            //{
            //    return;
            //}

            if (model.UPIid == "")
            {
                return "UPI ID cannot be blank";
            }
            //if (model.UPIid.Trim().Contains("@"))
            //{
            //    return "Enter valid UPI ID";
            //}
            if (model.Price1.Trim().Length == 0 && model.Price2.Trim().Length == 0 && model.Price3.Trim().Length == 0)
            {
                if (model.Qty1.Trim().Length == 0 && model.Qty2.Trim().Length == 0 && model.Qty3.Trim().Length == 0)
                {
                    return "Enter Bid Details";
                }
            }
            if (model.Qty1.Trim() == "" || model.Price1.Trim() == "")
            {
                return "Quantity/Price cannot be blank";
            }
            else
            {
                if (Convert.ToInt32(model.Qty1.Trim()) % Convert.ToInt32(model.MinimumOrder.Trim()) != 0)
                {
                    return "Enter valid Quantity";
                }
            }
            if (model.Qty2.Trim() != "" && model.Price2.Trim() != "")
            {
                if (Convert.ToInt32(model.Qty2.Trim()) % Convert.ToInt32(model.MinimumOrder.Trim()) != 0 || Convert.ToInt32(model.Qty2.Trim()) == 0)
                {
                    return "Enter valid Quantity";
                }
            }
            if (model.Qty3.Trim() != "" && model.Price3.Trim() != "")
            {
                if (Convert.ToInt32(model.Qty3.Trim()) % Convert.ToInt32(model.MinimumOrder.Trim()) != 0 || Convert.ToInt32(model.Qty3.Trim()) == 0)
                {
                    return "Enter valid Quantity";
                }
            }

            strsql = "select * from client_master where cm_cd='" + userId + "'";
            DataSet dt1 = new DataSet();
            dt1 = objUtility.OpenDataSet(strsql);

            strsql = "select * from  Bankact,Bank_master ";
            strsql += " where  ba_clientcd='" + userId + "' and ba_default='y' and ba_micr=bk_micr ";
            if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("sysobjects a , syscolumns b", "count(0)", "a.id = b.id and b.name = 'ba_ifsccode' and a.name", "Bankact", true)) > 0)
            {
                strsql += " and ba_ifsccode = bk_IFCCode ";
            }
            DataSet dt2 = new DataSet();
            dt2 = objUtility.OpenDataSet(strsql);

            strsql = "select da_dpid ,da_actno,case left(da_dpid,2) when 'IN' then rtrim(da_dpid) else '0' end as BOID from Dematact ";
            strsql += "where  da_clientcd='" + userId + "' and da_defaultyn='y'";
            DataSet dt3 = new DataSet();
            dt3 = objUtility.OpenDataSet(strsql);

            if (dt3.Tables[0].Rows[0]["da_dpid"].ToString().Trim().Substring(0, 2) == "IN")
            {
                strDepository = "nsdl";
            }
            else
            {
                strDepository = "cdsl";
            }
            try
            {
                bool blnSME = objUtility.OpenDataSet("select case when IPO_Min_Price=IPO_Max_Price then '1' else '0' end as 'FP' from IPOs where IPO_NSE_Symbol='" + model.IPOName.Trim() + "' and IPO_Category='" + model.InvestorType.Trim() + "'").Tables[0].Rows[0][0].ToString() == "1";
                ibbsRes = IBBSLogin();
                if (ibbsRes.Status == "N")
                {
                    //return "API Error: LOGINID IS NOT CONFIGURED FOR API[Errorcode:006]";
                    return ibbsRes.Data;
                }

                strToken = ibbsRes.Data;

                List<BidDetails> listBidDetails = new List<BidDetails>();
                listBidDetails.Add(new BidDetails { quantity = "", rate = "", cuttoffflag = "" });
                if (!blnSME)
                {
                    listBidDetails.Add(new BidDetails { quantity = "", rate = "", cuttoffflag = "" });
                    listBidDetails.Add(new BidDetails { quantity = "", rate = "", cuttoffflag = "" });
                }
                IPOApplication application = new IPOApplication { };
                application.scripid = model.IPOName.Trim();
                application.clientname = "";
                application.panno = "";
                application.depository = "";
                application.dpid = "";
                application.clientbenfid = "";
                application.bankname = "";
                application.bankbranch = "";
                application.bankcode = "";
                application.location = "";
                application.ifsccode = "";
                application.accountnumber = "";
                application.filler1 = "";
                application.category = model.InvestorType.ToString().Trim();
                application.address = "";
                application.email = "";
                application.contact = "";
                application.bidtype = "2";
                application.filler2 = "";
                application.syndicatemembercode = "";
                application.brokercode = "";
                application.subbrokercode = "";
                application.referencefield = "";
                application.repartitiontype = "nr";
                application.orderno = "";
                application.bids = listBidDetails;

                strJson = JsonConvert.SerializeObject(application);

                ibbsRes = PostData(strURL1.Trim() + "eforms", strJson, strToken);
                if (ibbsRes.Status == "N")
                {
                    return ibbsRes.Data;
                }
                strResponse = ibbsRes.Data;
                if (JObject.Parse(strResponse)["errorcode"].ToString().Trim() == "0")
                {
                    strAppNo = JObject.Parse(strResponse)["applicationno"].ToString();
                }
                else
                {
                    return "API Error : " + JObject.Parse(strResponse)["message"].ToString() + " [Errorcode:" + JObject.Parse(strResponse)["errorcode"].ToString() + "]'";
                }

                List<OrderBidDetails> listBidDetails1 = new List<OrderBidDetails>();
                //strChk1 = model.Qty1 == true ? "1" : "0";
                //strChk2 = chkQty2.Checked == true ? "1" : "0";
                //strChk3 = chkQty3.Checked == true ? "1" : "0";

