                string[] formats = { "M/d/yyyy h:mm:ss tt", "dd-MM-yyyy HH:mm:ss" };
                DateTime dt = DateTime.ParseExact(ISR[0].sponsorbankactiontime.Trim(), formats, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None);
                strsql = "update IPO_Application set IPA_DpStatus='" + ISR[0].dpstatus.Trim() + "', IPA_DpRemark='" + ISR[0].dpremarks.Trim() + "', IPA_BnkPayStatus='" + ISR[0].sponsorbankpaystatus.Trim() + "', IPA_BnkActionDt='" + dt.ToString("yyyyMMdd").Trim() + "', IPA_BnkActionTime='" + dt.ToString("HH:mm:ss").Trim() + "'" + (ISR[0].sponsorbankamtblocked.Trim() == "" ? "" : " ,IPA_BnkBlockedAmt='" + ISR[0].sponsorbankamtblocked.Trim() + "' ") + ", IPA_BnkRejectReason='" + ISR[0].rejectreason.Trim() + "', IPA_Errorcode='" + ISR[0].errorcode.Trim() + "', IPA_Message='" + ISR[0].message.Trim() + "' where IPA_ClientCd='" + userId + "' and IPA_ScripID='" + IPOName + "' and IPA_AppNo='" + strAppNo + "'";
                objUtility.ExecuteSQL(strsql);
                return "Status Updated Successfully";
            }
            catch (Exception exx)
            {
                throw exx;
            }
        }
