        public string encrypt(string pInput, string strKey)
        {
            string result = "";
            Byte[] bytesToBeEncrypted = Encoding.UTF8.GetBytes(GenerateSHA256String(pInput));
            Byte[] passwordBytes = Encoding.UTF8.GetBytes(strKey);
            passwordBytes = SHA256.Create().ComputeHash(passwordBytes);
            Byte[] encryptedBytes = null;
            Byte[] saltBytes = new Byte[] { 1, 2, 3, 4, 5, 6, 7, 8 };
            using (MemoryStream ms = new MemoryStream())
            {
                using (RijndaelManaged AES = new RijndaelManaged())
                {
                    AES.KeySize = 256;
                    AES.BlockSize = 128;
                    Rfc2898DeriveBytes key = new Rfc2898DeriveBytes(passwordBytes, saltBytes, 1000);
                    AES.Key = key.GetBytes(AES.KeySize / 8);
                    AES.IV = key.GetBytes(AES.BlockSize / 8);
                    AES.Mode = CipherMode.CBC;
                    using (CryptoStream cs = new CryptoStream(ms, AES.CreateEncryptor(), CryptoStreamMode.Write))
                    {
                        cs.Write(bytesToBeEncrypted, 0, bytesToBeEncrypted.Length);
                        cs.Close();
                    }
                    encryptedBytes = ms.ToArray();
                    result = Convert.ToBase64String(encryptedBytes);
                }
            }
            return result;
        }
        public string GenerateSHA256String(string inputString)
        {
            SHA256 sha256 = SHA256Managed.Create();
            Byte[] bytes = Encoding.UTF8.GetBytes(inputString);
            Byte[] hash = sha256.ComputeHash(bytes);
            StringBuilder stringBuilder = new StringBuilder();
            for (int i = 0; i <= hash.Length - 1; i++)
            {
                stringBuilder.Append(hash[i].ToString("X2"));
            }
            return stringBuilder.ToString();
        }
        public IBBSResponse IBBSLogin()
        {
            string strCred = objUtility.fnFireQueryTradeWeb("sysparameter", "sp_sysvalue", "sp_parmcd", "BSEIPO", true);
            string strURL1 = objUtility.fnFireQueryTradeWeb("sysparameter", "sp_sysvalue", "sp_parmcd", "BSEIPOURL1", true);
            string strMemberCode, strLoginID, strPassword, strIBBSID, strKey;
            string strJson, strResponse;
            string[] arrCred = new string[5];
            HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(strURL1.Trim() + "login");
            httpWebRequest.ContentType = "application/json";
            httpWebRequest.Method = "POST";
            ServicePointManager.SecurityProtocol = (SecurityProtocolType)768 | (SecurityProtocolType)3072 | (SecurityProtocolType)12288 | (SecurityProtocolType)192;

            if (strCred.Trim() != "")
            {
                arrCred = strCred.Split('/');
                strMemberCode = arrCred[0].ToString();
                strLoginID = arrCred[1].ToString();
                strPassword = arrCred[2].ToString();
                strIBBSID = arrCred[3].ToString();
                strKey = arrCred[4].ToString();
            }
            else
            {
                return new IBBSResponse { Status = "N", Data = "Invalid Credentials" };
            }

            using (StreamWriter streamWriter = new StreamWriter(httpWebRequest.GetRequestStream()))
            {
                LoginRequest request = new LoginRequest();
                request.membercode = strMemberCode;
                request.loginid = strLoginID;
                request.password = strPassword;
                request.ibbsid = strIBBSID;
                strJson = JsonConvert.SerializeObject(request);
                streamWriter.Write(strJson);
            }
            HttpWebResponse httpWebResponse = (HttpWebResponse)httpWebRequest.GetResponse();
            using (StreamReader streamReader = new StreamReader(httpWebResponse.GetResponseStream()))
            {
                strResponse = streamReader.ReadToEnd();
            }

            if (JObject.Parse(strResponse)["errorcode"].ToString() == "0")
            {
                strToken = JObject.Parse(strResponse)["token"].ToString();
                return new IBBSResponse { Status = "Y", Data = strToken };
            }
            else
            {
                return new IBBSResponse { Status = "N", Data = "API Error : " + JObject.Parse(strResponse)["message"].ToString() + " [Errorcode:" + JObject.Parse(strResponse)["errorcode"].ToString() + "]" };
                //return "";
            }
        }
        public IBBSResponse PostData(string strUrl, string strJson, string strToken)
        {
            string strCred = objUtility.fnFireQueryTradeWeb("sysparameter", "sp_sysvalue", "sp_parmcd", "BSEIPO", true);
            string[] arrCred = new string[5];
            string strResponse;

            if (strCred.Trim() == "")
            {
                return new IBBSResponse { Status = "N", Data = "Invalid Credentials" };
            }

            arrCred = strCred.Split('/');
            string strMemberCode = arrCred[0].ToString();
            string strLoginID = arrCred[1].ToString();
            string strPassword = arrCred[2].ToString();
            string strIBBSID = arrCred[3].ToString();
            string strKey = arrCred[4].ToString();

            HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(strUrl.Trim());
            httpWebRequest.ContentType = "application/json";
            httpWebRequest.Method = "POST";
            httpWebRequest.Headers.Add("Checksum", encrypt(strJson, strKey));
            httpWebRequest.Headers.Add("Token", strToken);
            httpWebRequest.Headers.Add("Membercode", strMemberCode);
            httpWebRequest.Headers.Add("Login", strLoginID);
            ServicePointManager.SecurityProtocol = (SecurityProtocolType)768 | (SecurityProtocolType)3072 | (SecurityProtocolType)12288 | (SecurityProtocolType)192;

            using (StreamWriter streamWriter = new StreamWriter(httpWebRequest.GetRequestStream()))
            {
                streamWriter.Write(strJson);
            }

            HttpWebResponse httpWebResponse = (HttpWebResponse)httpWebRequest.GetResponse();
            using (StreamReader streamReader = new StreamReader(httpWebResponse.GetResponseStream()))
            {
                strResponse = streamReader.ReadToEnd();
            }
            return new IBBSResponse { Status = "Y", Data = strResponse };
        }
