        public dynamic Client_Closer(AccountCloserModel data, string userId)
        {
            try
            {
                string strSql = "";
                ////var aa = Dns.GetHostName();
                ////string bb = Dns.GetHostByName(aa).AddressList[0].ToString();
                if ((data.closureType.ToUpper() == "D" || data.closureType.ToUpper() == "B") && data.dematAccount == "")
                {
                    throw new Exception("Demat account number should not be blank");
                }
                if (data.closureType == "B" && data.dematAccount != "")
                {
                    strSql = $"Insert into Master_Change_Request values( '{data.clientCode}' , 'DC' , '{_httpContextAccessor.HttpContext.Connection.RemoteIpAddress}' ,  '{System.Environment.MachineName.ToString()}' , '{userId}' , 'Close Demat Account' , Left(Replace(CONVERT(nvarchar, getdate(),21),'-',''),8)  , substring(Replace(CONVERT(nvarchar, getdate(),21),'-',''),10,8) ,'', Left(Replace(CONVERT(nvarchar, getdate(),21),'-',''),8) , substring(Replace(CONVERT(nvarchar, getdate(),21),'-',''),10,8) , '0' ,'{data.dematAccount}','','','','','', '' , 'N' ,'','')";
                    objUtility.ExecuteSQL(strSql);

                    strSql = $"Insert into Master_Change_Request values( '{data.clientCode}' , 'TC' , '{_httpContextAccessor.HttpContext.Connection.RemoteIpAddress}' ,  '{System.Environment.MachineName.ToString()}' , '{userId}' , 'Close Trading Account' , Left(Replace(CONVERT(nvarchar, getdate(),21),'-',''),8)  , substring(Replace(CONVERT(nvarchar, getdate(),21),'-',''),10,8) ,'', Left(Replace(CONVERT(nvarchar, getdate(),21),'-',''),8) , substring(Replace(CONVERT(nvarchar, getdate(),21),'-',''),10,8) , '0' ,'','','','','','', '' , 'N' ,'','')";
                    objUtility.ExecuteSQL(strSql);
                }
                else
                {
                    strSql = $"Insert into Master_Change_Request values( '{data.clientCode}' , '{data.closureType.ToUpper()}C' , '{_httpContextAccessor.HttpContext.Connection.RemoteIpAddress}' ,  '{System.Environment.MachineName.ToString()}' , '{userId}' , Case when '{data.closureType}'='D' then 'Close Demat Account' else 'Close Trading Account' End , Left(Replace(CONVERT(nvarchar, getdate(),21),'-',''),8)  , substring(Replace(CONVERT(nvarchar, getdate(),21),'-',''),10,8) ,'', Left(Replace(CONVERT(nvarchar, getdate(),21),'-',''),8) , substring(Replace(CONVERT(nvarchar, getdate(),21),'-',''),10,8) , '0' ,'{data.dematAccount}','','','','','', '' , 'N' ,'','')";
                    objUtility.ExecuteSQL(strSql);
                }
                return "Account close successfully!!";
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
