                    {
                        string strERelation = "";
                        DataSet dtEContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + OldEmailId.Trim() + "' and cc_type='E'");
                        if (dtEContact.Tables[0].Rows.Count > 0)
                        {
                            strERelation = dtEContact.Tables[0].Rows[0]["cc_Relation"].ToString();
                        }
                        if (!string.IsNullOrEmpty(NewEmail))
                        {
                            if (NewEmail.Trim().Length > 0)
                            {
                                string strEmail = NewEmail.Trim();
                                Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
                                Match match = regex.Match(strEmail);
                                if (match.Success)
                                {
                                    if (strEmail.ToLower() == OldEmailId.ToLower())
                                    {
                                        throw new Exception("Please enter new Email, the old and new Email cannot be the same.");
                                    }
                                    if (strEmail.ToUpper().Contains("NOEMAIL") == true || strEmail.ToUpper().Contains("NOTPROVIDED") == true || strEmail.ToUpper().Contains("XYZ") == true || char.IsDigit(strEmail.Split('@')[1][0]) == true)
                                    {
