                                    strsql = "update Master_Change_Request set MCR_Status ='N' ,MCR_ReplyOTP='" + OTP.Trim() + "' , MCR_ReplyDate='" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , MCR_ReplyTime='" + DateTime.Now.ToString("HH:mm:ss") + "' where MCR_ID='" + Convert.ToString(SessionEMAILID) + "'";
                                    objUtility.ExecuteSQL(strsql);
                                    strIDs = Convert.ToString(SessionEMAILID);
                                    SessionEMAILID = "";
                                }
                                else
                                {
                                    strsql = "update Master_Change_Request set MCR_Status ='N' ,MCR_ReplyOTP='" + OTP.Trim() + "' , MCR_ReplyDate='" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , MCR_ReplyTime='" + DateTime.Now.ToString("HH:mm:ss") + "' where MCR_ClientCode='" + userId + "' and MCR_Item='EI' and MCR_OldValue='" + OldEmailId.Trim() + "' and MCR_Status ='O'";
                                    objUtility.ExecuteSQL(strsql);
                                }
                            }
                            else
                            {
                                strsql = "delete from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status ='N' and MCR_Item='EI'";
                                objUtility.ExecuteSQL(strsql);
                                strsql = "Insert into Master_Change_Request values( '" + userId.ToUpper() + "' , 'EI' , '" + ip + "' ,  '" + System.Environment.MachineName.ToString() + "' , '" + OldEmailId.Trim() + "' , 'OTP Sent' , '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "' , '' , '' , '' , '" + EmailSelectedIndex.ToString() + "' ,'" + NewEmail.Trim() + "','" + strERelation.Trim() + "','','','','','', 'N','','' )";
                                objUtility.ExecuteSQL(strsql);
                            }
                            strsql = "select MCR_ID from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='N' and MCR_Item='EI'";
