                        //    if (dtGross.Month > 3)
                        //    {
                        //        if (dtGross.AddYears(1).Year.ToString() != null)
                        //        {
                        //            //cmbAsOn.ClearSelection();
                        //            upload.AsOnDate = dtGross.AddYears(1).Year.ToString();
                        //        }
                        //    }
                        //    else
                        //    {
                        //        if (dtGross.Year.ToString() != null)
                        //        {
                        //            //cmbAsOn.ClearSelection();
                        //            upload.AsOnDate = dtGross.Year.ToString();
                        //        }
                        //    }
                        //}
                        #endregion
                        //string NewIncomeValue;
                        if (Convert.ToInt32(upload.grossIncome) <= 100000)
                        {
                            //NewIncomeValue = "Below Rs. 1  Lac";
                            GrossSelectedIndex = 0;
                        }
                        else if (Convert.ToInt32(upload.grossIncome) <= 500000)
                        {
                            //NewIncomeValue = "Btw Rs. 1 to Rs. 5 Lacs";
                            GrossSelectedIndex = 1;
                        }
                        else if (Convert.ToInt32(upload.grossIncome) <= 1000000)
                        {
                            //NewIncomeValue = "Btw Rs. 5 to Rs. 10 Lacs";
                            GrossSelectedIndex = 2;
                        }
                        else if (Convert.ToInt32(upload.grossIncome) <= 2500000)
                        {
                            //NewIncomeValue = "Btw Rs. 10 to Rs. 25 Lacs";
                            GrossSelectedIndex = 3;
                        }
                        else if (Convert.ToInt32(upload.grossIncome) <= 10000000)
                        {
                            //NewIncomeValue = "Btw Rs. 25 Lacs to Rs. 1 Crore";
                            GrossSelectedIndex = 4;
                        }
                        else
                        {
                            //NewIncomeValue = "More than Rs. 1 Crore";
                            GrossSelectedIndex = 5;
                        }
                        if (Convert.ToInt32(objUtility.fnFireQueryTradeWeb("Client_Details", "Count(0)", "substring(ce_companycode,3,1) in ('F','K','X' ) and ce_regDt<>'' and ce_clientcd", userId.ToString(), true)) > 0)
                        {
                            if (string.IsNullOrEmpty(upload.image))
                            {
                                throw new Exception("Gross Annual Income Proof is Compulsorily for Trading in Derivative Segment.");
                            }
                        }
                        strGincome = objUtility.fnFireQueryTradeWeb("client_info", "cm_grossincome", "cm2_cd", userId, true);
                        strGincomedt = objUtility.fnFireQueryTradeWeb("client_info", "cm_grossincomedt", "cm2_cd", userId, true);
                        int g;
                        Boolean blnNSDL = IsNSDLClient(userId);
                        if (Int32.TryParse(strGincome, out g))
                        {
                            if (Convert.ToInt32(strGincome) == GrossSelectedIndex + 1 && strGincomedt == upload.AsOnDate.ToString() + "0331" && blnNSDL == false)
                            {
                                throw new Exception("Please enter new Gross Annual Income, the old and new Gross Annual Income cannot be the same.");
                            }
                        }
                        if (!string.IsNullOrEmpty(upload.image))
                        {
                            string[] validFileTypes = { "tif", "pdf", "png", "bmp", "jpeg" };
                            var data = upload.image.Substring(0, 5);
                            switch (data.ToUpper())
                            {
                                case "IVBOR":
                                    ext = ".png";
                                    break;
                                case "/9J/4":
                                    ext = ".jpeg";
                                    break;
                                case "JVBER":
                                    ext = ".pdf";
                                    break;
                            }
                            bool isValidFile = false;
                            for (int i = 0; i < validFileTypes.Length; i++)
                            {
                                if (ext.Equals("." + validFileTypes[i], StringComparison.OrdinalIgnoreCase))
                                {
                                    isValidFile = true;
                                    break;
                                }
                            }
                            if (isValidFile == true)
                            {
                                filesize = bytes.Length;
                                if (filesize < 512000)
                                {
                                }
                                else
                                {
                                    throw new Exception("Gross Annual Income Proof to be in PDF / JPEG / PNG / BMP format only with size less than 500 kb");
                                }
                            }
                            else
                            {
                                throw new Exception("Gross Annual Income Proof to be in PDF / JPEG / PNG / BMP format only");
                            }
                        }

                        var ip = _httpContextAccessor.HttpContext.Connection.RemoteIpAddress.ToString();
                        string Strsql = string.Empty;
                        Strsql = "delete from master_change_request where MCR_ClientCode='" + userId + "' and MCR_Item='GI' and MCR_Status='N'";
                        objUtility.ExecuteSQL(Strsql);
                        Strsql = @"Insert into Master_Change_Request values( '" + userId.ToUpper() + "' , 'GI' , '" + ip + "' ,  '" + System.Environment.MachineName.ToString() + "' , '" + (OldIncomeValue.Trim() != "" ? (strGincome + "~" + strGincomedt) : "") + "' , 'OTP Sent' , '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "' , '' , '' , '' , '' ,'" + ext + "','','','','','',@Image, 'N','" + Convert.ToInt32(GrossSelectedIndex + 1) + "','" + upload.AsOnDate.ToString() + "0331" + "' )";
                        SqlConnection con;
                        using (var db = new DataContext())
                        {
                            con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                            con.Open();
                            using (SqlCommand MyCmd = new SqlCommand())
                            {
                                MyCmd.Connection = con;
                                MyCmd.CommandTimeout = 5000;
                                MyCmd.CommandText = Strsql;
                                MyCmd.Parameters.Add("@Image", SqlDbType.Image);
                                MyCmd.Parameters[0].Value = bytes;
                                MyCmd.ExecuteNonQuery();
                                MyCmd.Dispose();
                            }
                            Strsql = "select MCR_ID from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='N' and MCR_Item='GI'";
                            DataSet dtID = new DataSet();
                            dtID = objUtility.OpenDataSet(Strsql);
                            strIDs = dtID.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                        }
                    }
                    else
                    {
                        throw new Exception("New Details can not be blank");
                    }
                }
                else
                {
                    throw new Exception("OTP Mismatched, Please enter valid otp");
                }
            }
            else
            {
                throw new Exception("OTP Cannot be blank");
            }

            string strMessage = "Your Change Request has been Registered. Ref No : " + strIDs;
            return strMessage;

        }
        public dynamic Modification_Generate_Combined_OTP_Execute(string userId, string OTP, string Old_Mob_No, string Old_Email_Id, string Old_Gross_Income, string New_Mobile_Number, string Mobile_Owner_Type, string New_Email_Id, string Email_Owner_Type)
        {
            string SessionMOBILEID = "";
            int MobileSelectedIndex = 0;
            string New_MobileNo = "";
            string Mobile_Type = "";
            string SessionEMAILID = "";
            int EmailSelectedIndex = 0;
            string New_EmailId = "";
            string New_Email_Type = "";
            int GrossSelectedIndex = 0;
            string AsOnDate = "";

            if (!string.IsNullOrEmpty(OTP))
            {
                var responseSessionOtp = _httpContextAccessor.HttpContext.Session.GetObject<List<OtpUserIdSession>>("userOtp");
                var responseOtp = responseSessionOtp.Where(x => x.UserId == userId && x.OTP == OTP).FirstOrDefault();
                if (responseOtp != null)
                {
                    responseSessionOtp.Remove(responseOtp);
                    _httpContextAccessor.HttpContext.Session.SetObject("userOtp", responseSessionOtp);
                    if (MobileSelectedIndex == 0)
                    {
                        strsql = "select * from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status = 'O' and MCR_Item='MO'";
                        DataTable dt = new DataTable();
                        dt = objUtility.OpenDataTable(strsql);
                        if (dt.Rows.Count > 0)
                        {
                            New_MobileNo = dt.Rows[0]["MCR_New1"].ToString().Trim();
                            SessionMOBILEID = dt.Rows[0]["MCR_ID"].ToString().Trim();
                            MobileSelectedIndex = int.Parse(dt.Rows[0]["MCR_Owner"].ToString().Trim());
                            strsql = "update master_change_request set MCR_Status='O', MCR_Reason='OTP Sent' where MCR_ID='" + Convert.ToString(SessionMOBILEID) + "'";
                            objUtility.ExecuteSQL(strsql);
                        }
                        else
                        {
                            SessionMOBILEID = "";
                        }
                        DataSet dtContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + Old_Mob_No.Trim() + "' and cc_type='M'");
                        if (dtContact.Tables[0].Rows.Count > 0)
                        {
                            New_MobileNo = dtContact.Tables[0].Rows[0]["cc_contact"].ToString();
                            if (dtContact.Tables[0].Rows[0]["cc_relation"].ToString().Trim() != "")
                            {
                                Mobile_Type = dtContact.Tables[0].Rows[0]["cc_relation"].ToString().Trim();
                            }
                        }
                    }
                    if (EmailSelectedIndex == 0)
                    {
                        if (objUtility.GetWebParameter("SMTPSERVER").Trim() != "")
                        {
                            strsql = "select * from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status = 'O' and MCR_Item='EI'";
                            DataTable dt = new DataTable();
                            dt = objUtility.OpenDataTable(strsql);
                            if (dt.Rows.Count > 0)
                            {
                                New_EmailId = dt.Rows[0]["MCR_New1"].ToString().Trim();
                                SessionEMAILID = dt.Rows[0]["MCR_ID"].ToString().Trim();
                                EmailSelectedIndex = int.Parse(dt.Rows[0]["MCR_Owner"].ToString().Trim());
                                strsql = "update master_change_request set MCR_Status='O', MCR_Reason='OTP Sent' where MCR_ID='" + Convert.ToString(SessionEMAILID) + "'";
                                objUtility.ExecuteSQL(strsql);
                            }
                            else
                            {
                                SessionEMAILID = "";
                            }
                        }
                        DataSet dtContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + Old_Email_Id.Trim() + "' and cc_type='E'");
                        if (dtContact.Tables[0].Rows.Count > 0)
                        {
                            New_EmailId = dtContact.Tables[0].Rows[0]["cc_contact"].ToString();
                            if (dtContact.Tables[0].Rows[0]["cc_relation"].ToString().Trim() != "")
                            {
                                New_Email_Type = dtContact.Tables[0].Rows[0]["cc_relation"].ToString().Trim();
                            }
                        }
                    }
                    if (GrossSelectedIndex == 0)
                    {
                        string strIndex = objUtility.fnFireQueryTradeWeb("client_info", "cm_grossincome", "cm2_cd", userId.ToUpper(), true);
                        string strDate = objUtility.fnFireQueryTradeWeb("client_info", "cm_grossincomedt", "cm2_cd", userId.ToUpper(), true);
                        if (strIndex.Trim() != "")
                        {
                            int n;
                            if (int.TryParse(strIndex.Trim(), out n) == true)
                            {
                                GrossSelectedIndex = Convert.ToInt32(strIndex) - 1;
                            }
                        }
                        if (strDate.Trim() != "")
                        {
                            DateTime dtGross = objUtility.ConvertDT(strDate);
                            if (dtGross.Month > 3)
                            {
                                if (dtGross.AddYears(1).Year.ToString() != null)
                                {
                                    //cmbAsOn.ClearSelection();
                                    AsOnDate = dtGross.AddYears(1).Year.ToString();
                                }
                            }
                            else
                            {
                                if (dtGross.Year.ToString() != null)
                                {
                                    //cmbAsOn.ClearSelection();
                                    AsOnDate = dtGross.Year.ToString();
                                }
                            }
                        }
                    }

                    List<Generate_Combined_OTP_Response> combined_OTP_Responses = new List<Generate_Combined_OTP_Response>();
                    if ((!string.IsNullOrEmpty(New_Mobile_Number) && !string.IsNullOrEmpty(Mobile_Owner_Type)) || (!string.IsNullOrEmpty(New_Email_Id) && !string.IsNullOrEmpty(Email_Owner_Type)))
                    {
                        Generate_Combined_OTP_Response result = new Generate_Combined_OTP_Response();
                        if (!string.IsNullOrEmpty(New_Mobile_Number) && !string.IsNullOrEmpty(Mobile_Owner_Type))
                        {
                            result.New_mobile_OTP = Generate_New_Mobile_OTP_Combined_Execute(userId, Old_Mob_No, New_Mobile_Number, Mobile_Owner_Type);
                        }
                        if (!string.IsNullOrEmpty(New_Email_Id) && !string.IsNullOrEmpty(Email_Owner_Type))
                        {
                            result.New_email_OTP = Generate_New_Email_OTP_Combined_Execute(userId, Old_Email_Id, New_Email_Id, Email_Owner_Type);
                        }
                        combined_OTP_Responses.Add(result);
                        return result;
                    }
                    else
                    {
                        throw new Exception("New Details can not be blank");
                    }
                }
                else
                {
                    throw new Exception("OTP Mismatched");
                }
            }
            else
            {
                throw new Exception("OTP can not be blank");
            }

        }
