        public string ModificationRequest_Combined_Update_Execute(string userId, string OldIncome, ModificationRequestCombinedModel combined)
        {
            string strIDs = "";
            string SessionMOBILEID = "";
            string OldMobileNum = "";
            string NewMobileNum = "";
            string MobileType = "";
            int MobileSelectedIndex;
            string strMRelation = "";
            string SessionEMAILID = "";
            string OldEmailId = "";
            string NewEmail = "";
            string EmailType = "";
            int EmailSelectedIndex = default;
            string strGincome = "";
            string strGincomedt = "";
            string ext = "";
            int filesize;

            if (!string.IsNullOrEmpty(combined.New_Mobile_OTP))
            {
                DataSet dtSet = new DataSet();
                dtSet = objUtility.OpenDataSet("select * from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='O' and MCR_Item='MO'");
                OldMobileNum = dtSet.Tables[0].Rows[0]["MCR_OldValue"].ToString().Trim();
                NewMobileNum = dtSet.Tables[0].Rows[0]["MCR_New1"].ToString().Trim();
                MobileSelectedIndex = Convert.ToInt32(dtSet.Tables[0].Rows[0]["MCR_Owner"].ToString().Trim());
                SessionMOBILEID = dtSet.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();

                if (MobileSelectedIndex == 0)
                {
                    MobileType = "Self";
                }
                else if (MobileSelectedIndex == 1)
                {
                    MobileType = "Spouse";
                }
                else if (MobileSelectedIndex == 2)
                {
                    MobileType = "Dependent Children";
                }
                else if (MobileSelectedIndex == 3)
                {
                    MobileType = "Dependent Parent";
                }
                DataSet dtMContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + OldMobileNum.Trim() + "' and cc_type='M'");
                if (dtMContact.Tables[0].Rows.Count > 0)
                {
                    strMRelation = dtMContact.Tables[0].Rows[0]["cc_Relation"].ToString();
                }

                if (!string.IsNullOrEmpty(NewMobileNum))
                {
                    long i;
                    if (NewMobileNum.Trim().Length != 10)
                    {
                        throw new Exception("Please enter valid mobile number");
                    }
                    else if (combined.New_Mobile_OTP.Trim() == "")
                    {
                        throw new Exception("OTP Cannot be blank");
                    }
                    else if (!Int64.TryParse(NewMobileNum, out i))
                    {
                        throw new Exception("Please enter valid mobile number");
                    }
                    else if (NewMobileNum.Trim().ToLower() == OldMobileNum.Trim().ToLower() && MobileType.Trim() == strMRelation.Trim())
                    {
                        throw new Exception("Please enter new mobile number, the old and new mobile number cannot be the same.");
                    }
                    strsql = "select top 1 OTP_OTP,OTP_ValidTillDate,OTP_ValidTillTime from OTP_Master with (NoLock) where OTP_ClientCode='" + userId + "' and OTP_Item='MO' and OTP_Status='P' and OTP_SentTo='" + NewMobileNum.Trim() + "' and OTP_Product = 'TradeWebX' and OTP_Type = 'MCR' order by OTP_Identity desc";
                    DataTable dt = objUtility.OpenDataTable(strsql);
                    if (dt.Rows.Count > 0 && dt.Rows[0]["OTP_OTP"].ToString() == combined.New_Mobile_OTP.ToString())
                    {
                        DateTime dtNow = DateTime.Now;
                        DateTime dt3 = objUtility.stod(dt.Rows[0]["OTP_ValidTillDate"].ToString());
                        TimeSpan time = TimeSpan.Parse(dt.Rows[0]["OTP_ValidTillTime"].ToString());
                        DateTime dtExpiry = dt3 + time;
                        if (dtNow > dtExpiry)
                        {
                            strsql = "update OTP_Master set OTP_Status='E' where OTP_ClientCode='" + userId + "' and OTP_Item='MO' and OTP_Status='P' and OTP_OTP='" + combined.New_Mobile_OTP.Trim() + "' and OTP_SentTo='" + NewMobileNum.Trim() + "' and OTP_Product = 'TradeWebX' and OTP_Type = 'MCR'";
                            objUtility.ExecuteSQL(strsql);
                            throw new Exception("OTP has been expired");
                        }
                    }
                    else
                    {
                        throw new Exception("OTP Mismatched");
                    }
                }

                if (!string.IsNullOrEmpty(NewMobileNum))
                {
                    strsql = "update OTP_Master set OTP_Status='M' where OTP_ClientCode='" + userId + "' and OTP_Item='MO' and OTP_Status='P' and OTP_OTP='" + combined.New_Mobile_OTP.Trim() + "' and OTP_SentTo='" + NewMobileNum.Trim() + "' and OTP_Product = 'TradeWebX' and OTP_Type = 'MCR'";
                    objUtility.ExecuteSQL(strsql);
                    if (Convert.ToString(SessionMOBILEID) != "")
                    {
                        strsql = "update Master_Change_Request set MCR_Status ='N' ,MCR_ReplyOTP='" + combined.New_Mobile_OTP.Trim() + "' , MCR_ReplyDate='" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , MCR_ReplyTime='" + DateTime.Now.ToString("HH:mm:ss") + "' where MCR_ID='" + Convert.ToString(SessionMOBILEID) + "'";
                        objUtility.ExecuteSQL(strsql);
                        strIDs = Convert.ToString(SessionMOBILEID);
                        SessionMOBILEID = "";
                    }
                    else
                    {
                        strsql = "update Master_Change_Request set MCR_Status ='N' ,MCR_ReplyOTP='" + combined.New_Mobile_OTP.Trim() + "' , MCR_ReplyDate='" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , MCR_ReplyTime='" + DateTime.Now.ToString("HH:mm:ss") + "' where MCR_ClientCode='" + userId + "' and MCR_Item='MO' and MCR_OldValue='" + OldMobileNum.Trim() + "' and MCR_Status ='O'";
                        objUtility.ExecuteSQL(strsql);
                    }
                    strsql = "select MCR_ID from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='N' and MCR_Item='MO'";
                    DataSet dtID = new DataSet();
                    dtID = objUtility.OpenDataSet(strsql);
                    strIDs = dtID.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                }
            }

            if (!string.IsNullOrEmpty(combined.New_Email_OTP))
            {
                DataSet dtSet1 = new DataSet();
                dtSet1 = objUtility.OpenDataSet("select * from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='O' and MCR_Item='EI'");
                OldEmailId = dtSet1.Tables[0].Rows[0]["MCR_OldValue"].ToString().Trim();
                NewEmail = dtSet1.Tables[0].Rows[0]["MCR_New1"].ToString().Trim();
                EmailType = dtSet1.Tables[0].Rows[0]["MCR_Owner"].ToString().Trim();
                SessionEMAILID = dtSet1.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();

                string strERelation = "";
                DataSet dtEContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + OldEmailId.Trim() + "' and cc_type='E'");
                if (dtEContact.Tables[0].Rows.Count > 0)
                {
                    strERelation = dtEContact.Tables[0].Rows[0]["cc_Relation"].ToString();
                }
                if (!string.IsNullOrEmpty(NewEmail))
                {
                    if (NewEmail.Trim().Length > 0)
                    {
                        string strEmail = NewEmail.Trim();
                        Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
                        Match match = regex.Match(strEmail);
                        if (match.Success)
                        {
                            if (strEmail.ToLower() == OldEmailId.ToLower())
                            {
                                throw new Exception("Please enter new Email, the old and new Email cannot be the same.");
                            }
                            if (strEmail.ToUpper().Contains("NOEMAIL") == true || strEmail.ToUpper().Contains("NOTPROVIDED") == true || strEmail.ToUpper().Contains("XYZ") == true || char.IsDigit(strEmail.Split('@')[1][0]) == true)
                            {
                                throw new Exception("Enter valid Email ID");
                            }
                        }
                        else
                        {
                            throw new Exception("Enter valid Email ID");
                        }
                    }
                    else
                    {
                        throw new Exception("Email ID cannot be blank");
                    }
                    if (objUtility.GetWebParameter("SMTPSERVER").Trim() != "")
                    {
