                            DateTime dt3 = objUtility.stod(dt.Rows[0]["OTP_ValidTillDate"].ToString());
                            TimeSpan time = TimeSpan.Parse(dt.Rows[0]["OTP_ValidTillTime"].ToString());
                            DateTime dtExpiry = dt3 + time;
                            if (dtNow > dtExpiry)
                            {
                                strsql = "update OTP_Master set OTP_Status='E' where OTP_ClientCode='" + userId + "' and OTP_Item='EI' and OTP_Status='P' and OTP_OTP='" + combined.New_Email_OTP.Trim() + "' and OTP_SentTo='" + NewEmail.Trim() + "' and OTP_Product = 'TradeWebX' and OTP_Type = 'MCR'";
