                            objUtility.ExecuteSQL(strsql);
                        }
                    }
                    else
                    {
                        strsql = "delete from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status ='N' and MCR_Item='EI'";
                        objUtility.ExecuteSQL(strsql);
                        strsql = "Insert into Master_Change_Request values( '" + userId.ToUpper() + "' , 'EI' , '" + ip + "' ,  '" + System.Environment.MachineName.ToString() + "' , '" + OldEmailId.Trim() + "' , 'OTP Sent' , '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "' , '' , '' , '' , '" + EmailSelectedIndex.ToString() + "' ,'" + NewEmail.Trim() + "','" + strERelation.Trim() + "','','','','','', 'N','','' )";
                        objUtility.ExecuteSQL(strsql);
                    }
                    strsql = "select MCR_ID from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='N' and MCR_Item='EI'";
                    DataSet dtID = new DataSet();
                    dtID = objUtility.OpenDataSet(strsql);
                    strIDs = dtID.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                }
