                {
                    throw new Exception("New Email id can not be blank");
                }
            }

            if (!string.IsNullOrEmpty(combined.NewGrossIncome) && !string.IsNullOrEmpty(combined.AsOnDate) && !string.IsNullOrEmpty(combined.image))
            {
                byte[] bytes = System.Convert.FromBase64String(combined.image);

                int GrossSelectedIndex = default;
                #region Code Not Required
                //string strIndex = objUtility.fnFireQueryTradeWeb("client_info", "cm_grossincome", "cm2_cd", userId.ToUpper(), true);
                //string strDate = objUtility.fnFireQueryTradeWeb("client_info", "cm_grossincomedt", "cm2_cd", userId.ToUpper(), true);
