                    var data = combined.image.Substring(0, 5);
                    switch (data.ToUpper())
                    {
                        case "IVBOR":
                            ext = ".png";
                            break;
                        case "/9J/4":
                            ext = ".jpeg";
                            break;
                        case "JVBER":
                            ext = ".pdf";
                            break;
                    }
                    bool isValidFile = false;
                    for (int i = 0; i < validFileTypes.Length; i++)
                    {
                        if (ext.Equals("." + validFileTypes[i], StringComparison.OrdinalIgnoreCase))
                        {
                            isValidFile = true;
                            break;
                        }
                    }
                    if (isValidFile == true)
                    {
                        filesize = bytes.Length;
                        if (filesize < 512000)
                        {
                        }
                        else
                        {
                            throw new Exception("Gross Annual Income Proof to be in PDF / JPEG / PNG / BMP format only with size less than 500 kb");
                        }
                    }
                    else
                    {
                        throw new Exception("Gross Annual Income Proof to be in PDF / JPEG / PNG / BMP format only");
                    }
                }

                var ip = _httpContextAccessor.HttpContext.Connection.RemoteIpAddress.ToString();
