                Strsql = @"Insert into Master_Change_Request values( '" + userId.ToUpper() + "' , 'GI' , '" + ip + "' ,  '" + System.Environment.MachineName.ToString() + "' , '" + (OldIncome.Trim() != "" ? (strGincome + "~" + strGincomedt) : "") + "' , 'OTP Sent' , '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "' , '' , '' , '' , '' ,'" + ext + "','','','','','',@Image, 'N','" + Convert.ToInt32(GrossSelectedIndex + 1) + "','" + combined.AsOnDate.ToString() + "0331" + "' )";
                SqlConnection con;
                using (var db = new DataContext())
                {
                    con = new SqlConnection((db.Database.GetDbConnection()).ConnectionString);
                    con.Open();
                    using (SqlCommand MyCmd = new SqlCommand())
                    {
                        MyCmd.Connection = con;
                        MyCmd.CommandTimeout = 5000;
                        MyCmd.CommandText = Strsql;
                        MyCmd.Parameters.Add("@Image", SqlDbType.Image);
                        MyCmd.Parameters[0].Value = bytes;
                        MyCmd.ExecuteNonQuery();
                        MyCmd.Dispose();
                    }
                    Strsql = "select MCR_ID from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='N' and MCR_Item='GI'";
                    DataSet dtID = new DataSet();
                    dtID = objUtility.OpenDataSet(Strsql);
                    strIDs = dtID.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                }
            }
            else
            {
                throw new Exception("New Income Details can not be null");
            }

            string strMessage = "Your Change Request has been Registered. Ref No : " + strIDs;
            return strMessage;

