        public string MOTP(string userId, string OldMobileNumber, string NewMobileNumber, string SessionMOBILEID, int MobileSelectedIndex)
        {
            long i;
            //string strmsg;
            string strMobile = NewMobileNumber.Trim();
            string strRelation = "";
            DataSet dtContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + OldMobileNumber.Trim() + "' and cc_type='M'");

            if (dtContact.Tables[0].Rows.Count != 0)
            {
                strRelation = dtContact.Tables[0].Rows[0]["cc_Relation"].ToString();
            }

            if (strMobile == "")
            {
                throw new Exception("Mobile number cannot be blank");
            }
            else if (strMobile.Length != 10)
            {
                throw new Exception("Mobile number to be 10 digits");
            }
            else if (!Int64.TryParse(strMobile, out i))
            {
                throw new Exception("Mobile number to be 10 digits");
            }
            else if (strMobile.ToLower() == OldMobileNumber.Trim().ToLower())
            {
                throw new Exception("Please enter new mobile number, the old and new mobile number cannot be the same.");
            }

            Boolean blnRepeat = false;
            if (strMobile.StartsWith("1") || strMobile.StartsWith("2") || strMobile.StartsWith("3") || strMobile.StartsWith("4") || strMobile.StartsWith("5"))
            {
                throw new Exception("Please enter valid mobile number");
            }
            for (int j = 0; j < strMobile.Length; j++)
            {
                if (strMobile[j] != strMobile[0])
                {
                    blnRepeat = false;
                    break;
                }
                else
                {
                    blnRepeat = true;
                }
            }
            if (blnRepeat == true)
            {
                throw new Exception("Please enter valid mobile number");
            }
            //string mode = "NMOBILE";
            var New_OTP = ModificationRequest_Generate_OTP_SMS_Email(userId, strMobile.Trim(), "MOBILE");
            if (string.IsNullOrEmpty(New_OTP))
            {
                throw new Exception("OTP Can not be null");
            }
            //int MobileSelectedIndex=default;

            var ip = _httpContextAccessor.HttpContext.Connection.RemoteIpAddress.ToString();
            if (!string.IsNullOrEmpty(NewMobileNumber))
            {
                if (Convert.ToString(SessionMOBILEID) != "")
                {
                    strsql = "update master_change_request set MCR_New1='" + NewMobileNumber.Trim() + "', MCR_Date='" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "', MCR_Time='" + DateTime.Now.ToString("HH:mm:ss") + "',MCR_Owner='" + MobileSelectedIndex.ToString() + "', MCR_IP='" + ip + "', MCR_MachineName='" + System.Environment.MachineName.ToString() + "' where MCR_ID='" + Convert.ToString(SessionMOBILEID) + "'";
                    objUtility.ExecuteSQL(strsql);
                }
                else
                {
                    strsql = "delete from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status ='N' and MCR_Item='MO'";
                    objUtility.ExecuteSQL(strsql);
                    strsql = "Insert into Master_Change_Request values( '" + userId.ToUpper() + "' , 'MO' , '" + ip + "' ,  '" + System.Environment.MachineName.ToString() + "' , '" + OldMobileNumber.Trim() + "' , 'OTP Sent' , '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "' ,'', '' , '' , '" + MobileSelectedIndex.ToString() + "' ,'" + NewMobileNumber.Trim() + "','" + strRelation.Trim() + "','','','','', '' , 'O','','' )";
                    objUtility.ExecuteSQL(strsql);
                    DataSet dtSet = new DataSet();
                    dtSet = objUtility.OpenDataSet("select * from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='O' and MCR_Item='MO'");
                    SessionMOBILEID = dtSet.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                }
            }
            return New_OTP;
        }
        public string EOTP(string userId, string OldEmail, string NewEmailId, string SessionEMAILID, int EmailSelectedIndex)
        {
            if (NewEmailId.Trim() == "")
            {
                throw new Exception("Email ID cannot be blank");
            }

            string strEmail = NewEmailId.Trim();
            string strRelation = "";
            DataSet dtContact = objUtility.OpenDataSet("Select * from Common_Contacts Where cc_Client = '" + userId.ToUpper() + "' and cc_Contact = '" + OldEmail.Trim() + "' and cc_type='E'");

            if (dtContact.Tables[0].Rows.Count != 0)
            {
                strRelation = dtContact.Tables[0].Rows[0]["cc_Relation"].ToString();
            }
            Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
            Match match = regex.Match(strEmail);
            if (match.Success)
            {
                if (strEmail.ToLower() == OldEmail.Trim().ToLower())
                {
                    throw new Exception("Please enter new Email, the old and new Email cannot be the same.");
                }
                if (strEmail.ToUpper().Contains("NOEMAIL") == true || strEmail.ToUpper().Contains("NOTPROVIDED") == true || strEmail.ToUpper().Contains("XYZ") == true || char.IsDigit(strEmail.Split('@')[1][0]) == true)
                {
                    throw new Exception("Enter valid Email ID");
                }
            }
            else
            {
                throw new Exception("Enter valid Email ID");
            }

            //Session["TYPE"] = "NEMAIL";
            var New_EOtp = ModificationRequest_Generate_OTP_SMS_Email(userId, NewEmailId.Trim(), "EMAIL");
            if (string.IsNullOrEmpty(New_EOtp))
            {
                throw new Exception("EOTP can not be blank");
            }
            //lblEeotp.Attributes.Add("style", "visibility:visible;");
            //txtNeotp.Attributes.Add("style", "visibility:visible;");

            #region Old Code
            var ip = _httpContextAccessor.HttpContext.Connection.RemoteIpAddress.ToString();
            if (!string.IsNullOrEmpty(NewEmailId))
            {
                if (Convert.ToString(SessionEMAILID) != "")
                {
                    strsql = "update master_change_request set MCR_New1='" + NewEmailId.Trim() + "', MCR_Date='" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "', MCR_Time='" + DateTime.Now.ToString("HH:mm:ss") + "',MCR_Owner='" + EmailSelectedIndex.ToString() + "', MCR_IP='" + ip + "', MCR_MachineName='" + System.Environment.MachineName.ToString() + "' where MCR_ID='" + Convert.ToString(SessionEMAILID) + "'";
                    objUtility.ExecuteSQL(strsql);
                }
                else
                {
                    strsql = "delete from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status ='N' and MCR_Item='EI'";
                    objUtility.ExecuteSQL(strsql);
                    strsql = "Insert into Master_Change_Request values( '" + userId.ToUpper() + "' , 'EI' , '" + ip + "' ,  '" + System.Environment.MachineName.ToString() + "' , '" + OldEmail.Trim() + "' , 'OTP Sent' , '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "' ,'', '' , '' , '" + EmailSelectedIndex.ToString() + "' ,'" + NewEmailId.Trim() + "','" + strRelation.Trim() + "','','','','', '' , 'O' ,'','')";
                    objUtility.ExecuteSQL(strsql);
                    DataSet dtSet = new DataSet();
                    dtSet = objUtility.OpenDataSet("select * from master_change_request where MCR_ClientCode='" + userId.ToUpper() + "' and MCR_Status='O' and MCR_Item='EI'");
                    SessionEMAILID = dtSet.Tables[0].Rows[0]["MCR_ID"].ToString().Trim();
                }
            }
            #endregion
            return New_EOtp;
        }
        public void checkTable()
        {
            DataSet dsCreate = new DataSet();
            strsql = "select * from SysObjects where name= 'Master_Change_Request'";
            dsCreate = objUtility.OpenDataSet(strsql);
            if (dsCreate.Tables[0].Rows.Count == 0)
            {
                strsql = "CREATE TABLE Master_Change_Request(";
                strsql += " [MCR_ID] [int] IDENTITY(1,1) NOT NULL,";
                strsql += " [MCR_ClientCode] [char](8) NOT NULL,";
                strsql += " [MCR_Item] [char](2) NOT NULL,";
                strsql += " [MCR_IP] [varchar](20) NOT NULL,";
                strsql += " [MCR_MachineName] [varchar](50) NOT NULL,";
                strsql += " [MCR_OldValue] [varchar](100) NOT NULL,";
                strsql += " [MCR_Reason] [varchar](100) NOT NULL,";
                strsql += " [MCR_Date] [char](8) NOT NULL,";
                strsql += " [MCR_Time] [char](8) NOT NULL,";
                strsql += " [MCR_ReplyOTP] [varchar](8) NOT NULL,";
                strsql += " [MCR_ReplyDate] [varchar](8) NOT NULL,";
                strsql += " [MCR_ReplyTime] [varchar](8) NOT NULL,";
                strsql += " [MCR_Owner] [char](1) NOT NULL,";
                strsql += " [MCR_New1] [varchar](100) NOT NULL,";
                strsql += " [MCR_New2] [varchar](50) NOT NULL,";
                strsql += " [MCR_New3] [varchar](50) NOT NULL,";
                strsql += " [MCR_NewCity] [varchar](50) NOT NULL,";
                strsql += " [MCR_NewState] [varchar](50) NOT NULL,";
                strsql += " [MCR_NewPin] [varchar](6) NOT NULL,";
                strsql += " [MCR_ReplyProof] [image] NOT NULL,";
                strsql += " [MCR_Status] [char](1) NOT NULL,";
                strsql += " CONSTRAINT [PK_MasterChangeRequest] PRIMARY KEY CLUSTERED ([MCR_ID]))";
                objUtility.ExecuteSQL(strsql);
            }

            objUtility.CreateOTPMasterTable();
        }
        public Boolean IsNSDLClient(string userId)
        {
            Boolean blnNSDL = false;
            if (_configuration["Estro"] != "")
            {
                strsql = "select case left(da_dpid,2) when 'IN' then 'Y' else 'N' end as IsNSDL ,da_dpid ,da_actno from Dematact ";
                strsql += "where  da_clientcd='" + userId + "' and da_defaultyn='y'";
                DataTable dtUser = objUtility.OpenDataTable(strsql);
                if (dtUser.Rows.Count > 0)
                {
                    if (dtUser.Rows[0]["IsNSDL"].ToString().Trim() == "Y")
                    {
                        blnNSDL = true;
                    }
                }
            }
            return blnNSDL;
        }
