        #region CommonAPI Methods

        public dynamic Execute(CommonModel commonModel)
        {
            string ProcedureName = "";
            int SerialNo = 0;
            string strErrorMsg = "";
            string comma = "";

            if (string.IsNullOrWhiteSpace(commonModel.ProjectName))
            {
                strErrorMsg += comma + "Project Name is missing";
                comma = ",";
            }
            if (string.IsNullOrWhiteSpace(commonModel.FunctionName))
            {
                strErrorMsg += comma + "Function Name is missing";
                comma = ",";
            }
            if (string.IsNullOrWhiteSpace(commonModel.ModuleName))
            {
                strErrorMsg += comma + "Module Name is missing";
                comma = ",";
            }
            if (string.IsNullOrWhiteSpace(commonModel.UserID))
            {
                strErrorMsg += comma + "User Id is missing";
                comma = ",";
            }
            try
            {
                JObject requestString = JObject.Parse(commonModel.RequestString.ToString());
            }
            catch (Exception ex)
            {
                strErrorMsg += comma + "Request String:" + ex.Message;
                comma = ",";
            }

            string sql = "select SerialNo, ProcedureName, IsDebugEnabled from tbl_GenericAPIDefinition";
            sql += " where ProjectName='" + commonModel.ProjectName + "' and ModuleName='" + commonModel.ModuleName + "' and FunctionName='" + commonModel.FunctionName + "'";
            DataTable dt = objUtility.OpenDataTable(sql);
            if (dt.Rows.Count > 0)
            {
                SerialNo = Convert.ToInt32(dt.Rows[0]["SerialNo"].ToString().Trim());
                ProcedureName = dt.Rows[0]["ProcedureName"].ToString().Trim();
            }

            if (SerialNo > 0)
            {
                string connetionString = objUtility.GetConnectionStr();
                using (SqlConnection conn = new SqlConnection(connetionString))
                {
                    using (SqlCommand cmd = new SqlCommand(ProcedureName))
                    {
                        cmd.CommandType = CommandType.StoredProcedure;
                        //cmd.CommandTimeout = 0;
                        if (conn.State == ConnectionState.Closed)
                            conn.Open();
                        cmd.Connection = conn;
                        cmd.Parameters.Add(new SqlParameter("@i_vcProjectName", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcProjectName"].Value = commonModel.ProjectName;
                        cmd.Parameters.Add(new SqlParameter("@i_vcModuleName", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcModuleName"].Value = commonModel.ModuleName;
                        cmd.Parameters.Add(new SqlParameter("@i_vcFunctionName", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcFunctionName"].Value = commonModel.FunctionName;
                        cmd.Parameters.Add(new SqlParameter("@i_vcSource", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcSource"].Value = commonModel.RequestSource;
                        cmd.Parameters.Add(new SqlParameter("@i_vcUniqueID", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcUniqueID"].Value = commonModel.RequestUniqueID;
                        cmd.Parameters.Add(new SqlParameter("@i_vcUserID", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcUserID"].Value = commonModel.UserID;
                        cmd.Parameters.Add(new SqlParameter("@i_vcInputJSON", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcInputJSON"].Value = commonModel.RequestString.ToString();

                        cmd.Parameters.Add(new SqlParameter("@o_vcOutPutJSON", SqlDbType.VarChar, 2000000));
                        cmd.Parameters["@o_vcOutPutJSON"].Direction = ParameterDirection.Output;
                        cmd.CommandTimeout = 0;
                        cmd.ExecuteNonQuery();

                        string retValue = cmd.Parameters["@o_vcOutPutJSON"].Value.ToString();

                        JArray jsonArray = null;
                        try
                        {
                            if (!string.IsNullOrEmpty(retValue))
                            {
                                jsonArray = JArray.Parse(retValue);
                            }
                        }
                        catch (Exception ex)
                        {
                            throw ex;
                        }
                        cmd.Parameters.Clear();
                        return jsonArray;
                    }
                }
            }
            else
            {
                return JsonConvert.DeserializeObject("[{\"ResponseFlag\":\"E\", \"ResponseMessage\":\"Invalid Request Definition\"}]");
            }
        }

        public static Decimal InsertIntoLogMessage(object obj, string connectionString)
        {
            Decimal sno = 0;
            string sql = "insert into tbl_GenericAPIDebugLog (RequestString, UpdateTimeStamp)";
            sql += " Values (@RequestString, GetDate())";
            using (SqlConnection conn = new SqlConnection(connectionString))
            {
                using (SqlCommand cmd = new SqlCommand(sql, conn))
                {
                    cmd.Parameters.AddWithValue("@RequestString", obj.ToString());
                    if (conn.State == ConnectionState.Closed)
                        conn.Open();
                    cmd.ExecuteNonQuery();
                }
                string sql3 = "SELECT IDENT_CURRENT('tbl_GenericAPIDebugLog')";
                using (SqlCommand cmd = new SqlCommand(sql3, conn))
                {
                    if (conn.State == ConnectionState.Closed)
                        conn.Open();
                    SqlDataReader rs = cmd.ExecuteReader();
                    if (rs.Read())
                    {
                        sno = rs.GetDecimal(0);
                    }
                }
            }
            return sno;
        }

