        #region TradeWeb CommonGrid Methods

        public dynamic TradeWebCommonGrid(string userId, TradeWebDataGridRequest commonModel)
        {
            TradeWebDataGridResponse response = new TradeWebDataGridResponse();
            string ProcedureName = "";
            int SerialNo = 0;
            string strErrorMsg = "";
            string comma = "";
            string strReportCode = "";
            string strReportCategory = "";
            string strXML = "";

            if (string.IsNullOrWhiteSpace(commonModel.ReportCode))
            {
                strErrorMsg += comma + "Report Code is missing";
                comma = ",";
            }
            if (string.IsNullOrWhiteSpace(userId))
            {
                strErrorMsg += comma + "Client Code is missing";
                comma = ",";
            }
            try
            {
                strXML = commonModel.XML;
                try
                {
                    System.Xml.XmlDocument xmlDoc = new System.Xml.XmlDocument();
                    xmlDoc.LoadXml("<Root>" + strXML + "</Root>");
                    UpdateXmlValue(xmlDoc, "UserId", userId);
                    UpdateXmlValue(xmlDoc, "SelectTag", "C");
                    strXML = xmlDoc.OuterXml;
                    strXML = strXML.Replace("<Root>", "").Replace("</Root>", "");
                }
                catch (Exception ex)
                {
                    response.Message = "XML string is Not valid";
                    response.Data = null;
                    return response;
                }
            }
            catch (Exception ex)
            {
                strErrorMsg += comma + "Request String:" + ex.Message;
                comma = ",";
            }

            if (!string.IsNullOrWhiteSpace(strErrorMsg))
            {
                response.Message = strErrorMsg;
                response.Data = null;
                return response;
            }

            string strFunctionName = commonModel.ReportCode.Trim() + "|" + commonModel.ReportCategory.Trim();
            string sql = "select SerialNo, ProcedureName, IsDebugEnabled from tbl_GenericAPIDefinition";
            sql += " where ProjectName='TradeWebAPI' and ModuleName='TradeWeb' and FunctionName='" + strFunctionName + "'";
            DataTable dt = objUtility.OpenDataTable(sql);
            if (dt.Rows.Count > 0)
            {
                SerialNo = Convert.ToInt32(dt.Rows[0]["SerialNo"].ToString().Trim());
                ProcedureName = dt.Rows[0]["ProcedureName"].ToString().Trim();
            }

            if (SerialNo > 0)
            {
                string strModuleName = "TradeWeb";
                strReportCode = commonModel.ReportCode.Trim();
                strReportCategory = commonModel.ReportCategory.Trim();

                string connetionString = objUtility.GetConnectionStr();
                using (SqlConnection conn = new SqlConnection(connetionString))
                {
                    using (SqlCommand cmd = new SqlCommand(ProcedureName))
                    {
                        cmd.CommandType = CommandType.StoredProcedure;
                        cmd.CommandTimeout = 0;
                        if (conn.State == ConnectionState.Closed)
                            conn.Open();
                        cmd.Connection = conn;
                        cmd.Parameters.Add(new SqlParameter("@vcXML", SqlDbType.VarChar));
                        cmd.Parameters["@vcXML"].Value = strXML;
                        cmd.Parameters.Add(new SqlParameter("@i_vcProjectCode", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcProjectCode"].Value = strModuleName;
                        cmd.Parameters.Add(new SqlParameter("@i_vcReportCode", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcReportCode"].Value = strReportCode;
                        cmd.Parameters.Add(new SqlParameter("@i_vcReportCategory", SqlDbType.VarChar));
                        cmd.Parameters["@i_vcReportCategory"].Value = strReportCategory;

                        cmd.Parameters.Add(new SqlParameter("@o_vcErrorFlag", SqlDbType.VarChar, 2000000));
                        cmd.Parameters["@o_vcErrorFlag"].Direction = ParameterDirection.Output;
                        cmd.Parameters.Add(new SqlParameter("@o_vcErrorMessage", SqlDbType.VarChar, 2000000));
                        cmd.Parameters["@o_vcErrorMessage"].Direction = ParameterDirection.Output;

                        SqlDataAdapter adap = new SqlDataAdapter
                        {
                            SelectCommand = cmd
                        };
                        DataSet ds = new DataSet();
                        adap.Fill(ds);
                        cmd.ExecuteNonQuery();

                        string retErrFlag = cmd.Parameters["@o_vcErrorFlag"].Value.ToString();
                        string retErrMsg = cmd.Parameters["@o_vcErrorMessage"].Value.ToString();
                        cmd.Parameters.Clear();

                        if (retErrFlag.Trim() == "E")
                        {
                            response.Message = retErrMsg;
                            response.Data = null;
                        }
                        else
                        {
                            List<DataSet> lstDs = new List<DataSet>();
                            lstDs.Add(ds);
                            response.Message = "";
                            response.Data = lstDs;
                        }
                        return response;
                    }
                }
            }

            return null;
        }

        static void UpdateXmlValue(System.Xml.XmlDocument xmlDoc, string tagName, string newValue)
        {
            // Find the specified element by tag name
            System.Xml.XmlNode node = xmlDoc.SelectSingleNode("//" + tagName);

            // Update the value of the element if found
            if (node != null)
            {
                node.InnerText = newValue;
            }
        }

