        public dynamic GetKyc_Details(FinalReKycModel respModel, string userId)
        {
            try
            {
                string strSql = string.Empty;
                RekycGetJsonModel rekycGetJsonModel = new RekycGetJsonModel();
                var db = new DataContext();
                string status = "";
                DataTable dbTable = objUtility.OpenDataTable("Select  * from Client_ModifyAttach (NoLock) where ma_cmcd = '" + userId + "' and ma_field = 'json'  and ma_status = 'N' order by ma_srno desc");
                if (dbTable.Rows.Count > 0)
                {
                    var strResponse = JObject.Parse(Encoding.UTF8.GetString((byte[])dbTable.Rows[0]["ma_proof"]).ToString());
                    rekycGetJsonModel.rekycJson = strResponse;
                    DataTable dtRkC = objUtility.OpenDataTable("Select  * from Client_ReKycMain (NoLock) where rm_cmcd = '" + userId + "' and rm_rekyc = 'N'  and rm_step = '1' order by rm_srno desc");
                    if (dtRkC.Rows.Count > 0)
                    {
                        status = dtRkC.Rows[0]["rm_desc"].ToString();
                    }
                    var step = Convert.ToInt16(ReKYC_GetSteps(userId, "rm_step", "ReKYC"));

                    if (step == 3)
                    {
                        strResponse["RekycJson"][0]["ReKycDetails"][0]["RekycStatus"] = "Pending for E-Sign";
                    }
                    else if (step == 4)
                    {
                        strResponse["RekycJson"][0]["ReKycDetails"][0]["RekycStatus"] = "Pending for E-Sign KRA";
                    }
                    else if (step == 5)
                    {
                        strResponse["RekycJson"][0]["ReKycDetails"][0]["RekycStatus"] = "Pending for Approval";
                    }
                    else
                    {
                        strResponse["RekycJson"][0]["ReKycDetails"][0]["RekycStatus"] = status;
                    }
                    return rekycGetJsonModel;
                }
                else
                {
                    try
                    {
                        SqlParameter[] sqlPrm = new[]
                        {
                            new SqlParameter("@i_vcClientCode",userId),
                           // new SqlParameter("@i_vcPassingValueType","XML"),
                            new SqlParameter("@i_vcTemplateCode","Template1"),
                            new SqlParameter("@i_vcProcessTag","G"),
                        };
                        List<OutputParamSP> spModelList = new List<OutputParamSP>();
                        OutputParamSP spModel = new OutputParamSP();
                        spModel.ParamValue = "@o_vcErrorFlag";
                        spModel.DbType = SqlDbType.VarChar;
                        spModel.Length = 1;
                        spModelList.Add(spModel);
                        spModel = new OutputParamSP();
                        spModel.ParamValue = "@o_vcErrorMessage";
                        spModel.DbType = SqlDbType.VarChar;
                        spModel.Length = 500;
                        spModelList.Add(spModel);
                        spModel = new OutputParamSP();
                        spModel.ParamValue = "@o_vcJsonOutput";
                        spModel.DbType = SqlDbType.NVarChar;
                        spModel.Length = 8000;
                        spModelList.Add(spModel);
                        var respSP = objUtility.Execute_SP_OuputParam("SP_ReKyc_GetData", sqlPrm, spModelList);
                        string[] breakResp = respSP.ToString().Split('$');
                        if (breakResp[0] != "S")
                        {
                            var jsonResp = JsonConvert.DeserializeObject(breakResp[2]);
                            rekycGetJsonModel.errorMsg = breakResp[1];
                            return rekycGetJsonModel;
                        }
                        if (!string.IsNullOrEmpty(breakResp[2]))
                        {
                            //var xmlStr = breakResp[2];//.Replace("<row>", "");
                            ////xmlStr = xmlStr.Replace("</row>", "");
                            //XmlDocument doc = new XmlDocument();
                            //doc.LoadXml(xmlStr);
                            //string jsonText = JsonConvert.SerializeXmlNode(doc);
                            //jsonText = jsonText.Replace("{\"row\":", "[");
                            //jsonText = jsonText.Replace("}}", "}]");
                            //jsonText = jsonText.Replace("[[{", "[{");
                            //jsonText = jsonText.Replace("}]}", "}]");
                            //jsonText = jsonText.Replace("}]]", "}]}]");
                            //jsonText = jsonText.Replace(":{\"ReKycDetails\":", ":[{\"ReKycDetails\":");
                            var jsonResp = JsonConvert.DeserializeObject<dynamic>(breakResp[2]);
                            rekycGetJsonModel.rekycJson = jsonResp;
                            return rekycGetJsonModel;
                        }
                        rekycGetJsonModel.errorMsg = "No records found!";
                        return rekycGetJsonModel;
                    }
                    catch (Exception ex)
                    {
                        throw ex;
                    }
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

