                            break;
                    }
                    strResStatus += " [" + dtCode.Rows[0]["cm_residentialstatus"].ToString().Trim() + "]";
                    string strAccStatus = "";
                    switch (dtCode.Rows[0]["cm_freezeyn"].ToString().Trim())
                    {
                        case "A":
                            strAccStatus = "Freeze for All";
                            break;
                        case "Y":
                            strAccStatus = "Freeze for Trades";
                            break;
                        case "B":
                            strAccStatus = "Freeze for Branches";
                            break;
                        default:
                            strAccStatus = "Active";
                            break;
                    }

                    string strCKYCNo = "";
                    strsql = "Select count(0) From sysobjects Where name = 'Client_CKYC'";
                    dtTemp = objUtility.OpenDataTable(strsql);
                    if (Conversion.Val(dtTemp.Rows[0][0].ToString()) != 0)
                    {
                        strsql = "select isNull(case ck_status when 'Y' then 'Pending' when 'E' then 'Exported' when 'S' then 'Success' else 'Pending' end, '') as ck_status, " +
                                    " isNull(Ck_Reference,'') Ck_Reference, isNull(case Ck_RespType when '02' then 'Post De-Duplication' when '03' then 'Post FIR' when '04' then 'Post confirmation with ID issuer' " +
                                    " when '05' then 'Post KYC Generation' else '' end, '') as ckresponsetype, isNull(Ck_Nfiller1,0) as ckycnumber, isNull(mkrdt,'') mkrdt " +
                                    " from Client_CKYC " +
                                    " where CK_SRNO in (select MAX(ck_SRNo) From Client_CKYC  Group By CK_Panno) And ck_panno ='" + dtCode.Rows[0]["cm_panno"].ToString().Trim() + "' ";
                        dtTemp = objUtility.OpenDataTable(strsql);
                        if (dtTemp.Rows.Count != 0)
                        {
                            strCKYCNo = dtTemp.Rows[0]["ckycnumber"].ToString().Trim();
                        }
                    }

                    FinalReKycModel kycModel = new FinalReKycModel();

                    kycModel.KycMode = "";
                    kycModel.KycNumber = strCKYCNo;
                    kycModel.NomineeOpt = "";
                    Personal PersonalDetails = new Personal()
                    {
                        ClientCode = userId,
                        FirstName = dtCode.Rows[0]["cm_name"].ToString().Trim(),
                        LastName = "",
                        MiddleName = "",
                        FatherName = dtCode.Rows[0]["cm_faherhusguar"].ToString().Trim(),
                        PAN = dtCode.Rows[0]["cm_panno"].ToString().Trim(),
                        UID = dtCode.Rows[0]["cm_uid"].ToString().Trim(),
                        Mobile = dtCode.Rows[0]["cm_mobile"].ToString().Trim(),
                        Email = dtCode.Rows[0]["cm_email"].ToString().Trim(),
                        Gender = strGender,
                        DateOfBirth = dtCode.Rows[0]["cm_dob"].ToString().Trim(),
                        MaritalStatus = strMaritalStatus,
                        CorrAddress1 = dtCode.Rows[0]["cm_add1"].ToString().Trim(),
                        CorrAddress2 = dtCode.Rows[0]["cm_add2"].ToString().Trim(),
                        CorrAddress3 = dtCode.Rows[0]["cm_add3"].ToString().Trim(),
                        CorrCity = dtCode.Rows[0]["cm_add4"].ToString().Trim(),
                        CorrState = dtCode.Rows[0]["cm_state"].ToString().Trim(),
                        CorrCountry = dtCode.Rows[0]["cm_BankActNo"].ToString().Trim(),
                        CorrPincode = dtCode.Rows[0]["cm_pincode"].ToString().Trim(),
                        Income = strIncome,
                        IncomeValue = strIncomeValue,
                        IncomeDate = dtCode.Rows[0]["cm_grossincomedt"].ToString().Trim(),
                        ClientsNamePrefix = dtCode.Rows[0]["cm_prefix"].ToString().Trim()
                    };

                    kycModel.PersonalDetails = PersonalDetails;
                    kycModel.NomineeDetails = nomList;
                    kycModel.BankDetails = bankList;
                    kycModel.DematDetails = dematList;
                    kycModel.SegmentDetails = tempSegment;
                    strsql = "select * From WebParameter where sp_parmcd='SetuSetting'";
                    DataTable dtSetuSetting = objUtility.OpenDataTable(strsql);
                    if (dtSetuSetting.Rows.Count > 0)
                    {
                        var setStr = (dtSetuSetting.Rows[0]["sp_sysvalue"].ToString()).Split('/');
                        if (setStr.Length > 0)
                        {
                            kycModel.ApiCallAddress = setStr[0].ToString();
                        }
                        if (setStr.Length > 1)
                        {
                            kycModel.ApiCallBank = setStr[1].ToString();
                        }
                    }
                    Dormant dormant = new Dormant();
                    dormant.DormantStatus = strAccStatus;
                    dormant.DormantIsActive = false;
                    kycModel.DormantDetails = dormant;
                    #endregion

                    return kycModel;
                }
                return null;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

