        public dynamic ReKYC_MasterTable(string userId, string status, string rekyc, int step, string desc, string requestType)
        {
            try
            {
                DateTime todayDate = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, UtilityCommon.GetIndianTimeZone());
                string strSql = string.Empty;
                if (string.IsNullOrEmpty(requestType))
                {
                    requestType = "ReKYC";
                }
                else if (requestType.ToLower() != "rekyc" && requestType.ToLower() != "account closure")
                {
                    requestType = "ReKYC";
                }
                string maxRefNo = "1001";
                strSql = " Select  * from Client_ReKycMain (NoLock) where rm_cmcd = '" + userId + "' And rm_rekyc = 'N' And rm_step < 6 And rm_RequestType = '" + requestType + "'  Order by rm_srno Desc ";
                DataTable dbTable = objUtility.OpenDataTable(strSql);
                if (dbTable.Rows.Count > 0)
                {
                    if (step < Convert.ToInt16(dbTable.Rows[0]["rm_step"].ToString()))
                        step = Convert.ToInt16(dbTable.Rows[0]["rm_step"].ToString());

                    strSql = " Update  Client_ReKycMain set ";
                    strSql += " rm_rekyc = '" + rekyc + "',";
                    strSql += " rm_status = '" + status + "',";
                    strSql += " rm_desc = '" + desc + "',";
                    strSql += " rm_step = " + step + ",";
                    strSql += " mkrdt = '" + todayDate.ToString("yyyyMMdd") + "',";
                    strSql += " mkrtm = '" + todayDate.ToString("HH:mm:ss") + "' ";
                    strSql += " Where rm_cmcd = '" + userId + "' and rm_refno = " + dbTable.Rows[0]["rm_refno"].ToString() + ";";
                    maxRefNo = dbTable.Rows[0]["rm_refno"].ToString();
                }
                else
                {
                    SqlTransaction objTrans = null;
                    var db = new DataContext();
                    using (SqlConnection ObjConnection = new SqlConnection((db.Database.GetDbConnection()).ConnectionString))
                    {
                        if (ObjConnection.State == ConnectionState.Closed)
                            ObjConnection.Open();
                        objTrans = ObjConnection.BeginTransaction();
                        try
                        {
                            string sqlStrRfNo = "Select Isnull(Max(rm_refno),1000) + 1 From Client_ReKycMain (NoLock)";
                            maxRefNo = objUtility.ExecuteSQLStringTrans(sqlStrRfNo, ObjConnection, objTrans);
                            objTrans.Commit();
                        }
                        catch (Exception)
                        {
                            objTrans.Rollback();
                        }
                    }
                    strSql = " insert into Client_ReKycMain (rm_cmcd, rm_cdate, rm_ctime, rm_rekyc, rm_status,rm_desc, mkrdt, mkrtm, rm_step,rm_refno, rm_RequestType)";
                    strSql += " values ('" + userId.ToUpper() + "', '" + todayDate.ToString("yyyyMMdd") + "','" + todayDate.ToString("HH:mm:ss") + "', 'N', '" + status + "',";
                    strSql += " '', '" + todayDate.ToString("yyyyMMdd") + "', '" + todayDate.ToString("HH:mm:ss") + "',0," + maxRefNo + ", '" + requestType + "' )";
                }
                objUtility.ExecuteSQL(strSql);
                return maxRefNo;
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic AddKyc_Details(string userId, object model, string fieldStatus, string refNo)
        {
            try
            {
                DateTime todayDate = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, UtilityCommon.GetIndianTimeZone());

                //var jsonString = ((System.Text.Json.JsonElement)model).GetRawText();
                var data = JsonConvert.DeserializeObject<dynamic>(model.ToString());
                var jsonData = JsonConvert.SerializeObject(data);

                string strSql = string.Empty;
                var byteProofJson = Encoding.UTF8.GetBytes(jsonData);

                strSql = "select  * from Client_ModifyAttach where ma_cmcd = '" + userId + "' and ma_field = 'json' and ma_refno = " + refNo;
                DataTable dbTable = objUtility.OpenDataTable(strSql);
                if (dbTable.Rows.Count > 0)
                {
                    strSql = " Update  Client_ModifyAttach set ";
                    strSql += " ma_proof = @proofJson,";
                    strSql += " mkrdt = '" + todayDate.ToString("yyyyMMdd") + "',";
                    strSql += " mkrtm = '" + todayDate.ToString("HH:mm:ss") + "',";
                    strSql += " ma_status = '" + fieldStatus + "' ";
                    strSql += " Where ma_cmcd = '" + userId + "' and ma_field = 'json' and ma_refno = " + refNo + " ;";
                }
                else
                {
                    strSql = " insert into Client_ModifyAttach (ma_cmcd, ma_date, ma_filename, ma_proof, ma_field, mkrdt, mkrtm, ma_refno, ma_Nfiller1, ma_status)";
                    strSql += " values ('" + userId.ToUpper() + "', '" + todayDate.ToString("yyyyMMdd") + "', 'form.json', @proofJson,";
                    strSql += " 'json', '" + todayDate.ToString("yyyyMMdd") + "', '" + todayDate.ToString("HH:mm:ss") + "'," + refNo + ",1, 'N' )";
                }
                Dictionary<string, byte[]> sqlParams = new Dictionary<string, byte[]>();
                sqlParams.Add("@proofJson", byteProofJson);
                objUtility.ExecuteSQL(strSql, sqlParams);
                return "Data updated successfully";
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic AddEsignPdf(string userId, byte[] pdfFile, string fileName, string filedName, string refNo)
        {
