        public dynamic RekycCheckerFullContent(string ClientCode, string refNo)
        {
            string strSql = "select ca_Srno SrNo, ca_cmcd ClientCode, ca_field Field, ca_desc Description, ca_oldValue OldValue, ";
            strSql += " ca_newValue NewValue, ca_date Date, ca_time Time, ca_Nfiller1 NFiller1, ca_Nfiller3 NFiller3,cm_name ClientName , ca_filler3 Filler3 ";
            strSql += " from Client_ModifyAPI Inner Join  Client_Master ON Client_ModifyAPI.ca_cmcd = Client_Master.cm_cd ";
            strSql += " where ca_Tplus = 'N' and ca_cmcd = '" + ClientCode + "' and ca_Nfiller3 = '" + refNo + "' order by Left(ca_field,3) , ca_Nfiller1, ca_filler3, Srno desc";
            var dbTable = objUtility.OpenDataTable(strSql);
            List<RekycCheckerDto> rekycCheckerDto = CommonExtensions.ConvertToList<RekycCheckerDto>(dbTable);
            List<RekycCheckerModel> rekycChecker = new List<RekycCheckerModel>();
            var rekycMakergroup = rekycCheckerDto.GroupBy(x => x.ClientCode.ToUpper());
            foreach (var item in rekycMakergroup)
            {
                RekycCheckerModel rChecker = new RekycCheckerModel();
                string incomeOld = "", incomeNew = "", incomeDateNew = "", incomeDateOld = "";
                incomeOld = objUtility.ReturnIncomeString(item?.FirstOrDefault(x => x.Field == "cm_grossincome")?.OldValue);
                incomeNew = objUtility.ReturnIncomeString(item?.FirstOrDefault(x => x.Field == "cm_grossincome")?.NewValue);

                incomeDateNew = item?.FirstOrDefault(x => x.Field == "cm_grossincomedt")?.NewValue ?? "";
                incomeDateOld = item?.FirstOrDefault(x => x.Field == "cm_grossincomedt")?.OldValue ?? "";
                incomeDateNew = incomeDateNew.Trim() == "" ? "" : DateTime.ParseExact(incomeDateNew, "yyyyMMdd", CultureInfo.InvariantCulture).ToString("dd/MM/yyyy");
                incomeDateOld = incomeDateOld.Trim() == "" ? "" : DateTime.ParseExact(incomeDateOld, "yyyyMMdd", CultureInfo.InvariantCulture).ToString("dd/MM/yyyy");
                #region Personal Details
                rChecker.Personal_Detail = new RekycPersonal()
                {
                    ClientCode = item.Key,
                    Request_Ref_No = item.FirstOrDefault().NFiller3.ToString(),
                    ClientName = item?.FirstOrDefault()?.ClientName ?? "",
                    CorrAddressNew1 = item?.FirstOrDefault(x => x.Field == "cm_add1")?.NewValue ?? "",
                    CorrAddressOld1 = item?.FirstOrDefault(x => x.Field == "cm_add1")?.OldValue ?? "",
                    CorrAddressNew2 = item?.FirstOrDefault(x => x.Field == "cm_add2")?.NewValue ?? "",
                    CorrAddressOld2 = item?.FirstOrDefault(x => x.Field == "cm_add2")?.OldValue ?? "",
                    CorrAddressNew3 = item?.FirstOrDefault(x => x.Field == "cm_add3")?.NewValue ?? "",
                    CorrAddressOld3 = item?.FirstOrDefault(x => x.Field == "cm_add3")?.OldValue ?? "",
                    CorrCityNew = item?.FirstOrDefault(x => x.Field == "cm_add4")?.NewValue ?? "",
                    CorrCityOld = item?.FirstOrDefault(x => x.Field == "cm_add4")?.OldValue ?? "",
                    CorrPincodeNew = item?.FirstOrDefault(x => x.Field == "cm_pincode")?.NewValue ?? "",
                    CorrPincodeOld = item?.FirstOrDefault(x => x.Field == "cm_pincode")?.OldValue ?? "",
                    CorrCountryNew = item?.FirstOrDefault(x => x.Field == "cm_country")?.NewValue ?? "",
                    CorrCountryOld = item?.FirstOrDefault(x => x.Field == "cm_country")?.OldValue ?? "",
                    CorrStateNew = item?.FirstOrDefault(x => x.Field == "cm_state")?.NewValue ?? "",
                    CorrStateOld = item?.FirstOrDefault(x => x.Field == "cm_state")?.OldValue ?? "",
                    EmailNew = item?.FirstOrDefault(x => x.Field == "cm_email")?.NewValue ?? "",
                    EmailRelation = item?.FirstOrDefault(x => x.Field == "cc_EmailRelation")?.NewValue ?? "",
                    EmailOld = item?.FirstOrDefault(x => x.Field == "cm_email")?.OldValue ?? "",
                    MobileNew = item?.FirstOrDefault(x => x.Field == "cm_mobile")?.NewValue ?? "",
                    MobileOld = item?.FirstOrDefault(x => x.Field == "cm_mobile")?.OldValue ?? "",
                    MobileRelation = item?.FirstOrDefault(x => x.Field == "cc_MobileRelation")?.NewValue ?? "",
                    IncomeNew = incomeNew,
                    IncomeOld = incomeOld,
                    IncomeDateNew = incomeDateNew,
                    IncomeDateOld = incomeDateOld,
                };
                #endregion

                #region Personal Details Attachments
                string strQuery = "select ma_srno SrNo, ma_cmcd ClientCode, ma_date Date, ma_filename FileName, ma_proof Proof, ma_field Field, mkrdt MkrDate, mkrtm MkrTime ,ma_Nfiller1 Nfiller  from Client_ModifyAttach where ma_cmcd = '" + item.Key + "' and ma_refNo = " + refNo + " And ma_field like '%attach%' order by ma_srno desc";
                var dbAttachment = objUtility.OpenDataTable(strQuery);
                List<PersonalAttachmentDto> tempPersonalAttachment = new List<PersonalAttachmentDto>();
                for (int q = 0; q < dbAttachment.Rows.Count; q++)
                {
                    PersonalAttachmentDto personalAttachmentdto = new PersonalAttachmentDto()
                    {
                        SrNo = dbAttachment.Rows[q]["SrNo"].ToLong(),
                        ClientCode = dbAttachment.Rows[q]["ClientCode"].ToString(),
                        Date = dbAttachment.Rows[q]["Date"].ToString(),
                        Field = dbAttachment.Rows[q]["Field"].ToString(),
                        FileName = dbAttachment.Rows[q]["FileName"].ToString(),
                        MkrDate = dbAttachment.Rows[q]["MkrDate"].ToString(),
                        MkrTime = dbAttachment.Rows[q]["MkrTime"].ToString(),
                        Nfiller = dbAttachment.Rows[q]["Nfiller"].ToString(),
                        Proof = Encoding.UTF8.GetString((byte[])dbAttachment.Rows[q]["Proof"]).ToString(),
                    };
                    tempPersonalAttachment.Add(personalAttachmentdto);
                }
                rChecker.Personal_Detail.AddressAttachment = tempPersonalAttachment?.OrderByDescending(x => x.SrNo)?.FirstOrDefault(x => x.Field == "AddressAttachment")?.Proof ?? "";
                rChecker.Personal_Detail.AddressAttachmentType = tempPersonalAttachment?.OrderByDescending(x => x.SrNo)?.FirstOrDefault(x => x.Field == "AddressAttachment")?.FileName ?? "";
                rChecker.Personal_Detail.IncomeAttachment = tempPersonalAttachment?.OrderByDescending(x => x.SrNo)?.FirstOrDefault(x => x.Field == "IncomeAttachment")?.Proof ?? "";
                #endregion

                #region Nominee Details
                List<RekycCheckerDto> commonRekycMaker = item.Where(x => x.Field.Substring(0, 3).ToLower() == "cn_" && (x.Filler3 == "1" || x.Filler3 == "3" || x.Filler3 == "5")).ToList();
                List<RekycNominee> reKycNominee = new List<RekycNominee>();
                var nomineeGroup = commonRekycMaker?.OrderBy(x => x.NFiller1)?.GroupBy(x => x.NFiller1);
                int nomId = 1;
                foreach (var nomineeItem in nomineeGroup)
                {
                    string nomDobNew = "", nomDobOld = "", grdDobNew = "", grdDobOld = "";
                    nomDobNew = nomineeItem?.FirstOrDefault(x => x.Field == "cn_dob")?.NewValue ?? "";
                    nomDobOld = nomineeItem?.FirstOrDefault(x => x.Field == "cn_dob")?.OldValue ?? "";
                    nomDobNew = nomDobNew.Trim() == "" ? "" : DateTime.ParseExact(nomDobNew, "yyyyMMdd", CultureInfo.InvariantCulture).ToString("dd/MM/yyyy");
                    nomDobOld = nomDobOld.Trim() == "" ? "" : DateTime.ParseExact(nomDobOld, "yyyyMMdd", CultureInfo.InvariantCulture).ToString("dd/MM/yyyy");

                    int nomGrdVal = Convert.ToInt32(nomineeItem?.FirstOrDefault(x => x.Field == "cn_firstname")?.Filler3) + 1;
                    List<RekycCheckerDto> grdObject = item.Where(x => x.Field.Substring(0, 3).ToLower() == "cn_" && x.Filler3 == nomGrdVal.ToString()).ToList();
                    var grdGroup = grdObject?.OrderBy(x => x.NFiller1)?.GroupBy(x => x.NFiller1);
                    RekycGuardian grdModl = new RekycGuardian();
                    foreach (var grdItem in grdGroup)
                    {
                        string panUidNew = grdItem?.FirstOrDefault(x => x.Field == "cn_pan")?.NewValue ?? "";
                        panUidNew = panUidNew == "" ? grdItem?.FirstOrDefault(x => x.Field == "cn_uid")?.NewValue ?? "" : panUidNew;
                        string panUidOld = grdItem?.FirstOrDefault(x => x.Field == "cn_pan")?.OldValue ?? "";
                        panUidOld = panUidOld == "" ? grdItem?.FirstOrDefault(x => x.Field == "cn_uid")?.OldValue ?? "" : panUidOld;
                        grdDobNew = grdItem?.FirstOrDefault(x => x.Field == "cn_dob")?.NewValue ?? "";
                        grdDobOld = grdItem?.FirstOrDefault(x => x.Field == "cn_dob")?.OldValue ?? "";
                        grdDobNew = grdDobNew == "" ? "" : DateTime.ParseExact(grdDobNew, "yyyyMMdd", CultureInfo.InvariantCulture).ToString("dd/MM/yyyy");
                        grdDobOld = grdDobOld == "" ? "" : DateTime.ParseExact(grdDobOld, "yyyyMMdd", CultureInfo.InvariantCulture).ToString("dd/MM/yyyy");
                        grdModl.NomGuardianDobNew = grdDobNew;
