        public dynamic RekycApprove(string loginUser, RekycApprovePost model, string compCode)
        {
            try
            {
                SqlParameter[] sqlPrm = new[]
                {
                        new SqlParameter("@i_vcClient_Code",model.ClientCode),
                        new SqlParameter("@i_vcRefNo",model.RefNo),
                        new SqlParameter("@i_vcApprovalFlag",model.Status),
                        new SqlParameter("@i_vcApprovalReason",model.Reason)
                     };
                List<OutputParamSP> spModelList = new List<OutputParamSP>();
                OutputParamSP spModel = new OutputParamSP();
                spModel.ParamValue = "@o_vcErrorFlag";
                spModel.DbType = SqlDbType.VarChar;
                spModel.Length = 1;
                spModelList.Add(spModel);
                spModel = new OutputParamSP();
                spModel.ParamValue = "@o_vcErrorMessage";
                spModel.DbType = SqlDbType.VarChar;
                spModel.Length = 500;
                spModelList.Add(spModel);
                spModel = new OutputParamSP();
                spModel.ParamValue = "@o_vcJsonOutput";
                spModel.DbType = SqlDbType.NVarChar;
                spModel.Length = 4000;
                spModelList.Add(spModel);
                var respSP = objUtility.Execute_SP_OuputParam("SP_ReKyc_CheckerApprove", sqlPrm, spModelList);

                return respSP;

            }
            catch (Exception ex)
            {
                return "Error in Process : Approve/Reject Data " + Environment.NewLine + "Error :" + ex.Message.ToString();
            }
        }

