            if (string.IsNullOrWhiteSpace(crossConnection))
            {
                return false;
            }
            var arrCrossCon = crossConnection.Split('/');
            var strConnection = $"server={arrCrossCon[0].Replace("[", "").Replace("]", "")};Database={arrCrossCon[1].Replace("[", "").Replace("]", "")};Uid={arrCrossCon[3].Replace("[", "").Replace("]", "")};Pwd={arrCrossCon[4].Replace("[", "").Replace("]", "")};Max Pool Size=200;Connect Timeout=20000;pooling='true';";
            SqlTransaction objTransTplus = null;

            try
            {
                using (SqlConnection ObjConnection = new SqlConnection(strConnection))
                {
                    string strNewValue = string.Empty;
                    string strOldValue = string.Empty;
                    string strField = string.Empty;
                    string strFieldDesc = string.Empty;
