        public string GetAccountCode(string accType)
        {
            string result = string.Empty;
            switch (accType.ToUpper())
            {
                case "SB":
                    result = "10";
                    break;
                case "CB":
                    result = "11";
                    break;
                case "CC":
                    result = "12";
                    break;
                default:
                    result = "";
                    break;
            }

            return result;
        }

