        public dynamic XMLCommonSPCall(string strXML, string procedureName)
        {
            string connetionString = objUtility.GetConnectionStr();
            DataSet ds = new DataSet();
            using (SqlConnection conn = new SqlConnection(connetionString))
            {
                using (SqlCommand cmd = new SqlCommand(procedureName))
                {
                    cmd.CommandType = CommandType.StoredProcedure;
                    if (conn.State == ConnectionState.Closed)
                        conn.Open();
                    cmd.Connection = conn;
                    cmd.CommandTimeout = 0;
                    cmd.Parameters.Add(new SqlParameter("@dsXml", SqlDbType.VarChar));
                    cmd.Parameters["@dsXml"].Value = strXML;
                    SqlDataAdapter adap = new SqlDataAdapter
                    {
                        SelectCommand = cmd
                    };
                    try
                    {
                        adap.Fill(ds);
                        cmd.ExecuteNonQuery();
                        return ds;
                    }
                    catch (Exception ex)
                    {
                        throw ex;
                    }
                }
            }
        }
        public string UploadPdfForEsignSetu(string refNo, string pdfBase64, string identifierMobileNo, string DispName, string yob, string esignRedirectUrl, string fileName, string clientCode, string modulName)
        {
            try
            {
                string esignReqId = string.Empty;
                string vendor = "SETU";
                #region upload file for esign
                var jsonObj = new
                {
                    ClientCode = clientCode,
                    base64 = pdfBase64,
                    FileName = fileName,
                    FilePassword = ""
                };
                var jsonParams = JsonConvert.SerializeObject(jsonObj);
                try
                {
                    var resp = _modelTRadeWeb.CallSetuProcedure(vendor, "EsignRequest", modulName, jsonParams, refNo);
                    //var parseJson = JObject.Parse(resp);
                    esignReqId = Convert.ToString(resp["id"]);
                    refNo = ReKYC_MasterTable(clientCode, "Pending", "N", 3, "Call Esign for upload " + modulName + " pdf for Request Id: " + esignReqId, modulName);
                }
                catch (Exception ex)
                {
                    return "Issue while uploading " + modulName + " pdf on setu server \\n " + ex.Message.ToString();
                }

                #endregion

                #region Create signature for esign
                var baseString = Convert.FromBase64String(pdfBase64);
                PdfReader reader1 = new PdfReader(baseString); // or file path
                int countPage = reader1.NumberOfPages;
                reader1.Close();
                var jsonSignerObj = new
                {
                    ClientCode = clientCode,
                    Requestid = esignReqId,
                    redirectUrl = esignRedirectUrl,
                    identifier = identifierMobileNo,
                    displayName = DispName,
                    height = "60",
                    onPages = countPage,
                    position = "bottom-right",
                    width = "180",
                    birthYear = yob
                };
                var jsonVal = JsonConvert.SerializeObject(jsonSignerObj);
                try
                {
                    var getSigner = _modelTRadeWeb.CallSetuProcedure(vendor, "CreateSign", modulName, jsonVal, refNo);
                    string signerUrl = "";
                    try
                    {
                        if (getSigner["ResponseFlag"] == "E")
                        {
                            return modulName + " pdf uploaded on setu, Please submit again to get pdf and Esign url. \\n " + getSigner["ResponseMessage"];
                        }
                        signerUrl = Convert.ToString(getSigner["signers"][0]["url"]);
                        var serlzJson = JsonConvert.SerializeObject(getSigner);
                        refNo = ReKYC_MasterTable(clientCode, "Pending", "N", 4, modulName + " PDF uploaded on setu, Pending for Esign (Request Id:" + esignReqId, modulName);
                        byte[] getJsonBytes = Encoding.UTF8.GetBytes(serlzJson);
                        var result = AddEsignPdf(clientCode, getJsonBytes, "EsignRequest", modulName + " Esign Request Output for Request Id", refNo);
                        return signerUrl;
                    }
                    catch (Exception e)
                    {
                        return modulName + " pdf uploaded on setu, Please submit again to get pdf and Esign url. \\n " + e.Message.ToString();
                    }
                }
                catch (WebException exception)
                {
                    string responseText = string.Empty;

                    var responseStream = exception.Response?.GetResponseStream();

                    if (responseStream != null)
                    {
                        using (var reader = new StreamReader(responseStream))
                        {
                            responseText = reader.ReadToEnd();
                        }
                    }
                    return responseText;
                }
                #endregion
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        public dynamic SendOTPcommon(string userId, EmailSmsReqModel reqObject)
        {
            DataTable dt = objUtility.OpenDataTable($"select cm_mobile,cm_email from client_master where cm_cd='{userId}';");
            string reqType = reqObject.reqestName.ToUpper();
            string strMessage = string.Empty;

            if (dt.Rows.Count > 0)
            {
                var jsonString = ((System.Text.Json.JsonElement)reqObject.requestObject).GetRawText();
                var jsonObject = JsonConvert.DeserializeObject<dynamic>(jsonString.ToString());

                string mode = jsonObject["mode"].ToString().ToUpper();
                string strMobile = jsonObject["MobileNo"].ToString().Trim();
                string strEmailTo = jsonObject["EmailId"].ToString().Trim();

                string chars1 = "1234567890";
                char[] stringChars1 = new char[4];

                Random random1 = new Random();
                for (int i = 0; i < stringChars1.Length; i++)
                {
                    stringChars1[i] = chars1[random1.Next(chars1.Length)];
                }
                string strOTP = new String(stringChars1);
                string strMsgTxt = string.Empty, Strsql = "";
                if (Convert.ToInt16(objUtility.fnFireQueryTradeWeb("Sysparameter", "count(0)", "sp_parmcd", "SMSCLMMO", true)) > 0)
                {
                    strMsgTxt = objUtility.fnFireQueryTradeWeb("sysparameter", "SP_SYSVALUE", "sp_parmcd", "SMSCLMMO", true);
                }
                else
                {
                    strMsgTxt = "Your OTP to initiate Mobile/Email/Gross Income change request for <Client> is <OTP>";
                }
                strMsgTxt = strMsgTxt.Replace("<Client>", userId);
                strMsgTxt = strMsgTxt.Replace("<OTP>", strOTP);

                if (strMsgTxt.ToUpper().Contains("<EMAIL ID/MOBILE NUMBER/INCOME>") == true)
                {
                    List<string> lstTag = new List<string> { };
                    if (reqType == "Email")
                    {
                        lstTag.Add("Email ID");
                    }
                    else if (reqType == "Mobile")
                    {
                        lstTag.Add("Mobile number");
                    }
                    else if (reqType == "Income")
                    {
                        lstTag.Add("Income");
                    }
                    string strTag = String.Join("/", lstTag.ToArray());
                    strMsgTxt = strMsgTxt.Replace("<Email ID/Mobile number/Income>", strTag);
                }
                strMsgTxt = strMsgTxt.Replace("<&>", "<~>");
                strMsgTxt = strMsgTxt.Replace("&", "");
                strMsgTxt = strMsgTxt.Replace("<~>", "&");

                if (reqType == "MOBILE")
                {
                    string strMobileNo = strMobile;
                    string[] strSMSParamVal = new string[5];
                    string strSMSParameter = "SMSUSERID/SMSPWD/SMSSENDER/SMSLENGTH/SMSLINK";
                    string strvalue = string.Empty;
                    string strFromNo1 = "";
                    string strFromNo2 = "";

                    for (int i = 0; i <= 4; i++)
                    {
                        strvalue = strSMSParameter.Split('/')[i];
                        strSMSParamVal[i] = objUtility.fnFireQueryTradeWeb("sysparameter", "SP_SYSVALUE", "sp_parmcd", strvalue, true);
                    }
                    string strURLLink = strSMSParamVal[4];

                    if (strURLLink.IndexOf("<USERID>") != -1 && strSMSParamVal[0].Trim() != "")
                    {
                        strURLLink = strURLLink.Replace("<USERID>", strSMSParamVal[0].Trim());
                    }
                    if (strURLLink.IndexOf("<PASSWORD>") != -1 && strSMSParamVal[1].Trim() != "")
                    {
                        strURLLink = strURLLink.Replace("<PASSWORD>", strSMSParamVal[1].Trim());
                    }
                    if (strSMSParamVal[2].Trim() == "")
                    {
                        if (strURLLink.IndexOf("<SENDERID>") != -1)
                        {
                            strURLLink = strURLLink.Replace("<SENDERID>", strSMSParamVal[2].Trim());
                        }
                    }
                    else
                    {
                        strFromNo1 = strSMSParamVal[2].Trim();
                        if (strFromNo1.IndexOf("|") != -1)
                        {
                            strFromNo2 = strFromNo1.Split('|')[1];
                            strFromNo1 = strFromNo1.Split('|')[0];
                        }
                        else
                        {
                            strFromNo1 = Strings.Left(strFromNo1.Trim(), 10);
                            strFromNo2 = "";
                        }
                        if (strURLLink.IndexOf("<SENDERID>") != -1)
                        {
                            strURLLink = strURLLink.Replace("<SENDERID>", strSMSParamVal[2].Trim());
                        }
                        else if (strURLLink.IndexOf("<SENDERID1>") != -1 || strURLLink.IndexOf("<SENDERID2>") != -1)
                        {
                            strURLLink = strURLLink.Replace("<SENDERID1>", strFromNo1).Replace("<SENDERID2>", strFromNo2);
                        }
                    }
                    strURLLink = strURLLink.Replace("<MESSAGE>", strMsgTxt);

                    if (strURLLink.IndexOf("/opted.smsapi.org/v1.0.7/") != -1)
                    {
                        strURLLink = strURLLink.Replace("<MESSAGE>", strMsgTxt);
                    }

                    if (strURLLink.IndexOf("/174.143.34.193/") != -1)
                    {
                        if (strMsgTxt.Trim().Length > 160)
                        {
                            strURLLink = strURLLink + "&mt=4";
                        }
                        else
                        {
                            strURLLink = strURLLink + "&mt=0";
                        }
                        strURLLink = strURLLink + "&typeofmessage=1";
                    }

                    if (objUtility.GetSysParmSt("SMSCOUNTRYCD", "") == "Y")
                    {
                        if (strMobileNo.Trim().Length == 10)
                        {
                            strMobileNo = "91" + strMobileNo;
                        }
                    }
                    else
                    {
                        if (strMobileNo.Trim().Length > 10)
                        {
                            strMobileNo = Strings.Right(strMobileNo.Trim(), 10);
                        }
                    }
                    strURLLink = strURLLink.Replace("<CLIENTMOBILE>", strMobileNo.Trim());

                    if (strURLLink.IndexOf("myvaluefirst.com") != -1)
                    {
                        string strSENDER = "";
                        if (strSMSParamVal[2].Trim().IndexOf("|") != -1)
                        {
                            if (Strings.Left(strMobileNo.Trim(), 2) == "92" || Strings.Left(strMobileNo.Trim(), 2) == "93")
                            {
                                strSENDER = strSMSParamVal[2].Trim().Split('|')[1];
                            }
                            else
                            {
                                strSENDER = strSMSParamVal[2].Trim().Split('|')[0];
                            }
                        }
                        else
                        {
                            strSENDER = Strings.Left(strSMSParamVal[2].Trim(), 10);
                        }
                        strURLLink = strURLLink.Replace("<SENDERID3>", strSENDER);
                    }
                    if (objUtility.GetWebParameter("SECURITYPROT").Trim() == "TLS12")
                    {
                        ServicePointManager.SecurityProtocol = (SecurityProtocolType)192 | (SecurityProtocolType)768 | (SecurityProtocolType)3072 | (SecurityProtocolType)48;
                    }
                    HttpWebRequest http = (HttpWebRequest)WebRequest.Create(strURLLink);
                    HttpWebResponse response = (HttpWebResponse)http.GetResponse();
                    StreamReader sr = new StreamReader(response.GetResponseStream());
                    string content = sr.ReadToEnd();
                    string strresponse = content;
                    sr.Close();
                    response.Close();

                    if (response.StatusCode == HttpStatusCode.OK)
                    {
                        strresponse = "SMS Sent Successfully.";
                    }
                    else if (content.IndexOf("<ERROR>") != -1)
                    {
                        if (content.IndexOf("<DESC>") != -1)
                        {
                            strresponse = Strings.Mid(content, Strings.InStr(1, content, "<DESC>", CompareMethod.Text) + 6);
                            strresponse = Strings.Left(content, Strings.InStr(1, content, "</DESC>", CompareMethod.Text) - 1);
                        }
                        else
                        {
                            strresponse = "SMS Sent Successfully.";
                        }
                    }
                    else if (content.IndexOf("\"\"error-status\"\":\"\"Success\"\"") != -1)
                    {
                        strresponse = "SMS Sent Successfully.";
                    }
                    else if (content.IndexOf(strMobileNo.Trim()) != -1)
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else if (content.IndexOf("<sms>") != -1)
                    {
                        if (content.IndexOf("-1") != -1)
                        {
                            strresponse = "Message Sending Failed";
                        }
                        else if (content.ToUpper().IndexOf("INVALID USERNAME OR PASSWORD") != -1)
                        {
                            strresponse = "Sending Failed. Invalid Username Or Password.";
                        }
                        else
                        {
                            strresponse = "Message Send Successfully.";
                        }
                    }
                    else if (content.IndexOf("Fail") != -1)
                    {
                        strresponse = "Message Sending Failed";
                    }
                    else if (content.ToUpper().IndexOf("INVALID USERNAME OR PASSWORD") != -1 || content.ToUpper().IndexOf("INVALID USERNAME AND PASSWORD") != -1)
                    {
                        strresponse = "Message Sending Failed. Invalid Username Or Password.";
                    }
                    else if (content.ToUpper().IndexOf("1701|") != -1 || content.ToUpper().IndexOf("SUCCESS") != -1)
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else if (content == "100")
                    {
                        strresponse = "Message Send Successfully.";
                    }
                    else if (content.ToUpper().IndexOf(":") != -1)
                    {
                        if (content.ToUpper().Split(':')[1] == "")
                        {
                            strresponse = content;
                        }
                        else
                        {
                            strresponse = "Message Send Successfully.";
                        }
                    }
                    else
                    {
                        strresponse = content;
                    }

                    Strsql = "Insert into sms_Logs values(";
                    Strsql += "'" + userId + "','" + strMobileNo + "','" + strMsgTxt + "',";
                    Strsql += "'" + strresponse.Replace("'", " ") + "','" + userId + "','" + DateTime.Now.ToString("yyyyMMdd") + "','" + DateTime.Now.ToString("HH:mm:ss") + "')";
                    objUtility.ExecuteSQL(Strsql);
                }

                if (reqType == "EMAIL")
                {
                    if (objUtility.GetWebParameter("SMTPSERVER").Trim() != "" && strEmailTo != "")
                    {
                        try
                        {
                            string strHost = string.Empty;
                            int intPort;
                            string strUserID = string.Empty;
                            string strPWD = string.Empty;
                            string strEmail = string.Empty;
                            string strSSL = string.Empty;
                            string strSMTPParamVal = objUtility.GetWebParameter("SMTPSERVER");
                            string strEmailID = strEmailTo;

                            strHost = strSMTPParamVal.Split('/')[0];
                            intPort = Convert.ToInt32(strSMTPParamVal.Split('/')[1]);
                            strUserID = strSMTPParamVal.Split('/')[2];
                            strPWD = strSMTPParamVal.Split('/')[3];
                            strEmail = strSMTPParamVal.Split('/')[4];
                            strSSL = strSMTPParamVal.Split('/')[5];

                            MailMessage Msg = new MailMessage();

                            Msg.From = new MailAddress(strEmail);
                            Msg.To.Add(strEmailID);
                            Msg.Subject = "Change Request OTP For Client " + userId;
                            Msg.Body = strMsgTxt;
                            Msg.IsBodyHtml = true;
                            SmtpClient smtp = new SmtpClient();
                            smtp.Host = strHost;
                            smtp.Port = intPort;
                            smtp.Credentials = new System.Net.NetworkCredential(strUserID, strPWD);
                            smtp.EnableSsl = strSSL == "N" ? false : true;
                            System.Net.ServicePointManager.ServerCertificateValidationCallback = delegate (object s,
                            System.Security.Cryptography.X509Certificates.X509Certificate certificate,
                            System.Security.Cryptography.X509Certificates.X509Chain chain,
                            System.Net.Security.SslPolicyErrors sslPolicyErrors)
                            {
                                return true;
                            };
                            smtp.Send(Msg);
                            Strsql = "Insert into sms_Logs values(";
                            Strsql += "'" + userId + "','" + strEmailTo + "','" + strMsgTxt + "',";
                            Strsql += "'OTP sent to your email','" + userId + "','" + DateTime.Now.ToString("yyyyMMdd") + "','" + DateTime.Now.ToString("HH:mm:ss") + "')";
                            objUtility.ExecuteSQL(Strsql);
                        }
                        catch (Exception)
                        {
                            return "Unable to send Email";
                        }
                    }
                }

                ///// Insert record in OTP_Master table 
                if (reqType == "MOBILE")
                {
                    Strsql = "insert into OTP_Master values('" + userId.ToUpper() + "', 'MO', '" + strOTP.Trim() + "','" + strMobile.Trim() + "', '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "', '" + objUtility.dtos(System.DateTime.Today.Date.AddMinutes(30).ToString()) + "','" + DateTime.Now.AddMinutes(30).ToString("HH:mm:ss") + "','P','TradeWeb', 'RKC','','','',0,0,0 )";
                    objUtility.ExecuteSQL(Strsql);
                }
                else if (reqType == "EMAIL")
                {
                    Strsql = "insert into OTP_Master values('" + userId.ToUpper() + "', 'EI', '" + strOTP.Trim() + "','" + strEmailTo.Trim() + "', '" + objUtility.dtos(System.DateTime.Today.Date.ToString()) + "'  , '" + DateTime.Now.ToString("HH:mm:ss") + "', '" + objUtility.dtos(System.DateTime.Today.Date.AddMinutes(30).ToString()) + "','" + DateTime.Now.AddMinutes(30).ToString("HH:mm:ss") + "','P','TradeWeb', 'RKC','','','',0,0,0 )";
                    objUtility.ExecuteSQL(Strsql);
                }

                if (mode == "MOBILE" || mode == "NEWMOBILE")
                {
                    strMessage = "OTP sent to " + (mode == "MOBILE" ? "Mobile" : "new Mobile");
                }
                else if (mode == "EMAIL" || mode == "NEWEMAIL")
                {
                    strMessage = "OTP sent to " + (mode == "EMAIL" ? "Email" : "new Email");
                }
            }
            return strMessage;
        }


        public dynamic UpdatePasswordFP(string userId, string otp, string newPassword)
        {
            VerifyOtpResponseFP resModel = new VerifyOtpResponseFP();
            resModel.status = "failed";
            resModel.redirectLogin = false;
            try
            {
                string Strsql = "Select * from Client_master where cm_cd = '" + userId.Trim() + "'";
                DataTable dt = objUtility.OpenDataTable(Strsql);
                string mobileNo = "", emailId = "";
                if (dt.Rows.Count > 0)
                {
                    mobileNo = dt.Rows[0]["cm_mobile"].ToString().Trim();
                    emailId = dt.Rows[0]["cm_email"].ToString().Trim();
                }
                else
                {
                    resModel.redirectLogin = true;
                    resModel.message = "Mobile Number is not available";
                    return resModel;
                }

                /////// ***** Check validation ****
                if (_configuration["IsTradeWeb"] == "O")
                {
                    string validation = objUtility.CheckPasswordCondition(newPassword, "", userId);
                    if (validation != "")
                    {
                        resModel.message = validation;
                        return resModel;
                    }
                }
                //////// ****** Verify OTP ****
                string verifyOtp = objUtility.VerifyOtp_OtpMaster(userId, otp, mobileNo + emailId, "FP", "TradeWeb");
                if (!verifyOtp.Contains("success"))
                {
                    resModel.redirectLogin = true;
                    if (verifyOtp == "OTP Mismatched")
                    {
                        resModel.redirectLogin = false;
                    }
                    resModel.message = verifyOtp;
                    return resModel;
                }
                /////// ***** update password ****
                Strsql = "select cm_cd,cm_pwd from client_master where cm_cd='" + userId + "'";
                DataSet ObjDsPwd = new DataSet();
                ObjDsPwd = objUtility.OpenDataSet(Strsql);
                if (ObjDsPwd.Tables[0].Rows.Count > 0)
                {
                    bool blnEncPwd = objUtility.GetWebParameter("TWEBENCPWD").Trim() == "Y";

                    Strsql = " update Client_master set cm_pwd='" + (blnEncPwd ? objUtility.Encrypt(newPassword) : newPassword) + "' where cm_cd='" + userId + "'";
                    objUtility.ExecuteSQL(Strsql);

                    objUtility.AfterChangePasswordTblEntry(newPassword, "", userId);

                    resModel.redirectLogin = true;
                    resModel.status = "success";
                    resModel.message = "Password has been changed successfully!";
                    return resModel;
                }
                return resModel;
            }
            catch (Exception ex)
            {
                resModel.message = ex.Message.ToString();
                return resModel;
            }
        }

        public dynamic CompileTypst(string ReportName, string ReportDisplayName, DataSet dts, string pdfType)
        {
            byte[] fileBytes = new byte[] { };
            var pdfResponses = new List<PDFResponse> { };
            string strJSONPath = "";
            string strPDFPath = "", baseDir = "", strJSON = "";
            try
            {
                Guid id = Guid.NewGuid();
                string uniquename = "" + id;
                string strJSONRelPath = "";
                string strTypstCommand = "", minorJson = "";
                baseDir = AppDomain.CurrentDomain.BaseDirectory + "Typst";
                string strTypstExePath = Path.Combine(baseDir, "typst.exe");
                string strInputPath = Path.Combine(baseDir, "Inputs");
                string strOutputPath = Path.Combine(baseDir, "Outputs");

                if (dts == null || dts.Tables.Count == 0)
                    return CreateEmptyResultTable();

                if (dts.Tables[0].Rows.Count == 0)
                    return CreateEmptyResultTable();

                string clientCode = "";

                strJSON = JsonConvert.SerializeObject(dts, Formatting.Indented);

                objUtility.TypstCreateCompanyLogo(baseDir);

                if (!Directory.Exists(strInputPath))
                    Directory.CreateDirectory(strInputPath);

                if (!Directory.Exists(strOutputPath))
                    Directory.CreateDirectory(strOutputPath);

                /////////// *** Please comment below two lines before build release ***** (For debug code)
                //string jsonfilePath = Path.Combine(baseDir, "inputs", "Test_Json.json").Replace("\\", "/");  // HH
                //strJSON = File.ReadAllText(jsonfilePath); // HH
                if (ReportDisplayName == "MTFSummary")
                    ReportDisplayName = "MTF_Status_Detail";

                strPDFPath = Path.Combine(strOutputPath, ReportName + "_" + uniquename + ".pdf");

                strJSONRelPath = Path.Combine("..", "Inputs", ReportName + "_" + uniquename + ".json").Replace("\\", "/");

                if (pdfType == "KRAPDF")
                {
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", "TypstKRA.typ") + "\"" + "  " + "\"" + strPDFPath + "\"";
                    strJSON = dts.Tables[0].Rows[0][0].ToString();

                    var desObj = AppendKRAimgTypst(baseDir, strJSON);
                    strJSON = JsonConvert.SerializeObject(desObj);
                }
                else if (pdfType == "FINALPDF")
                {
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", "TypstRekyc.typ") + "\"" + "  " + "\"" + strPDFPath + "\"";
                    strJSON = dts.Tables[0].Rows[0][0].ToString();

                    var desObj = AppendImagePdfTypst(baseDir, strJSON, uniquename);
                    strJSON = JsonConvert.SerializeObject(desObj);
                }
                else if (pdfType == "CLOSUREPDF")
                {
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", "TypstAccountClosure.typ") + "\"" + "  " + "\"" + strPDFPath + "\"";
                    strJSON = dts.Tables[0].Rows[0][0].ToString();

                    var desObj = AppendClosureImgTypst(baseDir, strJSON);
                    strJSON = JsonConvert.SerializeObject(desObj);
                }
                else if (pdfType == "CKYCINDV" || pdfType == "CKYCLE")
                {
                    strJSON = dts.Tables[0].Rows[0][0].ToString(); // HH uncomment
                    string typstFileName = pdfType == "CKYCINDV" ? "TypstCKYC_Individual.typ" : "TypstCKYC_LE.typ";
                    JArray rootArray = JArray.Parse(strJSON);
                    JObject mainObj = (JObject)rootArray[0];
                    var ifRelPersn = mainObj["IfMinor"];
                    if (ifRelPersn != null && ifRelPersn.HasValues)
                    {
                        minorJson = ifRelPersn.ToString();
                        if (minorJson != "")
                        {
                            var jsonObj = JsonConvert.DeserializeObject<dynamic>(minorJson);
                            foreach (var rpJson in jsonObj)
                            {
                                string typstFileNameRelPerson = pdfType == "CKYCINDV" ? "TypstCKYC_Ind_Rel.typ" : "TypstCKYC_LE_Rel.typ";
                                minorJson = JsonConvert.SerializeObject(rpJson);
                                minorJson = "[" + minorJson + "]";
                                var desObjMinor = AppendImagePdfTypst(baseDir, minorJson, uniquename);
                                clientCode = desObjMinor[0]["ClientCode"]?.ToString();
                                minorJson = JsonConvert.SerializeObject(desObjMinor);

                                strTypstCommand = "\"" + Path.Combine(baseDir, "templates", typstFileNameRelPerson) + "\"" + "  " + "\"" + strPDFPath + "\"";
                                strJSONPath = CreateJsonConfig(minorJson, ReportName + "_" + uniquename + ".json");
                                string argumentsMinro = $"compile {strTypstCommand} --input file_path={strJSONRelPath} --root \"{baseDir}\"";
                                try
                                {
                                    fileBytes = CommonTypstPdfPSI(argumentsMinro, strPDFPath, strTypstExePath, strJSONPath);
                                    pdfResponses.Add(new PDFResponse { PDFName = "CKYC_Indv_RelatedPerson_" + clientCode + ".pdf", Base64PDF = Convert.ToBase64String(fileBytes) });
                                }
                                catch (Exception e)
                                { }
                                finally
                                {
                                    DeleteTypstFiles(baseDir, minorJson);
                                }
                            }
                        }
                    }
                    var desObj = AppendImagePdfTypst(baseDir, strJSON, uniquename);
                    strJSON = JsonConvert.SerializeObject(desObj);
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", typstFileName) + "\"" + "  " + "\"" + strPDFPath + "\"";
                }
                else if (pdfType == "CVLKYCINDV")
                {
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", "TypstCVLKYC_Indv.typ") + "\"" + "  " + "\"" + strPDFPath + "\"";
                    strJSON = dts.Tables[0].Rows[0][0].ToString();

                    var desObj = AppendImagePdfTypst(baseDir, strJSON, uniquename);
                    strJSON = JsonConvert.SerializeObject(desObj);

                }
                else if (pdfType.ToUpper() == "ALERTFORINCOMEUPDATION" || pdfType.ToUpper() == "ALERTFORDORMANT")
                {
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", "AlertForIncomeDormant.typ") + "\"" + "  " + "\"" + strPDFPath + "\"";
                }
                else if (pdfType.ToUpper() == "ACCOUNTOPENINGLETTER")
                {
                    strJSON = dts.Tables[0].Rows[0][0].ToString();
                    JArray arr = JArray.Parse(strJSON);
                    if (arr.Count > 0 && arr[0]["Headers"]?.Any() == true)
                        clientCode = arr[0]["Headers"][0]["ClientCode"]?.ToString();

                    if (objUtility.GetWebParameter("ACTOPHDRIMG").Trim() == "Y")
                    {
                        string compCode = arr[0]["Headers"][0]["CompanyCode"]?.ToString();
                        string dirPath = Path.Combine(baseDir, "Assets");
                        string headerImagePath = objUtility.GetCompanyHeaderImageAsync(dirPath, compCode);
                        arr[0]["Headers"][0]["CompHeaderImage"] = headerImagePath;
                    }
                    strJSON = JsonConvert.SerializeObject(arr[0]);
                    ReportDisplayName = "AccountOpeningLetter";
                    strTypstCommand = "\"" + Path.Combine(baseDir, "templates", "AccountOpeningLetter.typ") + "\"" + "  " + "\"" + strPDFPath + "\"";
                }
                else
                {
                    clientCode = dts.Tables[0].Rows[0]["ClientCode"]?.ToString();
                    strTypstCommand = $"\"{Path.Combine(baseDir, "templates", "common.typ")}\" \"{strPDFPath}\"";
                }

                strJSONPath = CreateJsonConfig(strJSON, ReportName + "_" + uniquename + ".json");
                string arguments = $"compile {strTypstCommand} --input file_path={strJSONRelPath} --root \"{baseDir}\"";

                fileBytes = CommonTypstPdfPSI(arguments, strPDFPath, strTypstExePath, strJSONPath);

                if (pdfType == "FINALPDF")
                {
                    AppenePdfAttachmentInFinalPDF(baseDir, strJSON, strPDFPath, ref strOutputPath);
                    fileBytes = new byte[] { };
                    fileBytes = File.ReadAllBytes(strOutputPath);
                }
                pdfResponses.Add(new PDFResponse { PDFName = clientCode.Trim() + "_" + ReportDisplayName.Trim() + ".pdf", Base64PDF = Convert.ToBase64String(fileBytes) });

                DataTable dt = new DataTable();
                dt.Columns.Add("PDFName", typeof(string));
                dt.Columns.Add("Base64PDF", typeof(string));
                dt.Columns.Add("TotalPages", typeof(int));

                foreach (var pdf in pdfResponses)
                {
                    PdfReader reader = new PdfReader(fileBytes); // or file path
                    int pageCount = reader.NumberOfPages;
                    reader.Close();
                    dt.Rows.Add(pdf.PDFName, pdf.Base64PDF, pageCount);
                }
                DataSet dsRes = new DataSet();
                dsRes.Tables.Add(dt);
                dsRes.Tables[0].TableName = "rs0";

                return dsRes;
            }
            catch (Exception ex)
            {
                if (strJSONPath != "" && File.Exists(strJSONPath))
                {
                    File.Delete(strJSONPath);
                }
                throw ex;
            }
            finally
            {
                if (strPDFPath != "" && File.Exists(strPDFPath))
                {
                    File.Delete(strPDFPath);
                }
                if (pdfType == "KRAPDF")
                {
                    DeleteKRATypstFiles(baseDir, strJSON);
                }
                else if (pdfType == "FINALPDF")
                {
                    DeleteTypstFiles(baseDir, strJSON);
                }
                else if (pdfType == "CLOSUREPDF")
                {
                    DeleteClosureTypstFiles(baseDir, strJSON);
                }
            }
        }

