        public dynamic GenerateTypstAccountOpeningJson(string ReportName, string ReportDisplayName, string typstJSON)
        {
            byte[] fileBytes = new byte[] { };
            var pdfResponses = new List<PDFResponse> { };
            string strJSONPath = "";
            string strPDFPath = "", baseDir = "";

            try
            {
                Guid id = Guid.NewGuid();
                string uniquename = "" + id;
                string strJSONRelPath = "";
                string strTypstCommand = "", strHeaderImage = "";
                baseDir = AppDomain.CurrentDomain.BaseDirectory + "Typst";
                string strTypstExePath = Path.Combine(baseDir, "typst.exe");
                string strInputPath = Path.Combine(baseDir, "inputs");
                string strOutputPath = Path.Combine(baseDir, "outputs");

                objUtility.TypstCreateCompanyLogo(baseDir);

                if (!Directory.Exists(strInputPath))
                    Directory.CreateDirectory(strInputPath);

                if (!Directory.Exists(strOutputPath))
                    Directory.CreateDirectory(strOutputPath);

                /////// *** Decalred Global variables

                DataSet dts = new DataSet();
                DataTable dt = new DataTable();
                DataSet dsRes = new DataSet();
                dt.Columns.Add("MessageType", typeof(string));
                dt.Columns.Add("MessageText", typeof(string));

                /////////// *** Please comment below two lines before build release ***** (For debug code)
                //string jsonfilePath = Path.Combine(baseDir, "inputs", "Test_Json.json").Replace("\\", "/");  // HH
                //strJSON = File.ReadAllText(jsonfilePath); // HH

                if (objUtility.GetWebParameter("ACTOPHDRIMG").Trim() == "Y")
                    strHeaderImage = "Y";

                int succesCnt = 0, errorCnt = 0;
                var jsonFullObj = JsonConvert.DeserializeObject<dynamic>(typstJSON.ToString());
                foreach (var jsonObj in jsonFullObj)
                {
                    var obj = jsonObj;
                    string clientCode = (string)obj["Headers"][0]["ClientCode"].ToString();
                    string emailParamCode = (string)obj["Headers"][0]["EmailParamCode"].ToString();
                    string docType = (string)obj["Headers"][0]["DocType"].ToString();
                    string fileName = (string)obj["Headers"][0]["FileName"].ToString();
                    string compCode = (string)obj["Headers"][0]["CompanyCode"].ToString();
                    string toEmailId = (string)obj["Headers"][0]["EmailId"] ?? "";

                    #region
                    if (strHeaderImage == "Y")
                    {
                        string dirPath = Path.Combine(baseDir, "Assets");
                        string headerImagePath = objUtility.GetCompanyHeaderImageAsync(dirPath, compCode);
                        jsonObj["Headers"][0]["CompHeaderImage"] = headerImagePath;
                    }
                    string jsonTypst = JsonConvert.SerializeObject(jsonObj);

                    ///// Start Typst code          
                    strPDFPath = Path.Combine(strOutputPath, ReportName + "_" + clientCode + ".pdf");
                    strJSONPath = CreateJsonConfig(jsonTypst, ReportName + "_" + clientCode + ".json");
                    strTypstCommand = $"\"{Path.Combine(baseDir, "templates", "AccountOpeningLetter.typ")}\" \"{strPDFPath}\"";
                    strJSONRelPath = Path.Combine("..", "inputs", ReportName + "_" + clientCode + ".json").Replace("\\", "/");

                    string arguments = $"compile {strTypstCommand} --input file_path={strJSONRelPath} --root \"{baseDir}\"";
                    try
                    {
                        var processStartInfo = new ProcessStartInfo
                        {
                            FileName = strTypstExePath,
                            Arguments = arguments,
                            RedirectStandardOutput = true,
                            RedirectStandardError = true,
                            UseShellExecute = false,
                            CreateNoWindow = true
                        };
                        using var process = Process.Start(processStartInfo);
                        string output = process.StandardOutput.ReadToEnd();
                        string error = process.StandardError.ReadToEnd();
                        process.WaitForExit();

                        if (process.ExitCode != 0)
                        {
                            errorCnt++;
                            continue;
                        }

                        fileBytes = File.ReadAllBytes(strPDFPath);

                        //// var model2 = JsonConvert.DeserializeObject<EmailTemplateModel>(finalJSON);
                        var ipAddress = _httpContextAccessor.HttpContext.Connection.RemoteIpAddress?.ToString();
                        string clientHostName = string.Empty;
                        if (!string.IsNullOrEmpty(ipAddress))
                        {
                            try
                            {
                                var hostEntry = Dns.GetHostEntry(ipAddress);
                                clientHostName = hostEntry.HostName;
                            }
                            catch
                            {
                                clientHostName = ipAddress; // fallback to IP
                            }
                        }

                        string emailSubject = "", emailBody = "";
                        DataTable dtEmail = new DataTable();
                        string strEmail = " SELECT  EmailSubject Emailsubject,   BodyText EmailBodyText " +
                                          " FROM  tbl_EmailTemplate (NOLOCK)   WHERE RefName IN ('AccountOpeningLetter','CommonFormat')";
                        dtEmail = objUtility.OpenDataTable(strEmail);
                        emailSubject = dtEmail.Rows[0]["Emailsubject"].ToString();
                        emailBody = dtEmail.Rows[0]["EmailBodyText"].ToString();

                        objUtility.CommonInsertEailTemplate(compCode, clientCode, docType, clientHostName, emailParamCode, toEmailId, emailSubject, emailBody, fileBytes, fileName);
                        succesCnt++;
                        if (File.Exists(strJSONPath))
                        {
                            File.Delete(strJSONPath);
                        }
                        if (strPDFPath != "" && File.Exists(strPDFPath))
                        {
                            File.Delete(strPDFPath);
                        }
                    }
                    catch
                    {
                        errorCnt++;
                    }
                    finally
                    {
                        if (strPDFPath != "" && File.Exists(strPDFPath))
                        {
                            File.Delete(strPDFPath);
                        }
                        if (File.Exists(strJSONPath))
                        {
                            File.Delete(strJSONPath);
                        }
                    }

                    #endregion
                }
                dt.Rows.Add("SUCCESS", "Successfully send email for total client: " + succesCnt);
                dt.Rows.Add("ERROR", "Error for total client: " + errorCnt);
                dsRes.Tables.Add(dt);
                dsRes.Tables[0].TableName = "rs0";
                return dsRes;
            }
            catch (Exception ex)
            {
                if (strJSONPath != "" && File.Exists(strJSONPath))
                {
                    File.Delete(strJSONPath);
                }
                throw new Exception(ex.Message.ToString());
            }
            finally
            {
                if (strPDFPath != "" && File.Exists(strPDFPath))
                {
                    File.Delete(strPDFPath);
                }
            }

        }

    }
